window.CIBER_DATA={"version":"2026-11-27-v1","days":[{"id":1,"title":"Continuidad y recuperación","subtitle":"Cinco misiones para mantener el servicio y demostrar la recuperación","missions":[{"id":1,"slug":"puerto","title":"Puerto de guardia","block":"Qué debe seguir funcionando","description":"Priorizamos embarques, comprobamos dependencias y defendemos un servicio mínimo medible.","originalSlide":19,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/continuidad/puerto.html","minutes":30,"concepts":[{"term":"Ciberresiliencia","definition":"Capacidad de anticipar, resistir, recuperar y adaptarse ante problemas de los recursos digitales.","example":"Una farmacia prepara alternativas, atiende lo esencial, recupera el sistema y corrige lo que falló."},{"term":"Continuidad","definition":"Capacidad de mantener actividades prioritarias durante una interrupción.","example":"Una oficina atiende citas urgentes mediante un procedimiento alternativo preparado."},{"term":"Activo","definition":"Elemento con valor que contribuye a los objetivos de la organización.","example":"Los datos, el personal, una grúa y un procedimiento pueden ser activos."},{"term":"Dependencia","definition":"Recurso, persona, servicio o condición necesaria para otra actividad.","example":"La entrega necesita conexión y autorización."},{"term":"Amenaza","definition":"Causa potencial de un incidente perjudicial.","example":"Un corte de energía puede detener la atención."},{"term":"Vulnerabilidad","definition":"Debilidad que puede permitir o agravar un incidente.","example":"Tener una única alimentación agrava el efecto del corte."},{"term":"Impacto","definition":"Consecuencia del suceso sobre personas, servicios u objetivos.","example":"Perder una ventana de embarque retrasa la entrega sanitaria."},{"term":"Exposición","definition":"Condición de quedar accesible a determinados actores o entornos.","example":"Una cuenta remota sigue accesible aunque ya no se necesite."},{"term":"Superficie de ataque","definition":"Puntos desde los que se puede intentar acceder, afectar a un sistema o extraer información.","example":"Incluye el portal público y los accesos remotos del proveedor."},{"term":"BIA","definition":"Business Impact Analysis. Análisis de las consecuencias de una interrupción a lo largo del tiempo.","example":"Un pedido puede esperar hoy, pero no después del cierre de embarque."},{"term":"Prioridad","definition":"Orden de atención justificado por necesidades y consecuencias.","example":"Una carga urgente con plazo cercano se atiende antes que otra que puede esperar."},{"term":"Dependencia común","definition":"Elemento compartido cuyo fallo puede afectar a varias alternativas.","example":"Dos conexiones requieren el mismo directorio de autorización."},{"term":"Redundancia","definition":"Disponibilidad de recursos adicionales para soportar ciertos fallos.","example":"Un enlace alternativo ayuda si conserva su funcionamiento ante el fallo ensayado."},{"term":"Servicio mínimo","definition":"Capacidad y condiciones que deben conservarse durante la interrupción.","example":"Completar catorce pedidos incluyendo los siete urgentes."},{"term":"Criterio de aceptación","definition":"Condición observable que permite decidir si el resultado cumple lo acordado.","example":"Entregar todos los urgentes antes del cierre."},{"term":"Capacidad","definition":"Trabajo que un recurso o ruta puede completar en un intervalo definido.","example":"Una ruta procesa doce pedidos por ventana."},{"term":"Autorización","definition":"Permiso necesario para acceder a un recurso o realizar una operación.","example":"El responsable habilita una salida de carga tras la comprobación requerida."},{"term":"Riesgo residual","definition":"Riesgo que permanece tras las medidas aplicadas.","example":"La ruta alternativa conserva urgentes, pero aún puede retrasar pedidos ordinarios."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d1m1q01","kind":"concepto","title":"El servicio que importa","scenario":"Caso docente. El sistema del puerto deja de responder, pero todavía hay personal, mercancía y medios alternativos.","prompt":"¿Qué objetivo expresa mejor la continuidad?","terms":["Continuidad","Servicio mínimo"],"options":[{"text":"Mantener los embarques prioritarios con condiciones y capacidad acordadas.","feedback":"Correcto. El objetivo se refiere al resultado para las personas y establece qué capacidad se conserva."},{"text":"Anotar únicamente qué aplicaciones están caídas.","feedback":"El inventario ayuda, pero no establece qué actividad debe seguir funcionando."},{"text":"Encender todos los equipos antes de entregar nada.","feedback":"Esperar a recuperar cada equipo puede interrumpir actividades que ya podrían continuar con alternativas."},{"text":"Mantener el mismo volumen a cualquier precio y sin controles.","feedback":"Una alternativa debe respetar condiciones esenciales, como autorización y trazabilidad."}],"correct":0,"takeaway":"La continuidad conserva actividades prioritarias y condiciones esenciales durante la interrupción."},{"id":"d1m1q02","kind":"concepto","title":"Cuatro capacidades","scenario":"Caso docente. Tras un corte, el puerto cambia el procedimiento y ensaya una autorización alternativa que antes no tenía.","prompt":"¿Qué capacidad de ciberresiliencia representa principalmente ese cambio?","terms":["Ciberresiliencia"],"options":[{"text":"Resistir, porque todavía está atendiendo pedidos.","feedback":"Resistir consiste en sostener capacidad durante la perturbación. Aquí el foco es cambiar la preparación futura."},{"text":"Anticipar, porque el ataque aún no ha ocurrido.","feedback":"El corte ya ocurrió. Se aprende de él y se modifica la organización."},{"text":"Adaptarse a partir de lo aprendido.","feedback":"Correcto. La organización convierte la experiencia en una capacidad diferente y comprobable."},{"text":"Recuperar, porque vuelve la electricidad.","feedback":"El enunciado describe una mejora del procedimiento posterior, no solo restablecer capacidad."}],"correct":2,"takeaway":"Anticipar, resistir, recuperar y adaptarse son capacidades relacionadas que se entrenan con decisiones concretas."},{"id":"d1m1q03","kind":"concepto","title":"Más que equipos","scenario":"Caso docente. El inventario incluye servidores y grúas. Solo una persona sabe autorizar cargas sanitarias y el procedimiento vive en su memoria.","prompt":"¿Qué falta reconocer como activo y dependencia?","terms":["Activo","Dependencia"],"options":[{"text":"Nada: los activos siempre son objetos físicos.","feedback":"También tienen valor los datos, los procedimientos y las capacidades humanas."},{"text":"El conocimiento, la persona y el procedimiento de autorización.","feedback":"Correcto. Los activos incluyen información, personas y procedimientos que sostienen el servicio."},{"text":"El número de alertas del antivirus de las grúas.","feedback":"Ese dato no cubre la dependencia de autorización descrita."},{"text":"Únicamente el modelo del portátil de esa persona.","feedback":"El portátil no sustituye su conocimiento ni la autoridad necesaria para operar."}],"correct":1,"takeaway":"Un inventario útil recoge lo necesario para prestar el servicio, incluido conocimiento y autoridad."},{"id":"d1m1q04","kind":"concepto","title":"Tres palabras diferentes","scenario":"Caso docente. Una excavadora puede cortar el único cable del puerto y provocar que se pierda una ventana de embarque.","prompt":"¿Qué clasificación es correcta?","terms":["Amenaza","Vulnerabilidad","Impacto"],"options":[{"text":"Los tres términos significan lo mismo si hay una caída.","feedback":"Separarlos permite escoger medidas que actúen sobre causas y consecuencias distintas."},{"text":"Amenaza: corte. Vulnerabilidad: vía única. Impacto: embarque perdido.","feedback":"Correcto. Se separan la causa potencial, la debilidad y el daño sobre el servicio."},{"text":"Amenaza: cable único. Vulnerabilidad: ventana perdida. Impacto: excavadora.","feedback":"Se mezclan causa, debilidad y consecuencia. Identifica primero qué puede causar daño."},{"text":"Amenaza: ventana perdida. Vulnerabilidad: excavadora. Impacto: cable único.","feedback":"La ventana perdida es la consecuencia. El cable único es la debilidad que agrava el corte."}],"correct":1,"takeaway":"La amenaza puede causar daño, la vulnerabilidad lo facilita o agrava y el impacto es su consecuencia."},{"id":"d1m1q05","kind":"concepto","title":"Una prioridad defendible","scenario":"Caso docente. El puerto debe decidir entre restaurar facturación interna y autorizar medicamentos con temperatura controlada.","prompt":"¿Qué aporta un BIA a esta decisión?","terms":["BIA","Prioridad"],"options":[{"text":"La certeza de que el incidente no se repetirá.","feedback":"El BIA analiza impacto. No garantiza la ausencia de incidentes futuros."},{"text":"Las consecuencias de detener cada actividad y cómo cambian con el tiempo.","feedback":"Correcto. Esa evolución permite justificar prioridades y tiempos aceptables."},{"text":"Una lista de aplicaciones ordenada por su precio de compra.","feedback":"El precio no muestra cuándo una interrupción perjudica a usuarios o incumple necesidades del servicio."},{"text":"Una atribución del ataque a una persona concreta.","feedback":"La atribución no es el objetivo del análisis de impacto."}],"correct":1,"takeaway":"La prioridad se justifica por necesidades, consecuencias y tiempo, no por el brillo del equipo."},{"id":"d1m1q06","kind":"concepto","title":"La segunda vía","scenario":"Caso docente. Dos conexiones usan proveedores distintos, pero ambas necesitan el mismo directorio para validar cada orden.","prompt":"¿Qué debe comprobarse antes de llamarlas alternativas independientes?","terms":["Dependencia común","Redundancia"],"options":[{"text":"Que ambas conexiones sean más rápidas que la principal.","feedback":"La velocidad no elimina un directorio compartido como punto de fallo."},{"text":"Qué recursos y autorizaciones comparten y qué ocurre si fallan.","feedback":"Correcto. Una prueba del fallo compartido descubre si existe independencia útil para ese escenario."},{"text":"Solo que las facturas lleven logotipos distintos.","feedback":"La diversidad comercial no demuestra separación de los puntos cuyo fallo bloquea el servicio."},{"text":"Que los cables tengan distinto color.","feedback":"La apariencia no prueba independencia técnica ni operativa."}],"correct":1,"takeaway":"La redundancia solo protege frente a los fallos para los que conserva caminos operativos."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d1m1q07","kind":"caso","title":"Catorce pedidos, siete urgentes","scenario":"Caso docente. El mínimo de la ventana es completar 14 pedidos e incluir los 7 urgentes. Un plan entrega 16, de los que 6 son urgentes.","prompt":"¿Se ha cumplido el servicio mínimo?","terms":["Servicio mínimo","Criterio de aceptación"],"options":[{"text":"Sí, porque 16 supera 14.","feedback":"El criterio combina volumen y prioridad. Falta un pedido urgente."},{"text":"No, porque falta uno de los siete pedidos urgentes.","feedback":"Correcto. Se satisface el volumen, pero se incumple la condición de prioridad."},{"text":"No se puede evaluar sin conocer el precio de cada pedido.","feedback":"El criterio de aceptación está completamente definido por cantidad y urgentes incluidos."},{"text":"No, porque deberían entregarse exactamente 14.","feedback":"Catorce es el mínimo, no un máximo. Superarlo sería válido si se incluyeran todos los urgentes."}],"correct":1,"takeaway":"Una cifra total alta puede ocultar el incumplimiento de una condición crítica.","visual":{"type":"metrics","items":[{"label":"Mínimo","value":"14"},{"label":"Urgentes exigidos","value":"7"},{"label":"Resultado","value":"16 / 6 urgentes"}]}},{"id":"d1m1q08","kind":"caso","title":"La ruta está viva","scenario":"Caso docente. La fibra funciona y puede transportar 30 órdenes. El directorio de autorizaciones sigue caído y no existe procedimiento alternativo aprobado.","prompt":"¿Qué resultado cabe esperar para órdenes que exigen autorización?","terms":["Dependencia","Autorización"],"options":[{"text":"Se completarán si se quita el campo de autorización.","feedback":"Eso cambia las condiciones del servicio sin una alternativa aprobada y puede permitir operaciones indebidas."},{"text":"No pueden completarse aunque la conexión tenga capacidad.","feedback":"Correcto. El permiso es una condición necesaria del servicio, no un detalle de la conexión."},{"text":"Se completarán todas al abrir otra ventana del navegador.","feedback":"Cambiar la interfaz no restablece la dependencia de autorización."},{"text":"Se completarán 30 porque ese es el ancho de banda.","feedback":"La capacidad de una etapa no elimina el bloqueo de una condición necesaria."}],"correct":1,"takeaway":"Un componente disponible no demuestra que el servicio completo esté disponible.","visual":{"type":"metrics","items":[{"label":"Ruta","value":"30 órdenes"},{"label":"Autorización","value":"Caída"},{"label":"Alternativa","value":"No preparada"}]}},{"id":"d1m1q09","kind":"caso","title":"Capacidad alternativa","scenario":"Caso docente. Hay 18 pedidos pendientes, 6 urgentes. Una ruta alternativa permite completar 12 y la autorización funciona. Todos los pedidos consumen una unidad.","prompt":"¿Qué plan cumple un mínimo de 10 pedidos con todos los urgentes?","terms":["Servicio mínimo","Capacidad"],"options":[{"text":"Nueve ordinarios y un urgente.","feedback":"Alcanza diez, pero deja cinco urgentes sin atender."},{"text":"Seis urgentes y doce ordinarios.","feedback":"Ese plan requiere dieciocho unidades, pero solo hay capacidad para doce."},{"text":"Seis urgentes y seis ordinarios.","feedback":"Correcto. Usa las doce unidades disponibles, supera diez e incluye todos los urgentes."},{"text":"Doce ordinarios, porque maximizan el volumen.","feedback":"Se omiten los seis urgentes exigidos por el criterio."}],"correct":2,"takeaway":"La asignación de capacidad debe respetar las prioridades antes de completar el resto.","visual":{"type":"metrics","items":[{"label":"Pendientes","value":"18"},{"label":"Capacidad","value":"12"},{"label":"Urgentes","value":"6"}]}},{"id":"d1m1q10","kind":"caso","title":"Dos fibras, una excavación","scenario":"Caso docente. Fibra norte y fibra sur atraviesan la misma canalización. El escenario que debemos soportar es la rotura de esa canalización.","prompt":"¿Qué alternativa aporta diversidad frente a ese fallo?","terms":["Dependencia común","Redundancia"],"options":[{"text":"Comprar más capacidad en ambas fibras.","feedback":"La capacidad adicional no ayuda si el camino físico queda interrumpido."},{"text":"Duplicar el router manteniendo los dos cables actuales.","feedback":"Puede cubrir un fallo del router. No resuelve el corte de la canalización."},{"text":"Contratar otra fibra dentro de la misma canalización.","feedback":"Aumenta recursos expuestos al mismo corte, pero no evita el punto de fallo compartido."},{"text":"Un radioenlace con energía y autorización verificadas por vías operativas.","feedback":"Correcto. Cambia el camino físico y comprueba otras dependencias necesarias."}],"correct":3,"takeaway":"La independencia se evalúa frente al fallo concreto, incluidas las dependencias que quedan."},{"id":"d1m1q11","kind":"caso","title":"El reloj cambia la prioridad","scenario":"Caso docente. La carga A pierde su ventana en 20 minutos. La B puede esperar 3 horas sin incumplimiento. Ambas necesitan el mismo equipo y tardan 15 minutos.","prompt":"¿Qué secuencia respeta mejor las consecuencias temporales?","terms":["BIA","Prioridad"],"options":[{"text":"Elegir al azar para que el reparto sea neutral.","feedback":"Conocer los plazos permite evitar un perjuicio previsible."},{"text":"Esperar 20 minutos para tener más información, aunque no falte ningún dato.","feedback":"La espera consumiría la ventana crítica sin aportar una comprobación necesaria."},{"text":"Primero B, porque tiene más margen.","feedback":"Usar el margen de B como prioridad puede hacer que A pierda su ventana sin necesidad."},{"text":"Primero A y después B, registrando el criterio.","feedback":"Correcto. A termina dentro de su ventana y B conserva margen suficiente."}],"correct":3,"takeaway":"La prioridad puede cambiar con el tiempo aunque los activos físicos sean los mismos.","visual":{"type":"metrics","items":[{"label":"Carga A","value":"20 min"},{"label":"Carga B","value":"180 min"},{"label":"Trabajo por carga","value":"15 min"}]}},{"id":"d1m1q12","kind":"caso","title":"La entrada olvidada","scenario":"Caso docente. El portal público está protegido, pero un proveedor conserva una cuenta remota que ya no necesita.","prompt":"¿Qué revisión aborda directamente la exposición descrita?","terms":["Exposición","Superficie de ataque"],"options":[{"text":"Revisar la necesidad de ese acceso y retirar permisos innecesarios.","feedback":"Correcto. Se reduce un punto accesible y se alinea el permiso con una necesidad actual."},{"text":"Cerrar el registro de accesos para generar menos alertas.","feedback":"Reduce visibilidad y mantiene la exposición."},{"text":"Suponer que los proveedores nunca pueden sufrir compromisos.","feedback":"La confianza comercial no elimina la posibilidad de que una cuenta se use indebidamente."},{"text":"Añadir memoria al servidor del portal.","feedback":"La memoria no modifica el acceso remoto sobrante."}],"correct":0,"takeaway":"La superficie de ataque incluye accesos de terceros y cuentas, además de páginas públicas."},{"id":"d1m1q13","kind":"caso","title":"Lo que aún queda fuera","scenario":"Caso docente. La alternativa cumple el mínimo sanitario, pero deja cuatro pedidos ordinarios para la siguiente ventana. El límite acordado admite ese retraso.","prompt":"¿Qué debe registrar el responsable?","terms":["Riesgo residual","Criterio de aceptación"],"options":[{"text":"Solo el color verde del panel.","feedback":"Un color no permite reconstruir la limitación ni su aceptación."},{"text":"Que ya no queda ningún riesgo porque el mínimo se cumple.","feedback":"Cumplir el mínimo no hace desaparecer consecuencias pendientes ni la posibilidad de otros fallos."},{"text":"Que todos los pedidos se entregaron para no preocupar al relevo.","feedback":"Eso contradice el resultado y elimina información necesaria para continuar el trabajo."},{"text":"Los cuatro pedidos pendientes, sus consecuencias, el responsable y la próxima revisión.","feedback":"Correcto. El riesgo restante queda visible y sujeto a seguimiento."}],"correct":3,"takeaway":"Una recuperación parcial debe describir lo conseguido y lo que sigue pendiente.","visual":{"type":"metrics","items":[{"label":"Urgentes","value":"Completados"},{"label":"Ordinarios","value":"4 pendientes"},{"label":"Revisión","value":"Siguiente ventana"}]}},{"id":"d1m1q14","kind":"caso","title":"El cambio que permite aprender","scenario":"Caso docente. Una partida falla porque la ruta y su respaldo comparten autorización. Queréis comprobar si otra autorización mejora el resultado.","prompt":"¿Qué comparación permite atribuir mejor el cambio?","terms":["Dependencia común","Criterio de aceptación"],"options":[{"text":"Mantener escenario y decisiones, cambiando solo la autorización estudiada.","feedback":"Correcto. Se aísla la variable y se comparan resultados bajo condiciones equivalentes."},{"text":"Elegir únicamente la captura más favorable de cada partida.","feedback":"Seleccionar resultados favorables oculta las condiciones reales de comparación."},{"text":"Comparar una partida de veinte pedidos con otra de dos.","feedback":"La diferencia de demanda impide atribuir el cambio solo a la autorización."},{"text":"Cambiar a la vez demanda, ruta, criterio y autorización.","feedback":"Con varios cambios simultáneos no sabréis cuál explica el resultado."}],"correct":0,"takeaway":"Ensayar una hipótesis exige controlar qué cambia y medir el mismo criterio."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d1m1q15","kind":"reto","title":"Reto: servicio mínimo","scenario":"Caso docente. Una universidad debe permitir 40 matrículas válidas por hora durante una caída, con comprobación de identidad y registro recuperable.","prompt":"¿Qué propuesta cumple la definición de servicio mínimo?","terms":["Servicio mínimo","Autorización"],"options":[{"text":"Un circuito alternativo ensayado que completa al menos 40 matrículas válidas por hora y conserva su registro.","feedback":"Correcto. Se conservan capacidad, identidad y trazabilidad en el resultado del servicio."},{"text":"Encender todos los servidores aunque nadie pueda matricularse.","feedback":"Describe componentes, no el resultado útil exigido."},{"text":"Atender 50 formularios sin comprobar quién los presenta.","feedback":"Mejora el volumen aparente, pero incumple una condición esencial."},{"text":"Aceptar cualquier volumen siempre que la web muestre una pantalla de bienvenida.","feedback":"La página visible no demuestra capacidad ni operaciones válidas."}],"correct":0,"takeaway":"Un mínimo defendible une cantidad, calidad y condiciones de operación."},{"id":"d1m1q16","kind":"reto","title":"Reto: una mejora tras el fallo","scenario":"Caso docente. Un servicio recupera sus datos y después cambia las pruebas para detectar antes un directorio compartido.","prompt":"¿Qué distinción explica ambas acciones?","terms":["Ciberresiliencia"],"options":[{"text":"Ambas acciones son únicamente prevenir y no tienen relación con recuperación.","feedback":"La primera acción restablece capacidad perdida, que corresponde a recuperación."},{"text":"Recuperar significa aceptar que no se volverá a prestar el servicio.","feedback":"Recuperar implica restablecer una capacidad o servicio con condiciones comprobadas."},{"text":"Restaurar la capacidad es recuperar. Cambiar las pruebas con lo aprendido es adaptarse.","feedback":"Correcto. Son capacidades complementarias con resultados observables distintos."},{"text":"Adaptarse consiste solo en comprar equipos nuevos.","feedback":"También se cambian procesos, comprobaciones y decisiones."}],"correct":2,"takeaway":"La mejora posterior importa cuando se convierte en una capacidad comprobable."},{"id":"d1m1q17","kind":"reto","title":"Reto: dos alternativas","scenario":"Caso docente. Dos centros de atención tienen edificios, redes y equipos distintos. Ambos dependen de la misma persona para activar el modo manual y no hay suplente.","prompt":"¿Cuál es la conclusión mejor sustentada?","terms":["Dependencia común","Activo"],"options":[{"text":"La separación de edificios garantiza la continuidad ante cualquier fallo.","feedback":"La separación física no elimina una dependencia humana compartida."},{"text":"Las personas nunca se incluyen en un análisis de dependencias.","feedback":"Los conocimientos, disponibilidad y autoridad pueden ser condiciones necesarias."},{"text":"El problema se resuelve cambiando el nombre de los centros.","feedback":"El nombre no cambia quién puede activar el procedimiento."},{"text":"Existe una dependencia común de autoridad que debe cubrirse y ensayarse.","feedback":"Correcto. La misma persona puede bloquear ambas alternativas aunque la tecnología esté separada."}],"correct":3,"takeaway":"Las dependencias comunes pueden ser humanas, organizativas o técnicas."},{"id":"d1m1q18","kind":"reto","title":"Reto: impacto y riesgo","scenario":"Caso docente. Una biblioteca describe que una caída podría impedir préstamos durante un día y estudia la posibilidad de que ocurra y sus consecuencias.","prompt":"¿Qué afirmación diferencia mejor impacto y riesgo?","terms":["Impacto","Riesgo residual"],"options":[{"text":"Si hay una copia, el riesgo se vuelve cero por definición.","feedback":"Una copia puede reducir consecuencias, pero deben evaluarse condiciones, tiempos y otros fallos."},{"text":"Impacto es la probabilidad exacta de que alguien ataque.","feedback":"El impacto describe consecuencias. La probabilidad no se convierte en exacta por estimarla."},{"text":"El impacto es el perjuicio del servicio detenido. El riesgo considera ese escenario y la incertidumbre sobre su ocurrencia y consecuencias.","feedback":"Correcto. Se distinguen el efecto y la valoración del escenario que podría producirlo."},{"text":"Riesgo significa que la caída ya sucedió necesariamente.","feedback":"Un riesgo puede referirse a un escenario posible bajo incertidumbre."}],"correct":2,"takeaway":"Hablar de riesgo exige conectar el escenario, sus consecuencias y la incertidumbre."}]}],"sources":[{"title":"Presentación docente, día 1, diapositivas 2–18","url":""},{"title":"NIST SP 800-160 Vol. 2 Rev. 1","url":"https://csrc.nist.gov/pubs/sp/800/160/v2/r1/final"},{"title":"NIST SP 800-34 Rev. 1","url":"https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final"}]},{"id":2,"slug":"laminacion","title":"Turno de laminación","block":"Continuidad durante la interrupción","description":"Ajustamos personal y capacidad sin perder el rastro de cada lote y cada registro.","originalSlide":49,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/continuidad/flujo.html","minutes":30,"concepts":[{"term":"Plan de continuidad","definition":"Instrucciones y recursos para mantener actividades prioritarias durante una interrupción.","example":"Describe cuándo pasar a pedidos manuales, quién autoriza y qué se registra."},{"term":"Modo degradado","definition":"Servicio reducido que conserva las condiciones esenciales acordadas.","example":"Se atienden menos pedidos por hora, con identificación y registro."},{"term":"Cola","definition":"Operaciones que esperan a ser atendidas.","example":"Si llegan doce pedidos y salen ocho por minuto, se acumulan cuatro."},{"term":"Demanda","definition":"Cantidad de trabajo que llega a un servicio en un intervalo.","example":"Llegan veinte solicitudes cada hora."},{"term":"Capacidad","definition":"Trabajo que un recurso puede completar por unidad de tiempo.","example":"El puesto de comprobación verifica ocho pedidos por minuto."},{"term":"Cuello de botella","definition":"Etapa o recurso que limita el ritmo del conjunto.","example":"Una revisión lenta limita la salida aunque recepción sea rápida."},{"term":"Media","definition":"Suma de valores dividida entre el número de observaciones.","example":"Nueve esperas de uno y una de once minutos producen una media de dos."},{"term":"P95","definition":"Percentil 95. Valor que sitúa el 95 % de las observaciones ordenadas según el método indicado.","example":"Con rango más próximo y cien datos, se toma el dato de la posición 95."},{"term":"Disponibilidad","definition":"Acceso y uso del servicio cuando se necesita.","example":"La persona puede completar un pedido dentro de las condiciones previstas."},{"term":"Integridad","definition":"Protección de la información frente a cambios indebidos o errores.","example":"El pedido conserva la cantidad correcta."},{"term":"Confidencialidad","definition":"Protección frente al acceso o divulgación no autorizados.","example":"Los datos del cliente solo se muestran a quien corresponde."},{"term":"Trazabilidad","definition":"Posibilidad de reconstruir qué ocurrió, cuándo, quién intervino y con qué resultado.","example":"Un folio contiene pedido, hora, responsable y estado."},{"term":"Conciliación","definition":"Comparación de registros para resolver omisiones, diferencias o duplicados.","example":"Se contrasta cada folio con lo ya incorporado al sistema."},{"term":"Control","definition":"Medida técnica, humana u organizativa que modifica un riesgo.","example":"Revisar permisos previene usos indebidos y probar una copia prepara la recuperación."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d1m2q01","kind":"concepto","title":"Un plan que se puede activar","scenario":"Caso docente. La fábrica tiene un documento de ochenta páginas, pero nadie sabe quién puede pasar a pedidos manuales.","prompt":"¿Qué falta para que el plan sea operativo?","terms":["Plan de continuidad"],"options":[{"text":"La garantía de que nunca habrá una interrupción.","feedback":"Un plan prepara la actuación cuando ocurre una interrupción, no garantiza que sea imposible."},{"text":"Condición de activación, responsable, alternativa, registro y revisión.","feedback":"Correcto. Esos elementos permiten iniciar, ejecutar y evaluar una respuesta concreta."},{"text":"Una descripción de la historia de la fábrica.","feedback":"El contexto no sustituye condiciones de activación, autoridad y procedimiento."},{"text":"Otra portada con el logotipo más grande.","feedback":"La portada no establece quién decide ni cómo activar la alternativa."}],"correct":1,"takeaway":"El plan necesita decisiones ejecutables, responsables y comprobaciones."},{"id":"d1m2q02","kind":"concepto","title":"Trabajar con menos capacidad","scenario":"Caso docente. El sistema automático cae. Se preparan pedidos numerados en papel, con límites de volumen y comprobación de identidad.","prompt":"¿Cómo se describe esta alternativa?","terms":["Modo degradado","Trazabilidad"],"options":[{"text":"Ausencia de continuidad porque no se usa software.","feedback":"La continuidad puede apoyarse en personas y procedimientos manuales."},{"text":"Recuperación total porque ya existe actividad.","feedback":"El servicio todavía funciona con una alternativa y menor capacidad."},{"text":"Modo degradado con condiciones esenciales conservadas.","feedback":"Correcto. Se reduce capacidad, pero se conserva el resultado aceptable y su control."},{"text":"Permiso para omitir controles durante toda la caída.","feedback":"Trabajar de otra forma no elimina las condiciones de calidad, identidad o registro."}],"correct":2,"takeaway":"El modo degradado permite seguir atendiendo bajo límites explícitos."},{"id":"d1m2q03","kind":"concepto","title":"La etapa que manda","scenario":"Caso docente. Recepción, comprobación y entrega trabajan en serie. Todo pedido debe pasar por las tres.","prompt":"¿Qué determina el ritmo estable máximo si no faltan pedidos ni materiales?","terms":["Cuello de botella","Capacidad"],"options":[{"text":"La capacidad de la etapa más rápida.","feedback":"La etapa rápida tendrá que esperar a la que procesa menos."},{"text":"La capacidad de la etapa que limita el conjunto.","feedback":"Correcto. La etapa más lenta impone el límite bajo las condiciones descritas."},{"text":"La suma de las capacidades de las tres etapas.","feedback":"En una cadena cada pedido necesita todas las etapas. Sus ritmos no se suman."},{"text":"La cantidad de pantallas instaladas.","feedback":"Las pantallas no indican el ritmo efectivo del proceso."}],"correct":1,"takeaway":"Mejorar una etapa no limitante puede no aumentar la salida del servicio."},{"id":"d1m2q04","kind":"concepto","title":"La media y la espera larga","scenario":"Caso docente. Nueve operaciones tardan un minuto y una tarda once.","prompt":"¿Qué lectura describe correctamente la media?","terms":["Media","P95"],"options":[{"text":"Todas las personas esperaron exactamente dos minutos.","feedback":"La media resume. No describe el tiempo individual de cada persona."},{"text":"La media es once minutos porque ese es el peor caso.","feedback":"Once es el máximo, no la media."},{"text":"La media es diez minutos porque hay diez operaciones.","feedback":"El número de operaciones es el denominador. Debe dividir la suma de tiempos."},{"text":"La media es dos minutos, pero una persona esperó once.","feedback":"Correcto. La suma es veinte minutos entre diez operaciones. La distribución sigue siendo desigual."}],"correct":3,"takeaway":"Un promedio aceptable puede convivir con esperas importantes para algunos usuarios.","visual":{"type":"metrics","items":[{"label":"Operaciones","value":"10"},{"label":"Nueve tiempos","value":"1 min"},{"label":"Un tiempo","value":"11 min"}]}},{"id":"d1m2q05","kind":"concepto","title":"Tres condiciones del pedido","scenario":"Caso docente. La alternativa permite entregar pedidos, pero intercambia cantidades y deja los datos de clientes a la vista de cualquiera.","prompt":"¿Qué lectura es correcta?","terms":["Disponibilidad","Integridad","Confidencialidad"],"options":[{"text":"Hay actividad, pero fallan integridad y confidencialidad.","feedback":"Correcto. Las cantidades incorrectas afectan a la integridad y la exposición de datos a la confidencialidad."},{"text":"Solo importa la disponibilidad porque los pedidos salen.","feedback":"También importan que sean correctos y que la información no se divulgue sin autorización."},{"text":"La integridad significa únicamente que el papel no está roto.","feedback":"Aquí integridad se refiere a la información y a cambios o errores indebidos."},{"text":"La confidencialidad es correcta porque los datos están impresos.","feedback":"El soporte de papel también puede exponer información a personas no autorizadas."}],"correct":0,"takeaway":"Mantener actividad exige conservar las condiciones esenciales de información y servicio."},{"id":"d1m2q06","kind":"concepto","title":"La deuda de papel","scenario":"Caso docente. Durante la caída se atienden pedidos con folios numerados. Al volver el sistema hay que comparar lo registrado por ambas vías.","prompt":"¿Qué significa conciliar?","terms":["Conciliación","Trazabilidad"],"options":[{"text":"Cambiar todos los identificadores para que parezcan nuevos.","feedback":"Eso dificulta relacionar las operaciones y detectar duplicados."},{"text":"Destruir el papel en cuanto aparece la pantalla de acceso.","feedback":"Todavía puede contener operaciones que no están en el sistema."},{"text":"Copiar cada folio dos veces para estar más seguros.","feedback":"Duplicar registros puede crear justamente el error que se pretende evitar."},{"text":"Comparar registros y resolver omisiones, diferencias o duplicados.","feedback":"Correcto. Se reconstruye el resultado sin perder operaciones ni contarlas dos veces."}],"correct":3,"takeaway":"Una alternativa manual debe incluir cómo se incorporará y comprobará su información."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d1m2q07","kind":"caso","title":"La cola crece","scenario":"Caso docente. La cola empieza con 10 pedidos. Durante 5 minutos llegan 12 pedidos por minuto y se completan 8 por minuto. No hay cancelaciones.","prompt":"¿Cuántos quedan al final?","terms":["Cola","Demanda","Capacidad"],"options":[{"text":"10 pedidos.","feedback":"La entrada supera la salida en cuatro pedidos cada minuto."},{"text":"60 pedidos.","feedback":"Sesenta son las llegadas. También se completan cuarenta y había diez al inicio."},{"text":"20 pedidos.","feedback":"Eso cuenta solo el crecimiento de cinco minutos y olvida los diez iniciales."},{"text":"30 pedidos.","feedback":"Correcto. Cola final = 10 + 5 × (12 − 8) = 30."}],"correct":3,"takeaway":"La cola acumula la diferencia entre trabajo que llega y trabajo que se completa.","visual":{"type":"metrics","items":[{"label":"Cola inicial","value":"10"},{"label":"Llegadas","value":"12/min"},{"label":"Salida","value":"8/min"},{"label":"Tiempo","value":"5 min"}]}},{"id":"d1m2q08","kind":"caso","title":"Personal donde cambia el resultado","scenario":"Caso docente. Las etapas tienen capacidades de 12, 6 y 10 lotes por hora. Un refuerzo permite sumar 3 lotes por hora a una sola etapa.","prompt":"¿Dónde aumenta más el ritmo del conjunto?","terms":["Cuello de botella","Capacidad"],"options":[{"text":"En comprobación, para pasar de 6 a 9.","feedback":"Correcto. El límite del conjunto sube de seis a nueve, sin superar las otras capacidades."},{"text":"En cualquier etapa, porque las capacidades siempre se suman.","feedback":"Son etapas en serie y cada lote debe recorrerlas todas."},{"text":"En recepción, para pasar de 12 a 15.","feedback":"La comprobación seguiría limitada a seis, así que el conjunto no mejoraría."},{"text":"En entrega, para pasar de 10 a 13.","feedback":"La comprobación seguiría siendo el límite de seis."}],"correct":0,"takeaway":"Asignar recursos al cuello de botella puede elevar la capacidad útil.","visual":{"type":"metrics","items":[{"label":"Recepción","value":"12/h"},{"label":"Comprobación","value":"6/h"},{"label":"Entrega","value":"10/h"}]}},{"id":"d1m2q09","kind":"caso","title":"Calcular el P95","scenario":"Caso docente. Hay 100 tiempos ordenados. Los primeros 95 son de 7 minutos y los últimos 5 son de 20. Usamos el método del rango más próximo: posición ceil(0,95 × N).","prompt":"¿Cuál es el P95?","terms":["P95"],"options":[{"text":"20 minutos.","feedback":"Veinte es el máximo y corresponde a las posiciones 96 a 100."},{"text":"7 minutos.","feedback":"Correcto. La posición ceil(95) es la 95, cuyo tiempo es siete minutos."},{"text":"13,5 minutos.","feedback":"Promediar siete y veinte no aplica el método del rango especificado."},{"text":"7,65 minutos.","feedback":"Ese valor es la media ponderada, no el percentil solicitado."}],"correct":1,"takeaway":"Para interpretar un percentil hay que conocer el conjunto y el método.","visual":{"type":"metrics","items":[{"label":"Muestra","value":"100"},{"label":"Posición P95","value":"95"},{"label":"Últimas 5","value":"20 min"}]}},{"id":"d1m2q10","kind":"caso","title":"Vaciar la deuda","scenario":"Caso docente. Al recuperar el sistema quedan 24 pedidos en cola. Llegan 8 por hora y se completan 14 por hora, de forma constante.","prompt":"¿Cuánto tarda la cola en vaciarse?","terms":["Cola","Demanda","Capacidad"],"options":[{"text":"3 horas, porque 24 / 8 = 3.","feedback":"Ocho es la entrada, no la velocidad de reducción de la cola."},{"text":"4 horas.","feedback":"Correcto. La reducción neta es 14 − 8 = 6 por hora y 24 / 6 = 4."},{"text":"Nunca, porque siempre llegan pedidos.","feedback":"Puede vaciarse si la salida supera de manera sostenida a la entrada."},{"text":"Menos de 2 horas, porque 24 / 14 es menor que 2.","feedback":"Ese cálculo olvida los ocho pedidos nuevos que llegan cada hora."}],"correct":1,"takeaway":"La recuperación de una cola depende de la capacidad adicional sobre la demanda.","visual":{"type":"metrics","items":[{"label":"Pendientes","value":"24"},{"label":"Llegadas","value":"8/h"},{"label":"Salida","value":"14/h"}]}},{"id":"d1m2q11","kind":"caso","title":"Un folio con recorrido","scenario":"Caso docente. Dos turnos trabajan a mano. Un folio dice únicamente preparado, sin número, hora ni responsable.","prompt":"¿Qué registro permite reconstruir mejor la operación?","terms":["Trazabilidad"],"options":[{"text":"Identificador del pedido, momento, responsable y estado.","feedback":"Correcto. Esos campos permiten enlazar el folio con la operación y su resultado."},{"text":"El total diario, sin los pedidos que lo componen.","feedback":"El agregado no permite comprobar un pedido concreto ni resolver duplicados."},{"text":"Solo el nombre comercial del cliente, aunque tenga varios pedidos.","feedback":"Sin identificar la operación pueden confundirse pedidos diferentes."},{"text":"Un sello grande que diga urgente en todos los folios.","feedback":"La urgencia no identifica qué pedido se atendió ni quién lo hizo."}],"correct":0,"takeaway":"La trazabilidad se prepara mientras se opera, no se inventa al finalizar."},{"id":"d1m2q12","kind":"caso","title":"La pantalla vuelve antes que los datos","scenario":"Caso docente. El sistema central vuelve. Hay 18 folios pendientes de incorporar y tres pedidos ya aparecen también en el sistema.","prompt":"¿Cuál es el siguiente paso más defendible?","terms":["Conciliación","Integridad"],"options":[{"text":"Borrar los 18 folios porque el sistema ya enciende.","feedback":"La disponibilidad técnica no incorpora por sí misma lo atendido en papel."},{"text":"Comparar por identificador, resolver coincidencias y registrar las incorporaciones.","feedback":"Correcto. Se conserva la información y se evitan omisiones o duplicados."},{"text":"Importar los 18 como pedidos nuevos sin compararlos.","feedback":"Los tres existentes podrían duplicarse y generar una segunda entrega."},{"text":"Declarar cerrada la incidencia al ver el formulario de acceso.","feedback":"Todavía falta comprobar y conciliar el servicio realmente prestado."}],"correct":1,"takeaway":"Restablecer el sistema no liquida automáticamente los registros pendientes.","visual":{"type":"metrics","items":[{"label":"Folios","value":"18"},{"label":"Ya registrados","value":"3"},{"label":"Riesgo","value":"Duplicados"}]}},{"id":"d1m2q13","kind":"caso","title":"Un control en cada momento","scenario":"Caso docente. Limitamos permisos, revisamos alertas, aislamos un equipo comprometido y restauramos una copia comprobada.","prompt":"¿Qué correspondencia resulta adecuada?","terms":["Control"],"options":[{"text":"Restaurar es detectar y revisar alertas es recuperar.","feedback":"Revisar alertas ayuda a detectar. Restaurar ayuda a recuperar capacidad."},{"text":"Aislar solo sirve para mejorar el ancho de banda.","feedback":"En este escenario limita la propagación o el daño de un compromiso."},{"text":"Todos son controles preventivos porque están documentados.","feedback":"Documentar no cambia su función. Algunos detectan, responden o recuperan."},{"text":"Permisos: prevenir. Alertas: detectar. Aislamiento: responder. Restauración: recuperar.","feedback":"Correcto. La correspondencia identifica la función principal de cada acción en el ejemplo."}],"correct":3,"takeaway":"Los controles pueden actuar en momentos y sobre efectos distintos."},{"id":"d1m2q14","kind":"caso","title":"El límite del modo manual","scenario":"Caso docente. El procedimiento manual admite 20 operaciones por hora con comprobación. Llegan 28. Un encargado propone saltarse la comprobación para alcanzar 30.","prompt":"¿Qué decisión conserva mejor el servicio acordado?","terms":["Modo degradado","Plan de continuidad","Capacidad"],"options":[{"text":"Mantener la comprobación, priorizar con criterios y escalar el déficit de capacidad.","feedback":"Correcto. Se protege la condición esencial y se hace visible una limitación que exige decisión."},{"text":"Prometer que las 28 se completarán sin cambiar recursos ni proceso.","feedback":"La promesa no elimina el déficit de ocho operaciones por hora."},{"text":"Destruir los pedidos pendientes para reducir el contador.","feedback":"Reducir el registro de la cola no equivale a atender las operaciones."},{"text":"Eliminar el control sin avisar porque la cola queda más bonita.","feedback":"Reducir la cola a costa de una condición esencial puede producir operaciones inválidas."}],"correct":0,"takeaway":"El modo degradado exige comunicar y gestionar sus límites."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d1m2q15","kind":"reto","title":"Reto: dos colas","scenario":"Caso docente. Una tienda ya entregó todos los paquetes pendientes, pero conserva 25 recibos manuales sin incorporar.","prompt":"¿Cuál es la conclusión?","terms":["Cola","Conciliación","Trazabilidad"],"options":[{"text":"Hay que volver a entregar los 25 paquetes.","feedback":"Los recibos pendientes no significan que las entregas no se hayan realizado."},{"text":"La continuidad termina siempre en cuanto sale el último paquete.","feedback":"Queda trabajo de información necesario para reconstruir lo entregado."},{"text":"La cola física está vacía y sigue pendiente la conciliación de registros.","feedback":"Correcto. Son trabajos distintos y deben medirse y cerrarse con sus propios criterios."},{"text":"Los recibos no forman parte del servicio porque son papel.","feedback":"El soporte no elimina la obligación operativa de conciliar registros."}],"correct":2,"takeaway":"Conviene medir por separado operaciones pendientes y registros por conciliar."},{"id":"d1m2q16","kind":"reto","title":"Reto: una media tranquilizadora","scenario":"Caso docente. Dos turnos tienen la misma media de espera. En uno todas las personas esperan cerca de tres minutos. En otro algunas esperan veinte.","prompt":"¿Qué dato adicional ayuda a comparar el servicio?","terms":["Media","P95"],"options":[{"text":"Afirmar que los servicios son idénticos por compartir la media.","feedback":"Dos distribuciones diferentes pueden producir el mismo promedio."},{"text":"Solo volver a calcular la misma media con más decimales.","feedback":"Más decimales no muestran la dispersión ni las esperas largas."},{"text":"La distribución de esperas y un percentil calculado con el mismo método.","feedback":"Correcto. Permite observar lo que la media puede ocultar y mantener comparabilidad."},{"text":"El color del uniforme de cada turno.","feedback":"No describe la distribución de tiempos."}],"correct":2,"takeaway":"La métrica debe responder a la experiencia que queremos evaluar."},{"id":"d1m2q17","kind":"reto","title":"Reto: mejora aparente","scenario":"Caso docente. Un proceso tiene recepción a 15/h, revisión a 5/h y entrega a 12/h. Se duplica la entrega, sin cambiar las otras etapas.","prompt":"¿Qué ritmo estable máximo admite el modelo?","terms":["Cuello de botella","Capacidad"],"options":[{"text":"5 por hora, porque revisión sigue siendo el límite.","feedback":"Correcto. El recurso ampliado no era el cuello de botella."},{"text":"44 por hora, sumando 15 + 5 + 24.","feedback":"Las etapas están en serie. Sus capacidades no se suman."},{"text":"24 por hora, porque la entrega se duplica.","feedback":"La revisión sigue pudiendo completar solo cinco por hora."},{"text":"10 por hora, porque toda mejora duplica el resultado.","feedback":"Duplicar una etapa no duplica automáticamente el conjunto."}],"correct":0,"takeaway":"Para valorar una mejora hay que mirar el proceso completo.","visual":{"type":"metrics","items":[{"label":"Recepción","value":"15/h"},{"label":"Revisión","value":"5/h"},{"label":"Nueva entrega","value":"24/h"}]}},{"id":"d1m2q18","kind":"reto","title":"Reto: cierre del turno","scenario":"Caso docente. El siguiente turno recibe una aplicación operativa y un parte que dice todo bien. En realidad quedan folios y un lote sin comprobar.","prompt":"¿Qué relevo es suficiente?","terms":["Plan de continuidad","Trazabilidad","Conciliación"],"options":[{"text":"Solo una captura del escritorio encendido.","feedback":"Demuestra poco sobre pedidos, comprobaciones y registros pendientes."},{"text":"Cerrar todos los pendientes para que nadie se preocupe.","feedback":"Cambiar el estado sin completar el trabajo oculta riesgos al siguiente turno."},{"text":"Un parte con estado real, pendientes identificados, responsables y siguiente comprobación.","feedback":"Correcto. Permite continuar sin reconstruir a ciegas lo que ocurrió."},{"text":"El mismo mensaje, pero con tres signos de exclamación.","feedback":"El entusiasmo no aporta evidencia ni describe limitaciones."}],"correct":2,"takeaway":"El cierre debe dejar capacidad y pendientes comprensibles para quien continúa."}]}],"sources":[{"title":"Presentación docente, día 1, diapositivas 38–48","url":""},{"title":"NIST SP 800-34 Rev. 1","url":"https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final"},{"title":"NIST SP 800-55 Vol. 1","url":"https://csrc.nist.gov/pubs/sp/800/55/v1/final"}]},{"id":3,"slug":"copia","title":"La última copia","block":"Recuperación comprobada","description":"Elegimos datos recuperables y demostramos que tiempo, permisos y operaciones cumplen lo acordado.","originalSlide":79,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/continuidad/restauracion.html","minutes":30,"concepts":[{"term":"RTO","definition":"Recovery Time Objective. Objetivo de tiempo para restablecer la capacidad acordada.","example":"Si el objetivo es sesenta minutos, cuenta hasta que el servicio previsto está validado."},{"term":"RPO","definition":"Recovery Point Objective. Objetivo sobre el punto hasta el que deben recuperarse los datos, expresado normalmente como tiempo de pérdida tolerable.","example":"Con corte a las doce y RPO diez minutos, se busca recuperar datos hasta al menos las once y cincuenta."},{"term":"Validación","definition":"Comprobación de que el resultado satisface las condiciones previstas.","example":"Se verifica una reserva completa y sus permisos antes de reabrir."},{"term":"Réplica","definition":"Instancia de datos que se actualiza mediante sincronización.","example":"Un borrado puede propagarse a una réplica inmediata."},{"term":"Retención","definition":"Periodo durante el que se conservan versiones recuperables.","example":"Conservar versiones permite buscar un estado anterior a un error."},{"term":"Copia de seguridad","definition":"Datos conservados para permitir su recuperación.","example":"Una versión protegida permite restaurar tras una pérdida del sistema principal."},{"term":"Separación de accesos","definition":"Permisos distintos que evitan que comprometer producción otorgue control automático sobre sus copias.","example":"La cuenta de producción no puede borrar todas las versiones conservadas."},{"term":"Dependencia de recuperación","definition":"Elemento o condición que debe estar disponible para recuperar otro.","example":"La aplicación requiere datos y accesos válidos."},{"term":"Entorno confiable","definition":"Entorno preparado y comprobado para recuperar con garantías acordadas.","example":"Se revisan accesos y condiciones de compromiso antes de usar los datos restaurados."},{"term":"Runbook","definition":"Guía operativa con acciones, condiciones, comprobaciones y alternativas ante fallos.","example":"Si una copia no supera la comprobación, se detiene la apertura y se prueba la alternativa."},{"term":"Prueba funcional","definition":"Comprobación de que una operación produce el resultado previsto.","example":"Crear, confirmar y consultar una reserva de prueba."},{"term":"Permiso","definition":"Autorización para acceder a información o realizar una acción.","example":"Cada cliente solo puede modificar sus propias reservas."},{"term":"Integridad","definition":"Conservación de la información frente a cambios indebidos o errores.","example":"Las cantidades y relaciones recuperadas son coherentes y correctas."},{"term":"Conciliación","definition":"Comparación de registros para resolver diferencias, omisiones o duplicados.","example":"Los pedidos en papel se contrastan con los restaurados."},{"term":"Identificador","definition":"Dato que permite distinguir una operación de las demás.","example":"El pedido 417 mantiene el mismo número en papel y en la aplicación."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d1m3q01","kind":"concepto","title":"El reloj de recuperación","scenario":"Caso docente. La base de datos vuelve, pero todavía no se puede completar un pedido. El acuerdo exige recuperar pedidos válidos en sesenta minutos.","prompt":"¿Cuándo termina la medición del tiempo de recuperación de ese servicio?","terms":["RTO","Validación"],"options":[{"text":"Cuando aparece la primera pantalla verde.","feedback":"Ese indicador puede referirse solo a un componente."},{"text":"Cuando el administrador inicia sesión.","feedback":"Ese acceso no demuestra que usuarios y operaciones funcionen."},{"text":"Cuando se empieza a copiar la base de datos.","feedback":"Iniciar la restauración no equivale a completarla ni validarla."},{"text":"Cuando la capacidad de pedidos acordada funciona y se ha comprobado.","feedback":"Correcto. El resultado debe corresponder al servicio definido en el objetivo."}],"correct":3,"takeaway":"El alcance del RTO debe estar unido a una capacidad de servicio comprobable."},{"id":"d1m3q02","kind":"concepto","title":"El punto de los datos","scenario":"Caso docente. Se acuerda tolerar como máximo quince minutos de datos no recuperables tras una interrupción.","prompt":"¿Qué objetivo expresa ese acuerdo?","terms":["RPO","RTO"],"options":[{"text":"La capacidad de la red en megabits por segundo.","feedback":"El ancho de banda no define directamente la pérdida de datos tolerable."},{"text":"El RTO, porque ambos objetivos miden exactamente lo mismo.","feedback":"RTO se refiere al tiempo para restablecer capacidad. Aquí se habla del punto de datos recuperables."},{"text":"El RPO.","feedback":"Correcto. Expresa el objetivo sobre el punto temporal de los datos que deben poder recuperarse."},{"text":"La retención, porque indica cuánto dura una contraseña.","feedback":"La retención describe cuánto se conservan versiones recuperables, no una contraseña."}],"correct":2,"takeaway":"RTO y RPO responden a preguntas distintas sobre tiempo de servicio y datos."},{"id":"d1m3q03","kind":"concepto","title":"Otra instancia no es todo el historial","scenario":"Caso docente. Una réplica recibe automáticamente los cambios de la base principal, incluido un borrado accidental.","prompt":"¿Qué capacidad complementaria resulta útil para volver a un estado anterior válido?","terms":["Réplica","Retención","Copia de seguridad"],"options":[{"text":"Confiar en que sincronización significa integridad garantizada.","feedback":"Sincronizar también puede transmitir errores o cambios indebidos."},{"text":"Cambiar el nombre del servidor replicado.","feedback":"El nombre no altera qué datos se sincronizan."},{"text":"Una segunda réplica que aplique inmediatamente el mismo borrado.","feedback":"También podría reproducir el cambio dañino."},{"text":"Versiones históricas recuperables y una restauración probada.","feedback":"Correcto. Permiten buscar un punto anterior al borrado y comprobar su uso."}],"correct":3,"takeaway":"La protección debe cubrir el fallo concreto, incluida la propagación de cambios dañinos."},{"id":"d1m3q04","kind":"concepto","title":"La llave que abre todas las puertas","scenario":"Caso docente. La cuenta que administra producción también puede borrar todas las copias históricas.","prompt":"¿Qué debilidad conviene reducir?","terms":["Separación de accesos","Copia de seguridad"],"options":[{"text":"Que comprometer una misma cuenta permita destruir producción y recuperación.","feedback":"Correcto. Separar accesos reduce ese camino de fallo común."},{"text":"Que existan demasiadas versiones para el administrador.","feedback":"El problema señalado es el control simultáneo sobre producción y todas las copias."},{"text":"Que las copias ocupen una carpeta con otro nombre.","feedback":"El nombre no limita los permisos de la cuenta comprometida."},{"text":"Que una prueba funcional compruebe más de un componente.","feedback":"Comprobar el recorrido completo ayuda a validar el servicio."}],"correct":0,"takeaway":"Las copias necesitan protección frente al mismo incidente que afecta al sistema principal."},{"id":"d1m3q05","kind":"concepto","title":"Una guía que ayuda bajo presión","scenario":"Caso docente. El documento de recuperación dice restaurar lo antes posible y llamar si pasa algo.","prompt":"¿Qué convierte ese texto en un runbook útil?","terms":["Runbook"],"options":[{"text":"Más adjetivos para expresar urgencia.","feedback":"La urgencia no indica cómo actuar ni qué resultado comprobar."},{"text":"La instrucción de continuar siempre aunque fallen comprobaciones.","feedback":"Una guía debe establecer cuándo detenerse o pasar a una alternativa."},{"text":"Acciones, requisitos, comprobaciones y alternativa si falla cada paso.","feedback":"Correcto. Se puede ejecutar y decidir con información concreta."},{"text":"Una lista de nombres sin acciones ni sustitutos.","feedback":"Las personas necesitan saber qué deben hacer y bajo qué condiciones."}],"correct":2,"takeaway":"Un runbook enlaza acciones con condiciones, comprobaciones y respuesta a fallos."},{"id":"d1m3q06","kind":"concepto","title":"Una prueba con resultado","scenario":"Caso docente. La web abre y el proceso del servidor está activo. Falta comprobar que una reserva pueda confirmarse y quedar registrada.","prompt":"¿Qué prueba valida mejor el servicio descrito?","terms":["Prueba funcional","Validación"],"options":[{"text":"Hacer una captura del icono de la aplicación.","feedback":"La imagen no muestra que una operación se complete."},{"text":"Preguntar si el equipo hace ruido.","feedback":"El ruido no demuestra funcionamiento de la aplicación."},{"text":"Crear una reserva de prueba, confirmarla y verificar su registro y permisos.","feedback":"Correcto. Se comprueba un recorrido representativo con su resultado."},{"text":"Contar cuántos servicios del sistema operativo están en verde.","feedback":"Es un dato de componentes y no del recorrido de la reserva."}],"correct":2,"takeaway":"La recuperación se demuestra con operaciones representativas y condiciones de aceptación."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d1m3q07","kind":"caso","title":"Dos objetivos, dos resultados","scenario":"Caso docente. El corte ocurre a las 09:00. Hay datos válidos hasta las 08:50 y el servicio queda validado a las 09:40. Objetivos: RTO 60 min y RPO 15 min.","prompt":"¿Qué resultado corresponde?","terms":["RTO","RPO"],"options":[{"text":"Incumple ambos porque toda interrupción implica incumplimiento.","feedback":"Los objetivos admiten límites concretos y deben compararse con ellos."},{"text":"Cumple RTO, pero incumple RPO porque faltan cuarenta minutos.","feedback":"Los cuarenta minutos son de recuperación. La diferencia del punto de datos es diez."},{"text":"Cumple RPO, pero el RTO es diez minutos.","feedback":"Se están intercambiando las dos magnitudes."},{"text":"Cumple ambos: 40 min de recuperación y 10 min de datos expuestos a pérdida.","feedback":"Correcto. Cuarenta no supera sesenta y diez no supera quince."}],"correct":3,"takeaway":"Calcula por separado tiempo hasta servicio validado y distancia al punto de datos recuperable.","visual":{"type":"metrics","items":[{"label":"Corte","value":"09:00"},{"label":"Datos válidos","value":"08:50"},{"label":"Servicio validado","value":"09:40"}]}},{"id":"d1m3q08","kind":"caso","title":"La validación también consume tiempo","scenario":"Caso docente. Desde el corte se emplean 15 minutos en preparar el entorno, 35 en restaurar y 20 en validar. Son etapas consecutivas. El RTO acordado es 60 minutos.","prompt":"¿Qué conclusión es correcta?","terms":["RTO","Validación"],"options":[{"text":"No se puede calcular porque las etapas no son simultáneas.","feedback":"Precisamente al ser consecutivas se suman sus duraciones."},{"text":"Incumple por 10 minutos: el total es 70.","feedback":"Correcto. 15 + 35 + 20 = 70, diez por encima del objetivo."},{"text":"Cumple porque preparar y restaurar suman 50.","feedback":"Falta contar los veinte minutos de validación necesarios."},{"text":"Cumple porque restaurar tarda 35 minutos.","feedback":"El objetivo del servicio incluye el recorrido hasta la capacidad validada."}],"correct":1,"takeaway":"El presupuesto de recuperación debe incluir preparación y comprobaciones.","visual":{"type":"metrics","items":[{"label":"Preparación","value":"15 min"},{"label":"Restauración","value":"35 min"},{"label":"Validación","value":"20 min"},{"label":"RTO","value":"60 min"}]}},{"id":"d1m3q09","kind":"caso","title":"La copia reciente que llega tarde","scenario":"Caso docente. El corte es a las 12:15. La última copia válida contiene datos hasta las 12:00 y no hay registros adicionales recuperables. El RPO es 10 minutos.","prompt":"¿Se cumple el objetivo de datos?","terms":["RPO"],"options":[{"text":"Sí, porque quince minutos es un RTO habitual.","feedback":"El ejercicio establece RPO diez. No puede sustituirse por otro objetivo."},{"text":"Sí, porque la copia se restaura en cinco minutos.","feedback":"La velocidad de restauración no acorta el intervalo de datos que faltan."},{"text":"No. La pérdida potencial cubre 15 minutos, cinco más que el objetivo.","feedback":"Correcto. Se compara el corte con el último punto válido recuperable."},{"text":"No, porque el RPO se mide contando servidores.","feedback":"RPO se refiere al punto temporal de datos recuperables."}],"correct":2,"takeaway":"Una restauración rápida puede recuperar datos demasiado antiguos.","visual":{"type":"metrics","items":[{"label":"Corte","value":"12:15"},{"label":"Datos","value":"12:00"},{"label":"RPO","value":"10 min"}]}},{"id":"d1m3q10","kind":"caso","title":"Elegir una copia defendible","scenario":"Caso docente. A las 10:00 se interrumpe el servicio. La copia A contiene datos hasta 09:55, pero está dañada. B llega a 09:40 y ha superado las comprobaciones. No hay otra fuente recuperable. RPO: 15 minutos.","prompt":"¿Qué conclusión guía la recuperación?","terms":["Copia de seguridad","RPO","Integridad"],"options":[{"text":"Declarar cumplido el RPO con B, porque se ha validado.","feedback":"B es válida, pero deja veinte minutos de datos fuera, más que los quince acordados."},{"text":"B es la opción válida disponible, pero deja un incumplimiento de RPO que debe documentarse y gestionarse.","feedback":"Correcto. Se separa recuperabilidad de cumplimiento del objetivo."},{"text":"Usar A porque siempre gana la fecha más reciente.","feedback":"Una copia dañada no aporta un punto de recuperación válido por ser reciente."},{"text":"Cambiar la hora de B a 09:50 para cumplir.","feedback":"Modificar la etiqueta no recupera datos y falsea la evidencia."}],"correct":1,"takeaway":"Una copia debe ser válida y además satisfacer los objetivos. Son comprobaciones distintas.","visual":{"type":"metrics","items":[{"label":"Copia A","value":"09:55 / dañada"},{"label":"Copia B","value":"09:40 / válida"},{"label":"RPO","value":"15 min"}]}},{"id":"d1m3q11","kind":"caso","title":"Primero un lugar fiable","scenario":"Caso docente. Se han comprometido credenciales de administración. La copia es válida, pero se propone restaurarla en el mismo entorno sin revisar accesos.","prompt":"¿Qué condición de entrada falta?","terms":["Entorno confiable","Dependencia de recuperación"],"options":[{"text":"Un fondo de escritorio nuevo.","feedback":"La apariencia no cambia accesos ni condiciones de compromiso."},{"text":"Aumentar la publicidad del servicio.","feedback":"La comunicación no sustituye condiciones técnicas de recuperación."},{"text":"Desactivar toda comprobación para ganar tiempo.","feedback":"El objetivo temporal no elimina la necesidad de una recuperación aceptable."},{"text":"Preparar y comprobar un entorno y accesos confiables antes de reabrir.","feedback":"Correcto. Recuperar datos sobre condiciones comprometidas puede reproducir el daño."}],"correct":3,"takeaway":"El orden de recuperación depende de condiciones que permitan confiar en el resultado."},{"id":"d1m3q12","kind":"caso","title":"La operación vuelve con permisos incorrectos","scenario":"Caso docente. La restauración recupera todos los pedidos, pero cualquier usuario puede modificar los de otros clientes.","prompt":"¿Puede darse por validado el servicio?","terms":["Prueba funcional","Permiso","Integridad"],"options":[{"text":"No. La prueba debe incluir permisos y evitar operaciones indebidas.","feedback":"Correcto. La condición de servicio incluye quién puede hacer cada acción."},{"text":"Sí, porque el número de filas coincide.","feedback":"La cantidad de datos no comprueba si las operaciones y permisos son correctos."},{"text":"No, porque una restauración nunca puede usarse.","feedback":"Una restauración puede ser válida cuando se comprueban sus condiciones."},{"text":"Sí, si el tiempo de restauración fue muy corto.","feedback":"Cumplir tiempo no compensa una autorización incorrecta."}],"correct":0,"takeaway":"Validar incluye resultados y permisos, además de disponibilidad y tiempo."},{"id":"d1m3q13","kind":"caso","title":"Registros que completan el punto","scenario":"Caso docente. El corte ocurre a las 10:00. Una copia llega a las 09:30, pero registros válidos permiten reconstruir y comprobar los datos hasta las 09:57. RPO: 5 minutos.","prompt":"¿Qué punto se usa para evaluar el RPO?","terms":["RPO","Validación"],"options":[{"text":"La hora a la que termina el traslado de archivos.","feedback":"Ese instante se relaciona con la duración del proceso, no con el punto de los datos."},{"text":"10:00, porque todo registro garantiza pérdida cero.","feedback":"Solo se ha validado cobertura hasta 09:57."},{"text":"09:30 siempre, porque los registros no pueden aportar datos.","feedback":"El caso establece que permiten reconstruir y comprobar datos posteriores."},{"text":"09:57, con tres minutos de datos expuestos a pérdida.","feedback":"Correcto. Se evalúa el punto realmente recuperable y validado, no solo la hora de la copia base."}],"correct":3,"takeaway":"El RPO se comprueba frente al último punto válido que realmente puede reconstruirse.","visual":{"type":"metrics","items":[{"label":"Copia base","value":"09:30"},{"label":"Registros válidos","value":"09:57"},{"label":"Corte","value":"10:00"}]}},{"id":"d1m3q14","kind":"caso","title":"Conciliar sin repetir entregas","scenario":"Caso docente. El pedido 417 está solo en papel. El 418 aparece en papel y en la base con la misma entrega confirmada. El 419 tiene cantidades diferentes.","prompt":"¿Qué plan evita perder o duplicar operaciones?","terms":["Conciliación","Identificador"],"options":[{"text":"Elegir al azar una cantidad para 419.","feedback":"Una diferencia requiere contraste con evidencia, no una decisión arbitraria."},{"text":"Borrar todos los folios porque ya hay una base restaurada.","feedback":"Se perdería al menos el pedido 417 y no se resolvería 419."},{"text":"Insertar los tres como nuevos y cerrar.","feedback":"Podría duplicarse 418 y conservarse el error de 419."},{"text":"Incorporar 417, comprobar la coincidencia de 418 y resolver 419 con sus evidencias.","feedback":"Correcto. Se trata cada situación según su diferencia real."}],"correct":3,"takeaway":"La conciliación conserva identidad de las operaciones y resuelve diferencias antes del cierre."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d1m3q15","kind":"reto","title":"Reto: rápido y antiguo","scenario":"Caso docente. Un servicio se valida en 25 minutos, por debajo de su RTO de 40. Solo recupera datos de una hora antes del corte, con RPO de 15 minutos.","prompt":"¿Qué afirmación describe el resultado?","terms":["RTO","RPO"],"options":[{"text":"Cumple RTO e incumple RPO.","feedback":"Correcto. La duración y el punto de datos se evalúan por separado."},{"text":"RTO y RPO se promedian para obtener un aprobado.","feedback":"No son dos notas intercambiables. Cada objetivo conserva su condición."},{"text":"Cumple todo porque el servicio vuelve rápido.","feedback":"Queda una pérdida potencial de datos superior a la tolerada."},{"text":"Incumple RTO y cumple RPO.","feedback":"Se han intercambiado los objetivos."}],"correct":0,"takeaway":"Un objetivo cumplido no compensa automáticamente el incumplimiento del otro.","visual":{"type":"metrics","items":[{"label":"Recuperación","value":"25 / 40 min"},{"label":"Datos expuestos","value":"60 / 15 min"}]}},{"id":"d1m3q16","kind":"reto","title":"Reto: el ensayo que faltaba","scenario":"Caso docente. Las tareas de copia llevan meses marcadas como correctas. Nunca se ha probado recuperar una operación completa.","prompt":"¿Qué afirmación es defendible?","terms":["Copia de seguridad","Prueba funcional"],"options":[{"text":"Las marcas verdes garantizan tiempos y permisos de cualquier recuperación.","feedback":"Solo describen comprobaciones de las tareas realizadas."},{"text":"Hace falta un ensayo para conocer si los datos se restauran y el servicio cumple sus condiciones.","feedback":"Correcto. El ensayo aporta evidencia sobre una capacidad que el indicador de copia no demuestra."},{"text":"Basta con aumentar el tamaño del archivo de copia.","feedback":"El tamaño no demuestra que se pueda usar ni que el servicio funcione."},{"text":"Una copia no puede verificarse hasta que ocurra un desastre.","feedback":"Se pueden preparar ensayos de restauración y validación."}],"correct":1,"takeaway":"El éxito de una tarea de copia no equivale a una recuperación probada."},{"id":"d1m3q17","kind":"reto","title":"Reto: una guía con salida de emergencia","scenario":"Caso docente. La comprobación de integridad falla durante una restauración. El runbook contempla detener la apertura y probar otra copia verificada.","prompt":"¿Qué actuación sigue el propósito de la guía?","terms":["Runbook","Integridad"],"options":[{"text":"Borrar la comprobación fallida del informe.","feedback":"Oculta una limitación relevante y elimina trazabilidad."},{"text":"Mantener cerrada la apertura, registrar el fallo y ejecutar la alternativa prevista.","feedback":"Correcto. El resultado de la comprobación modifica la decisión de forma trazable."},{"text":"Repetir la misma orden sin revisar nada hasta obtener otra salida.","feedback":"Repetir sin hipótesis ni cambio no gestiona la condición fallida."},{"text":"Abrir igualmente para que el cronómetro no marque rojo.","feedback":"El tiempo no convierte datos inválidos en un servicio aceptable."}],"correct":1,"takeaway":"Una comprobación sirve cuando su resultado puede detener o cambiar la actuación."},{"id":"d1m3q18","kind":"reto","title":"Reto: copia y réplica","scenario":"Caso docente. Queréis soportar tanto la avería de un servidor como un borrado que se replica inmediatamente.","prompt":"¿Qué diseño encaja mejor con ambos escenarios?","terms":["Réplica","Retención","Separación de accesos"],"options":[{"text":"Redundancia operativa y versiones históricas protegidas, con pruebas para cada escenario.","feedback":"Correcto. Se combinan capacidades que cubren fallos distintos y se verifica su utilidad."},{"text":"El mismo servidor con dos nombres de red.","feedback":"Cambiar nombres no crea una alternativa de recuperación."},{"text":"Una única copia vieja sin comprobar, porque nunca cambia.","feedback":"Puede no contener datos suficientes ni ser utilizable."},{"text":"Dos réplicas inmediatas con permisos compartidos y sin historia.","feedback":"Pueden ayudar ante la avería, pero también replicar el borrado y compartir su exposición."}],"correct":0,"takeaway":"La cartera de recuperación debe responder a los escenarios de fallo que se quieren soportar."}]}],"sources":[{"title":"Presentación docente, día 1, diapositivas 68–78","url":""},{"title":"NIST SP 800-184","url":"https://csrc.nist.gov/pubs/sp/800/184/final"},{"title":"NIST, Recovery Time Objective","url":"https://csrc.nist.gov/glossary/term/recovery_time_objective"},{"title":"NIST, Recovery Point Objective","url":"https://csrc.nist.gov/glossary/term/Recovery_Point_Objective"}]},{"id":4,"slug":"patronato","title":"El patronato","block":"Decisiones sobre el riesgo","description":"Elegimos una cartera con presupuesto limitado y defendemos qué riesgo queda y quién lo acepta.","originalSlide":109,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/continuidad/cartera.html","minutes":30,"concepts":[{"term":"ERM","definition":"Enterprise Risk Management. Gestión integrada de los riesgos de toda la organización.","example":"Una caída digital se relaciona con atención, contratos, recursos y objetivos."},{"term":"Propietario del riesgo","definition":"Persona con responsabilidad y autoridad para gestionar un riesgo concreto.","example":"El responsable del servicio decide dentro de sus atribuciones qué retraso puede aceptar."},{"term":"ISO/IEC 27001","definition":"Norma de requisitos para un sistema de gestión de seguridad de la información.","example":"Organiza responsabilidades y gestión sobre información, accesos y controles."},{"term":"ISO 22301","definition":"Norma de requisitos para un sistema de gestión de continuidad del negocio.","example":"Organiza prioridades, alternativas y ensayos de continuidad."},{"term":"MAGERIT","definition":"Metodología de Análisis y Gestión de Riesgos de los Sistemas de Información.","example":"Relaciona activos, amenazas, impacto, salvaguardas y dependencias."},{"term":"Salvaguarda","definition":"Medida que modifica la probabilidad o las consecuencias de un riesgo.","example":"Una ruta independiente puede reducir el impacto de un corte."},{"term":"CIS Controls","definition":"Conjunto priorizado de prácticas y salvaguardas del Center for Internet Security.","example":"Incluye prácticas sobre inventario, acceso, formación y recuperación."},{"term":"NIST CSF","definition":"Cybersecurity Framework. Marco de resultados para gestionar el riesgo de ciberseguridad.","example":"CSF 2.0 organiza gobernar, identificar, proteger, detectar, responder y recuperar."},{"term":"Riesgo residual","definition":"Riesgo que permanece tras las medidas aplicadas.","example":"Una alternativa conserva urgentes, pero todavía puede retrasar otros pedidos."},{"term":"Valor esperado","definition":"Promedio teórico calculado con estimaciones y supuestos del modelo.","example":"Dos interrupciones al año por seis horas producen doce horas esperadas al año."},{"term":"Tratamiento del riesgo","definition":"Selección y aplicación de opciones para modificar o asumir un riesgo.","example":"Se puede evitar, reducir, compartir o aceptar un escenario bajo condiciones."},{"term":"Aceptación","definition":"Decisión informada de asumir un riesgo con criterios y responsabilidades definidos.","example":"Se admite un retraso temporal con responsable, límite y revisión."},{"term":"Escenario","definition":"Descripción concreta de un posible suceso y sus consecuencias.","example":"Cae el proveedor de identidad y no pueden autorizarse pedidos."},{"term":"Cartera de medidas","definition":"Conjunto de actuaciones elegido dentro de unos recursos y prioridades.","example":"Combinar copia protegida, preparación y ensayo dentro del presupuesto."},{"term":"Eficacia","definition":"Grado en que una medida consigue el resultado pretendido.","example":"El ensayo demuestra cuántas operaciones válidas conserva la alternativa."},{"term":"Criterio de aceptación","definition":"Condición utilizada para decidir si un resultado o riesgo puede asumirse.","example":"Se exige sostener veinte solicitudes válidas por hora."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d1m4q01","kind":"concepto","title":"El riesgo sale del servidor","scenario":"Caso docente. Una caída digital afecta a préstamos, contratos, atención presencial y presupuesto de una biblioteca.","prompt":"¿Qué aporta conectar el análisis con ERM?","terms":["ERM","Propietario del riesgo"],"options":[{"text":"Integrar el riesgo digital en los objetivos, responsabilidades y decisiones de la organización.","feedback":"Correcto. ERM permite valorar consecuencias en conjunto y asignar responsabilidad adecuada."},{"text":"Asignar todos los riesgos al último técnico que recibió una alerta.","feedback":"La responsabilidad requiere autoridad y relación con los objetivos afectados."},{"text":"Limitar la conversación a la marca de los servidores.","feedback":"La caída ya afecta a objetivos y decisiones de varias áreas."},{"text":"Eliminar riesgos financieros porque el origen es digital.","feedback":"Un origen digital puede producir consecuencias económicas y operativas."}],"correct":0,"takeaway":"El riesgo digital debe relacionarse con los objetivos de toda la organización."},{"id":"d1m4q02","kind":"concepto","title":"Dos sistemas de gestión","scenario":"Caso docente. El patronato quiere ordenar la seguridad de la información y la continuidad de actividades prioritarias.","prompt":"¿Qué correspondencia es correcta?","terms":["ISO/IEC 27001","ISO 22301"],"options":[{"text":"ISO/IEC 27001 es un antivirus e ISO 22301 una copia de seguridad.","feedback":"Son normas de requisitos para sistemas de gestión, no productos."},{"text":"Cualquiera de las dos garantiza que nunca habrá una interrupción.","feedback":"Un sistema de gestión no garantiza ausencia absoluta de incidentes."},{"text":"ISO/IEC 27001 organiza la seguridad de la información e ISO 22301 la continuidad del negocio.","feedback":"Correcto. Sus alcances son complementarios y requieren gestión, responsabilidades y evidencia."},{"text":"ISO 22301 identifica automáticamente a los atacantes.","feedback":"Su foco es la gestión de continuidad, no la atribución."}],"correct":2,"takeaway":"Las normas estructuran la gestión. Los resultados concretos deben comprobarse."},{"id":"d1m4q03","kind":"concepto","title":"Un mapa para razonar el riesgo","scenario":"Caso docente. Se analiza qué activos sostienen préstamos, qué amenazas pueden dañarlos y qué medidas cambian sus consecuencias.","prompt":"¿Qué encaja con el propósito de MAGERIT?","terms":["MAGERIT","Salvaguarda"],"options":[{"text":"Una clasificación de atacantes por nacionalidad.","feedback":"El análisis descrito trata de activos, amenazas y riesgo."},{"text":"Un compromiso de eliminar toda incertidumbre.","feedback":"El análisis necesita expresar supuestos y no convierte estimaciones en certezas."},{"text":"Relacionar activos, dependencias, amenazas, impacto, salvaguardas y riesgo residual.","feedback":"Correcto. Esa relación permite justificar por qué una medida aborda un escenario."},{"text":"Una lista de compras sin relación con los servicios.","feedback":"Las medidas deben justificarse por el riesgo y las dependencias que modifican."}],"correct":2,"takeaway":"El análisis conecta lo que tiene valor con aquello que puede dañarlo y cómo se trata."},{"id":"d1m4q04","kind":"concepto","title":"Medidas que se pueden ejecutar","scenario":"Caso docente. El equipo busca prácticas concretas sobre inventario, permisos, formación y recuperación.","prompt":"¿Qué recurso de la clase responde a esa necesidad?","terms":["CIS Controls"],"options":[{"text":"El RPO, como catálogo completo de controles.","feedback":"RPO expresa un objetivo de datos recuperables, no un catálogo de prácticas."},{"text":"Una lista de titulares de prensa sin acciones definidas.","feedback":"Los titulares aportan contexto, pero no una práctica ejecutable por sí mismos."},{"text":"Una puntuación que sustituya todas las decisiones humanas.","feedback":"Las medidas necesitan contexto, responsabilidad y comprobación."},{"text":"CIS Controls, con prácticas y salvaguardas priorizadas.","feedback":"Correcto. Ayuda a concretar medidas como gestionar accesos o preparar recuperación."}],"correct":3,"takeaway":"Las prácticas concretas se eligen según necesidades y se comprueban en su contexto."},{"id":"d1m4q05","kind":"concepto","title":"El mapa de resultados","scenario":"Caso docente. Se quiere organizar el trabajo de riesgo en gobernar, identificar, proteger, detectar, responder y recuperar.","prompt":"¿Qué marco corresponde a ese mapa?","terms":["NIST CSF"],"options":[{"text":"Una garantía automática de certificación de cualquier servicio.","feedback":"Describir funciones no demuestra por sí solo que se cumplan condiciones concretas."},{"text":"NIST CSF 2.0.","feedback":"Correcto. Sus seis funciones organizan resultados para gestionar el riesgo de ciberseguridad."},{"text":"Un sustituto del presupuesto y de los responsables.","feedback":"Un marco no elimina decisiones sobre recursos y autoridad."},{"text":"Solo una secuencia obligatoria que se ejecuta una vez al año.","feedback":"Las funciones organizan resultados de gestión y no se reducen a una secuencia anual."}],"correct":1,"takeaway":"Un marco ayuda a organizar resultados. La evidencia demuestra qué se consigue."},{"id":"d1m4q06","kind":"concepto","title":"El riesgo que sigue existiendo","scenario":"Caso docente. Una medida reduce las interrupciones esperadas, pero sigue siendo posible perder una ventana de atención.","prompt":"¿Cómo se denomina ese riesgo restante?","terms":["Riesgo residual"],"options":[{"text":"Una prueba de que la medida no aporta nada.","feedback":"Puede existir una reducción útil y aun así quedar riesgo."},{"text":"Riesgo imposible por definición.","feedback":"Que una medida reduzca el riesgo no elimina todos los escenarios."},{"text":"Riesgo residual.","feedback":"Correcto. Es el riesgo que permanece después de las medidas aplicadas."},{"text":"Un dato que debe quitarse del informe para no confundir.","feedback":"El responsable necesita conocerlo para decidir y seguir su evolución."}],"correct":2,"takeaway":"Tratar un riesgo incluye valorar y gestionar lo que permanece."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d1m4q07","kind":"caso","title":"Horas esperadas, no profecía","scenario":"Caso docente. El modelo estima 2 interrupciones al año de 6 horas cada una. Con una medida estima 1 al año de 2 horas.","prompt":"¿Qué lectura corresponde al modelo?","terms":["Valor esperado","Riesgo residual"],"options":[{"text":"El riesgo cae a cero porque hay menos interrupciones.","feedback":"El modelo todavía conserva dos horas esperadas al año."},{"text":"Se pasa de 12 a 2 horas esperadas al año, bajo los supuestos dados.","feedback":"Correcto. 2 × 6 = 12 y 1 × 2 = 2. La reducción modelada es diez horas."},{"text":"Se garantiza exactamente una interrupción de dos horas el próximo año.","feedback":"Un valor esperado es una estimación del modelo, no una predicción garantizada."},{"text":"Se pasa de 12 a 3 horas, sumando frecuencia y duración.","feedback":"Frecuencia y duración se multiplican en este modelo."}],"correct":1,"takeaway":"Una cifra esperada requiere unidades, supuestos y reconocimiento de la incertidumbre.","visual":{"type":"metrics","items":[{"label":"Antes","value":"2/año × 6 h"},{"label":"Después","value":"1/año × 2 h"},{"label":"Reducción modelada","value":"10 h/año"}]}},{"id":"d1m4q08","kind":"caso","title":"Presupuesto con un requisito","scenario":"Caso docente. Hay 10 unidades de presupuesto. Para recuperación se necesitan una copia protegida (6) y un ensayo (4). El servidor decorativo de recepción cuesta 5 y no cambia ese escenario.","prompt":"¿Qué cartera cumple el requisito dentro del presupuesto?","terms":["Cartera de medidas","Eficacia"],"options":[{"text":"Copia y servidor decorativo.","feedback":"Cuestan once y dejan sin ensayo la recuperación requerida."},{"text":"Solo el servidor decorativo, porque queda dinero.","feedback":"Ahorrar no satisface el objetivo de recuperación."},{"text":"Copia, ensayo y servidor decorativo.","feedback":"Suman quince, por encima del presupuesto de diez."},{"text":"Copia protegida y ensayo.","feedback":"Correcto. Suman diez y cubren las dos condiciones del requisito."}],"correct":3,"takeaway":"La cartera debe cumplir el objetivo dentro de los recursos, no solo incluir compras visibles.","visual":{"type":"metrics","items":[{"label":"Presupuesto","value":"10"},{"label":"Copia","value":"6"},{"label":"Ensayo","value":"4"}]}},{"id":"d1m4q09","kind":"caso","title":"Seguro y continuidad","scenario":"Caso docente. Un seguro cubre ciertas pérdidas económicas por interrupción. No aporta personal, conexiones ni un procedimiento alternativo.","prompt":"¿Qué conclusión es correcta?","terms":["Tratamiento del riesgo"],"options":[{"text":"Comparte determinadas consecuencias económicas y puede requerir medidas adicionales de continuidad.","feedback":"Correcto. La cobertura tiene un alcance que debe distinguirse de la capacidad operativa."},{"text":"El seguro mantiene el servicio por sí solo.","feedback":"La cobertura económica no ejecuta operaciones ni crea una alternativa."},{"text":"Es equivalente a restaurar una copia verificada.","feedback":"La restauración actúa sobre datos y capacidad. El seguro tiene otra función."},{"text":"Contratarlo elimina toda responsabilidad de la organización.","feedback":"La organización sigue teniendo decisiones y obligaciones sobre su servicio."}],"correct":0,"takeaway":"Compartir consecuencias económicas no equivale a sostener el servicio."},{"id":"d1m4q10","kind":"caso","title":"Aceptar con condiciones","scenario":"Caso docente. Queda un riesgo de retraso de pedidos ordinarios hasta el viernes. El responsable acepta temporalmente mientras se prepara una alternativa.","prompt":"¿Qué registro permite seguir esa decisión?","terms":["Aceptación","Propietario del riesgo"],"options":[{"text":"Una fecha pasada para que parezca que el problema terminó.","feedback":"Falsear el plazo impide gestionar la situación real."},{"text":"La palabra aceptado sin describir qué puede ocurrir.","feedback":"La decisión debe estar ligada a un escenario y unas consecuencias."},{"text":"Un mensaje que diga ya veremos sin fecha ni responsable.","feedback":"No permite saber quién decide ni cuándo deja de ser válida la aceptación."},{"text":"Riesgo restante, límites, responsable, plazo y prueba de revisión.","feedback":"Correcto. La aceptación resulta concreta y revisable."}],"correct":3,"takeaway":"Aceptar un riesgo es una decisión informada con límites y seguimiento."},{"id":"d1m4q11","kind":"caso","title":"El fallo que queremos soportar","scenario":"Caso docente. El objetivo es resistir la caída de un proveedor de identidad. La propuesta ofrece dos servidores más que dependen del mismo proveedor.","prompt":"¿Qué falta demostrar?","terms":["Escenario","Salvaguarda","Eficacia"],"options":[{"text":"Que el proveedor nunca pueda fallar.","feedback":"El escenario exige preparar qué hacer si falla, no descartarlo sin evidencia."},{"text":"Que las cajas tengan otra marca.","feedback":"La marca no elimina la dependencia del proveedor de identidad."},{"text":"Que los servidores nuevos sean más caros.","feedback":"El precio no demuestra independencia frente al fallo previsto."},{"text":"Que exista una alternativa operativa para la identidad y que supere una prueba de ese fallo.","feedback":"Correcto. La medida debe modificar el camino que bloquea el servicio."}],"correct":3,"takeaway":"La utilidad de una medida depende del escenario frente al que se prueba."},{"id":"d1m4q12","kind":"caso","title":"Dos medidas con solapamiento","scenario":"Caso docente. A reduce el mismo tipo de parada de 10 a 6 horas esperadas al año. B, aplicada sola, también lo reduce de 10 a 6. No se conoce su efecto combinado.","prompt":"¿Qué puede afirmarse?","terms":["Valor esperado","Cartera de medidas"],"options":[{"text":"Hace falta estudiar el efecto combinado y sus dependencias antes de sumar beneficios.","feedback":"Correcto. Dos medidas pueden actuar sobre la misma parte del riesgo."},{"text":"Ninguna sirve porque producen la misma cifra por separado.","feedback":"Cada una muestra una reducción modelada. Lo desconocido es su combinación."},{"text":"Juntas reducen necesariamente a dos horas porque se restan ambas mejoras.","feedback":"Los efectos podrían solaparse. El caso no permite sumarlos sin otro modelo."},{"text":"Juntas eliminan toda parada porque hay dos controles.","feedback":"El número de controles no demuestra ausencia de riesgo."}],"correct":0,"takeaway":"Los beneficios de medidas distintas no se suman automáticamente."},{"id":"d1m4q13","kind":"caso","title":"Evitar una operación concreta","scenario":"Caso docente. Una organización decide dejar de ofrecer una funcionalidad expuesta que no es necesaria para su servicio prioritario.","prompt":"¿Qué opción de tratamiento describe mejor la decisión?","terms":["Tratamiento del riesgo"],"options":[{"text":"Compartir, porque seguirá operando otra actividad.","feedback":"Compartir se refiere a repartir determinadas consecuencias o responsabilidades, no a retirar la actividad."},{"text":"Evitar ese riesgo asociado a la funcionalidad retirada.","feedback":"Correcto. Se decide no continuar la actividad que genera ese escenario, valorando sus efectos."},{"text":"Recuperar, porque se restaura un servicio caído.","feedback":"No se está describiendo una restauración, sino una decisión sobre una actividad."},{"text":"Aceptar, porque el riesgo continúa igual.","feedback":"Se elimina la actividad concreta que originaba el escenario descrito."}],"correct":1,"takeaway":"Evitar puede consistir en dejar de realizar una actividad, con una decisión consciente sobre sus consecuencias."},{"id":"d1m4q14","kind":"caso","title":"El ensayo desmiente la compra","scenario":"Caso docente. Se compró una alternativa para atender veinte solicitudes por hora. En el ensayo solo completa doce con las comprobaciones exigidas.","prompt":"¿Qué debe reflejar el informe?","terms":["Eficacia","Criterio de aceptación"],"options":[{"text":"Treinta, para compensar que el ensayo tuvo mala suerte.","feedback":"No hay evidencia que sustente esa cifra."},{"text":"El resultado de doce, la condición incumplida y una acción para corregir o revisar el plan.","feedback":"Correcto. La decisión se apoya en capacidad demostrada."},{"text":"Solo que el proveedor entregó el producto.","feedback":"La entrega del producto no demuestra el servicio que debía sostener."},{"text":"Veinte, porque lo decía el presupuesto aprobado.","feedback":"La previsión no sustituye al resultado observado."}],"correct":1,"takeaway":"Comprar una medida y demostrar su eficacia son hitos diferentes.","visual":{"type":"metrics","items":[{"label":"Objetivo","value":"20/h"},{"label":"Ensayo","value":"12/h"},{"label":"Déficit","value":"8/h"}]}}]},{"id":"reto","label":"Reto final","questions":[{"id":"d1m4q15","kind":"reto","title":"Reto: responsabilidad real","scenario":"Caso docente. Un técnico detecta riesgo en un servicio cuyo cierre temporal solo puede autorizar la dirección del área.","prompt":"¿Qué reparto es más útil?","terms":["Propietario del riesgo","ERM"],"options":[{"text":"El técnico aporta análisis y evidencias, y quien tiene autoridad decide el tratamiento y sus límites.","feedback":"Correcto. Se conectan conocimiento técnico y responsabilidad sobre objetivos."},{"text":"Nadie decide hasta que el riesgo se materialice.","feedback":"La falta de decisión mantiene el escenario sin tratamiento ni aceptación explícita."},{"text":"La dirección firma sin conocer el análisis.","feedback":"La responsabilidad necesita una decisión informada."},{"text":"El técnico acepta solo todo el riesgo porque lo descubrió.","feedback":"Detectar no otorga automáticamente autoridad sobre las consecuencias del servicio."}],"correct":0,"takeaway":"La responsabilidad debe corresponder a la capacidad de decidir y gestionar consecuencias."},{"id":"d1m4q16","kind":"reto","title":"Reto: un marco no es una compra","scenario":"Caso docente. Un proveedor afirma que instalar su producto completa todas las funciones de NIST CSF y elimina la necesidad de preparar a las personas.","prompt":"¿Qué valoración corresponde?","terms":["NIST CSF","CIS Controls"],"options":[{"text":"Los marcos solo sirven para sustituir controles técnicos.","feedback":"Los marcos organizan resultados y los controles pueden incluir tecnología."},{"text":"Debe comprobarse qué resultados cubre y qué decisiones, personas y procesos siguen siendo necesarios.","feedback":"Correcto. Una herramienta puede contribuir a resultados sin sustituir toda la gestión."},{"text":"Es correcto si el producto tiene muchos botones.","feedback":"La cantidad de funciones de una interfaz no demuestra resultados de gestión."},{"text":"La afirmación se demuestra contando licencias compradas.","feedback":"Las licencias no prueban preparación, responsabilidades ni recuperación."}],"correct":1,"takeaway":"Una herramienta contribuye a capacidades. Su alcance se evalúa con resultados y evidencia."},{"id":"d1m4q17","kind":"reto","title":"Reto: el criterio cambió","scenario":"Caso docente. Una aceptación temporal permitía una hora de interrupción, pero un nuevo servicio urgente solo tolera quince minutos.","prompt":"¿Qué procede?","terms":["Aceptación","Criterio de aceptación","Riesgo residual"],"options":[{"text":"Borrar el servicio nuevo del inventario para evitar la revisión.","feedback":"Eso oculta una necesidad real y debilita el análisis."},{"text":"Promediar una hora y quince minutos sin consultar a nadie.","feedback":"Un promedio no define el umbral aceptable del servicio."},{"text":"Mantener la aceptación para siempre porque ya está firmada.","feedback":"La condición que sustentaba la decisión ha cambiado."},{"text":"Revisar el riesgo y la decisión frente al nuevo límite y asignar las medidas necesarias.","feedback":"Correcto. Las aceptaciones dependen de sus condiciones y deben actualizarse."}],"correct":3,"takeaway":"El cambio de contexto puede invalidar una decisión anterior de aceptación."},{"id":"d1m4q18","kind":"reto","title":"Reto: una cartera defendible","scenario":"Caso docente. Dos propuestas cuestan lo mismo. La primera muestra muchas licencias. La segunda relaciona escenario, servicio, capacidad probada, riesgo restante y responsable.","prompt":"¿Qué propuesta aporta mejor base para decidir?","terms":["Cartera de medidas","Eficacia","Riesgo residual"],"options":[{"text":"La segunda, porque permite comprobar qué cambia y qué queda por asumir.","feedback":"Correcto. Relaciona recursos y resultado, sin ocultar limitaciones."},{"text":"La que use más siglas, aunque nadie pueda explicar el resultado.","feedback":"Las siglas no sustituyen argumentos ni evidencia."},{"text":"Cualquiera, porque mismo coste implica mismo riesgo.","feedback":"El coste no determina por sí solo la eficacia ni las dependencias."},{"text":"La primera, porque más nombres de productos siempre significan más resiliencia.","feedback":"El catálogo no demuestra utilidad frente al fallo que importa."}],"correct":0,"takeaway":"Una decisión defendible conecta necesidad, medidas, evidencia y riesgo restante."}]}],"sources":[{"title":"Presentación docente, día 1, diapositivas 98–108","url":""},{"title":"MAGERIT v3, Libro I","url":"https://www.hacienda.gob.es/sgt/catalogo_sefp/046_magerit_v3_libro1_metodo.pdf"},{"title":"NIST CSF 2.0","url":"https://www.nist.gov/publications/nist-cybersecurity-framework-csf-20"},{"title":"ISO 22301","url":"https://www.iso.org/standard/75106.html"},{"title":"ISO/IEC 27001","url":"https://www.iso.org/standard/27001"}]},{"id":5,"slug":"relevo","title":"Acta de relevo","block":"Entrega y aprendizaje","description":"Reconstruimos una cronología, contrastamos evidencias y entregamos un servicio con pendientes claros.","originalSlide":139,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/continuidad/relevo.html","minutes":30,"concepts":[{"term":"Hecho","definition":"Observación sustentada en información disponible.","example":"Dos reservas fallaron en la prueba y existe registro de sus identificadores."},{"term":"Hipótesis","definition":"Explicación provisional que debe contrastarse con información adicional.","example":"Quizá faltan datos, pero todavía no se ha comprobado."},{"term":"Decisión","definition":"Elección de una actuación con la información y autoridad disponibles.","example":"Se mantiene cerrada la apertura mientras se comprueban datos y permisos."},{"term":"Evidencia","definition":"Información conservada que permite respaldar o cuestionar una afirmación.","example":"Un registro muestra que la reserva 417 quedó confirmada."},{"term":"UTC","definition":"Tiempo Universal Coordinado, referencia común para expresar instantes comparables.","example":"13:10 UTC+1 equivale a 12:10 UTC."},{"term":"Cronología","definition":"Relación de hechos y acciones ordenados en el tiempo, con sus referencias y límites.","example":"Se anotan alarmas, decisiones y pruebas normalizando las horas."},{"term":"Procedencia","definition":"Origen de la información y forma en que se obtuvo.","example":"Se registra sistema, operación, momento y responsable de recogida."},{"term":"Hash","definition":"Resumen calculado de datos que ayuda a comparar su integridad.","example":"La huella de una copia se contrasta con una referencia conservada usando el mismo método."},{"term":"Integridad","definition":"Conservación de los datos frente a cambios indebidos o no explicados.","example":"La copia de trabajo debe corresponder al archivo de referencia."},{"term":"Cadena de custodia","definition":"Registro de recogida, manejo, conservación y transferencias de una evidencia.","example":"Cada paso identifica persona, momento y acción."},{"term":"Denominador","definition":"Conjunto de casos con el que se compara el número contado.","example":"En ocho de diez incidentes conocidos, diez es el denominador."},{"term":"Indicador","definition":"Medida definida para responder una pregunta concreta.","example":"Proporción de incidentes conocidos detectados internamente durante el trimestre."},{"term":"Parte de relevo","definition":"Registro del estado, evidencias, limitaciones y responsabilidades al entregar una actividad.","example":"Se explican reservas disponibles y folios aún pendientes."},{"term":"Aceptación del servicio","definition":"Confirmación responsable de que se cumplen las condiciones de funcionamiento acordadas.","example":"La persona autorizada revisa pruebas y limitaciones antes de aceptar."},{"term":"Riesgo residual","definition":"Riesgo que permanece después de aplicar las medidas.","example":"Quedan pedidos antiguos por conciliar aunque funcionen nuevas reservas."},{"term":"Lección aprendida","definition":"Conclusión que se convierte en una mejora verificable.","example":"Se ensaya una activación con suplente tras detectar una dependencia del titular."},{"term":"Acción correctiva","definition":"Cambio destinado a resolver una causa o debilidad identificada.","example":"Actualizar suplencias y probar que funcionan antes de la fecha fijada."},{"term":"Plano de control","definition":"Componentes empleados para configurar y administrar servicios.","example":"El panel permite cambiar configuración aunque la operación del usuario todavía falle."},{"term":"Recuperación parcial","definition":"Restablecimiento de una parte de la capacidad o del alcance previsto.","example":"Vuelve administración, pero aún no se confirman reservas."},{"term":"Prueba funcional","definition":"Comprobación de una operación representativa y su resultado previsto.","example":"Una reserva se crea, confirma y consulta con permisos correctos."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d1m5q01","kind":"concepto","title":"Lo observado y lo supuesto","scenario":"Caso docente. Dos reservas fallan. El equipo sospecha que faltan datos y decide comprobarlos antes de reabrir.","prompt":"¿Qué clasificación es correcta?","terms":["Hecho","Hipótesis","Decisión"],"options":[{"text":"Los tres enunciados son pruebas concluyentes de un ataque.","feedback":"El caso no demuestra un ataque ni identifica su causa."},{"text":"Hecho: faltan datos. Hipótesis: fallaron dos reservas.","feedback":"El fallo se observó. La falta de datos todavía es una explicación provisional."},{"text":"La decisión convierte automáticamente la hipótesis en un hecho.","feedback":"Actuar sobre una hipótesis no demuestra que sea verdadera."},{"text":"Hecho: fallaron dos reservas. Hipótesis: faltan datos. Decisión: comprobar antes de reabrir.","feedback":"Correcto. Se separa lo observado, su posible explicación y la actuación elegida."}],"correct":3,"takeaway":"La cronología debe distinguir observaciones, explicaciones provisionales y decisiones."},{"id":"d1m5q02","kind":"concepto","title":"Una hora con referencia","scenario":"Caso docente. Un registro dice 12:10 UTC y otro 13:10 UTC+1. Ambos relojes están correctamente sincronizados.","prompt":"¿Qué relación hay entre esos instantes?","terms":["UTC","Cronología"],"options":[{"text":"Son el mismo instante.","feedback":"Correcto. 13:10 en UTC+1 equivale a 12:10 UTC."},{"text":"No pueden compararse nunca porque usan zonas distintas.","feedback":"Las zonas explícitas permiten normalizar ambos a una referencia común."},{"text":"El primero ocurrió una hora después.","feedback":"También sería una comparación directa que ignora la zona."},{"text":"El segundo ocurrió una hora después.","feedback":"Debe descontarse el desplazamiento +1 antes de comparar."}],"correct":0,"takeaway":"Conservar la zona horaria evita inventar diferencias en una cronología."},{"id":"d1m5q03","kind":"concepto","title":"Una captura con origen","scenario":"Caso docente. Llega una imagen con el texto reserva confirmada, sin sistema de origen ni identificador.","prompt":"¿Qué información mejora su procedencia?","terms":["Procedencia","Evidencia"],"options":[{"text":"La frase prueba definitiva sin detalles adicionales.","feedback":"La afirmación no añade trazabilidad ni permite comprobar el alcance."},{"text":"Un marco de color y el nombre del archivo en mayúsculas.","feedback":"El aspecto no informa sobre origen ni obtención."},{"text":"Sistema y operación de origen, momento de recogida, responsable y forma de obtención.","feedback":"Correcto. Permite situar la información y evaluar qué afirmación respalda."},{"text":"Cambiar la fecha hasta que coincida con la hipótesis.","feedback":"Eso altera la evidencia en vez de documentar su procedencia."}],"correct":2,"takeaway":"Una evidencia útil debe permitir comprender de dónde sale y qué demuestra."},{"id":"d1m5q04","kind":"concepto","title":"La huella no escribe la historia","scenario":"Caso docente. Se conserva el hash de un archivo y después se compara con el del archivo revisado usando el mismo método.","prompt":"¿Qué aporta esa comparación?","terms":["Hash","Integridad"],"options":[{"text":"Demuestra que todo lo escrito es verdadero.","feedback":"El contenido puede ser falso aunque el archivo no cambie."},{"text":"Permite recuperar siempre el contenido original a partir del hash.","feedback":"Un hash no es una copia reversible del archivo."},{"text":"Demuestra quién redactó el archivo, aunque no haya otra evidencia.","feedback":"La huella por sí sola no identifica autoría."},{"text":"Ayuda a comprobar cambios en los datos, sin demostrar por sí sola su veracidad.","feedback":"Correcto. Su función debe distinguirse de autenticidad, procedencia y verdad."}],"correct":3,"takeaway":"La huella ayuda a comprobar integridad y necesita contexto sobre origen y conservación."},{"id":"d1m5q05","kind":"concepto","title":"El recorrido de la evidencia","scenario":"Caso docente. Un registro pasa de la persona que lo recoge a quien lo analiza y después al responsable del incidente.","prompt":"¿Qué documenta una cadena de custodia?","terms":["Cadena de custodia"],"options":[{"text":"Recogida, manejo, conservación y transferencias, con responsables, momentos y acciones.","feedback":"Correcto. Describe el recorrido y permite conocer quién hizo qué."},{"text":"El contenido completo de todas las conversaciones personales del equipo.","feedback":"La cadena se centra en el manejo de la evidencia pertinente."},{"text":"Una predicción de quién ganará la discusión del cierre.","feedback":"No se trata de reputación, sino de trazabilidad del manejo."},{"text":"Solo el nombre de la primera persona que vio el archivo.","feedback":"No cubre posteriores acciones o transferencias."}],"correct":0,"takeaway":"El manejo de evidencias necesita registro, no una cadena de memoria oral."},{"id":"d1m5q06","kind":"concepto","title":"Un porcentaje con base","scenario":"Caso docente. El equipo comunica ocho incidentes detectados internamente de diez incidentes conocidos.","prompt":"¿Qué afirmación permite el dato?","terms":["Denominador","Indicador"],"options":[{"text":"Que el servicio estuvo disponible el 80 % del tiempo.","feedback":"El indicador cuenta incidentes, no tiempo de disponibilidad."},{"text":"Que no existe ningún incidente desconocido.","feedback":"El recuento solo incluye incidentes conocidos."},{"text":"Que el 80 % de los incidentes conocidos se detectó internamente.","feedback":"Correcto. Se conserva el denominador y se evita extrapolar a lo desconocido."},{"text":"Que la detección global de todo lo ocurrido es exactamente 80 %.","feedback":"Se desconoce cuántos incidentes pudieron quedar fuera del conocimiento del equipo."}],"correct":2,"takeaway":"Un indicador necesita población, periodo y límites de interpretación."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d1m5q07","kind":"caso","title":"Ordenar sin inventar una hora","scenario":"Caso docente. A ocurrió a las 14:20 UTC+2 y B a las 12:25 UTC. Ambos relojes están sincronizados.","prompt":"¿Cuál es la secuencia correcta?","terms":["UTC","Cronología"],"options":[{"text":"A ocurrió dos horas después que B.","feedback":"El desplazamiento forma parte de cómo se representa el instante."},{"text":"Ambos ocurrieron a la vez.","feedback":"Después de normalizar aún hay cinco minutos de diferencia."},{"text":"A ocurrió cinco minutos antes que B.","feedback":"Correcto. A equivale a 12:20 UTC y B a 12:25 UTC."},{"text":"B ocurrió 1 h 55 min antes que A.","feedback":"Eso compara las cifras sin convertir el desplazamiento +2."}],"correct":2,"takeaway":"Normaliza instantes conservando sus registros originales y la zona de cada uno.","visual":{"type":"metrics","items":[{"label":"Registro A","value":"14:20 UTC+2"},{"label":"Registro B","value":"12:25 UTC"},{"label":"A normalizado","value":"12:20 UTC"}]}},{"id":"d1m5q08","kind":"caso","title":"Relojes que no cuentan lo mismo","scenario":"Caso docente. Dos registros indican 12:00 UTC, pero se descubre que uno tenía el reloj adelantado cinco minutos.","prompt":"¿Qué debe reflejar la reconstrucción?","terms":["Cronología","Evidencia"],"options":[{"text":"El registro original, el desfase conocido y la incertidumbre o corrección aplicada.","feedback":"Correcto. Se documenta la limitación temporal y cómo se comparan los hechos."},{"text":"Que debe borrarse el registro que incomoda.","feedback":"Perder el original elimina información relevante."},{"text":"Que ocurrieron a la vez porque ambos dicen UTC.","feedback":"La zona común no corrige un reloj desajustado."},{"text":"Una hora nueva elegida para que encaje con el relato.","feedback":"La corrección debe sustentarse en información sobre el reloj, no en una narración deseada."}],"correct":0,"takeaway":"Compartir zona horaria no garantiza que los relojes estén bien ajustados."},{"id":"d1m5q09","kind":"caso","title":"La huella cambió al copiar","scenario":"Caso docente. La copia de análisis no coincide con el hash de referencia, calculado con el mismo algoritmo sobre el archivo conservado.","prompt":"¿Qué actuación conserva mejor la evidencia?","terms":["Hash","Integridad","Cadena de custodia"],"options":[{"text":"Sobrescribir el hash de referencia con el nuevo.","feedback":"Eso oculta que la copia no coincide con la referencia."},{"text":"Editar la copia hasta que visualmente se parezca.","feedback":"La similitud visual no restablece ni demuestra integridad."},{"text":"Conservar originales y resultados, investigar la diferencia y obtener una copia de trabajo verificada.","feedback":"Correcto. La discrepancia se registra y se comprueba antes de usar la copia como equivalente."},{"text":"Declarar automáticamente que una persona concreta la manipuló.","feedback":"La diferencia no determina por sí sola causa ni autor."}],"correct":2,"takeaway":"Una discrepancia requiere investigación y registro, sin borrar la referencia."},{"id":"d1m5q10","kind":"caso","title":"Ochenta y cuatro de ciento veinte","scenario":"Caso docente. En el trimestre se conocen 120 incidentes. 84 se detectaron internamente y el resto por otras vías.","prompt":"¿Qué indicador está bien expresado?","terms":["Denominador","Indicador"],"options":[{"text":"84 % de todos los incidentes posibles.","feedback":"Ochenta y cuatro es el numerador, no el porcentaje, y el alcance sería excesivo."},{"text":"36 % de detección interna.","feedback":"Treinta y seis es la cantidad conocida por otras vías, no el porcentaje interno."},{"text":"70 % de los incidentes conocidos del trimestre se detectaron internamente.","feedback":"Correcto. 84 / 120 × 100 = 70 y se especifican población y periodo."},{"text":"120 % de detección porque todos terminaron siendo conocidos.","feedback":"El porcentaje solicitado depende del origen de detección."}],"correct":2,"takeaway":"El porcentaje pierde sentido si se cambia su denominador.","visual":{"type":"metrics","items":[{"label":"Conocidos","value":"120"},{"label":"Internos","value":"84"},{"label":"Otras vías","value":"36"}]}},{"id":"d1m5q11","kind":"caso","title":"El relevo que sí permite continuar","scenario":"Caso docente. Se crean nuevas reservas, pero faltan diez pedidos en papel por conciliar. Hay prueba de una reserva válida y revisión prevista a las 18:00.","prompt":"¿Qué parte es útil para el siguiente turno?","terms":["Parte de relevo","Aceptación del servicio"],"options":[{"text":"Solo el nombre del técnico que se va a casa.","feedback":"No describe capacidad, limitaciones ni evidencia."},{"text":"Servicio recuperado al cien por cien, porque abre la aplicación.","feedback":"La frase oculta diez operaciones pendientes y exagera el alcance."},{"text":"Diez pedidos sin más datos porque no conviene escribir mucho.","feedback":"Hace falta identificar el trabajo y asignar su seguimiento."},{"text":"Qué funciona, qué queda limitado, prueba disponible, responsable y revisión a las 18:00.","feedback":"Correcto. Permite continuar con una imagen concreta del servicio y sus pendientes."}],"correct":3,"takeaway":"Un buen relevo reduce la necesidad de adivinar el estado real.","visual":{"type":"metrics","items":[{"label":"Funciona","value":"Nuevas reservas"},{"label":"Pendiente","value":"10 pedidos"},{"label":"Revisión","value":"18:00"}]}},{"id":"d1m5q12","kind":"caso","title":"Administrar no es atender","scenario":"Caso docente. El panel de administración vuelve, pero los usuarios no pueden confirmar reservas.","prompt":"¿Cómo se describe mejor el estado?","terms":["Plano de control","Recuperación parcial","Prueba funcional"],"options":[{"text":"Incidente cerrado mientras el panel tenga un gráfico verde.","feedback":"El criterio de cierre debe corresponder al servicio acordado."},{"text":"Recuperación parcial del plano de control, con el servicio de reservas aún pendiente de validación.","feedback":"Correcto. Se distingue la capacidad administrativa de la operación final."},{"text":"Interrupción de toda la infraestructura sin ninguna parte recuperada.","feedback":"El caso indica que el panel ya funciona, así que existe una recuperación parcial."},{"text":"Recuperación total porque vuelve el panel.","feedback":"El panel describe una parte del sistema, no la operación del usuario."}],"correct":1,"takeaway":"Los componentes y los servicios pueden recuperarse a ritmos diferentes."},{"id":"d1m5q13","kind":"caso","title":"La firma necesita una base","scenario":"Caso docente. Se solicita aceptar el servicio. Hay una operación válida, una limitación temporal y un riesgo restante descrito.","prompt":"¿Qué debe hacer la persona con autoridad de aceptación?","terms":["Aceptación del servicio","Riesgo residual"],"options":[{"text":"Aceptar únicamente porque el equipo trabajó muchas horas.","feedback":"El esfuerzo no demuestra el cumplimiento del servicio."},{"text":"Firmar sin leer para evitar retrasos.","feedback":"La firma no sustituye la comprobación de lo que se acepta."},{"text":"Contrastar evidencia y condiciones, decidir dentro de su autoridad y dejar límites y seguimiento.","feedback":"Correcto. La aceptación se apoya en el estado y las condiciones conocidas."},{"text":"Quitar la limitación del informe antes de firmar.","feedback":"Ocultar la limitación impide una decisión informada."}],"correct":2,"takeaway":"Aceptar el servicio exige conocer capacidad, limitaciones y riesgo restante."},{"id":"d1m5q14","kind":"caso","title":"Una lección que cambia algo","scenario":"Caso docente. El incidente mostró que nadie conocía al suplente. La reunión concluye que la próxima vez habrá mejor comunicación.","prompt":"¿Qué acción convierte esa frase en una mejora verificable?","terms":["Lección aprendida","Acción correctiva"],"options":[{"text":"Añadir más personas a un correo sin definir funciones.","feedback":"Aumentar destinatarios no aclara quién puede actuar como suplente."},{"text":"Asignar responsable y fecha para actualizar suplencias y ensayar una activación sin el titular.","feedback":"Correcto. Se define un cambio, quién lo hará y cómo se comprobará."},{"text":"Repetir la misma frase en una diapositiva con más color.","feedback":"Sigue sin existir un cambio comprobable."},{"text":"Cerrar la acción al terminar la reunión.","feedback":"La reunión no demuestra que el problema se haya corregido."}],"correct":1,"takeaway":"Aprender implica una modificación concreta cuyo resultado pueda probarse."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d1m5q15","kind":"reto","title":"Reto: el hash tranquilizador","scenario":"Caso docente. Dos archivos tienen el mismo hash de referencia. El contenido afirma que todas las reservas se completaron, pero los registros de usuarios muestran fallos.","prompt":"¿Qué conclusión es defendible?","terms":["Hash","Evidencia","Integridad"],"options":[{"text":"Los registros de usuarios deben ser falsos porque hay un hash.","feedback":"La huella no demuestra la verdad del contenido del informe."},{"text":"El hash identifica necesariamente al autor del fallo.","feedback":"No determina autoría ni causalidad por sí solo."},{"text":"No se puede revisar ningún informe que tenga hash.","feedback":"La huella ayuda a conservarlo y compararlo, no impide analizarlo."},{"text":"La coincidencia ayuda a comprobar integridad respecto de la referencia, pero la afirmación necesita contraste con otras evidencias.","feedback":"Correcto. Se separa conservación del archivo y veracidad del relato."}],"correct":3,"takeaway":"Un archivo puede conservarse sin cambios y contener una afirmación incorrecta."},{"id":"d1m5q16","kind":"reto","title":"Reto: un porcentaje mejor","scenario":"Caso docente. Un mes se detectan internamente 8 de 10 incidentes conocidos. Otro, 9 de 15. Se usa la misma definición y periodo equivalente.","prompt":"¿Qué comparación es correcta?","terms":["Denominador","Indicador"],"options":[{"text":"La proporción baja del 80 % al 60 %, aunque el número interno sube.","feedback":"Correcto. 8/10 = 0,8 y 9/15 = 0,6. Ambos datos cuentan cosas distintas."},{"text":"La proporción mejora porque nueve es más que ocho.","feedback":"El numerador sube, pero también cambia el denominador."},{"text":"La segunda cifra demuestra por sí sola que hubo menos ataques reales.","feedback":"El recuento de conocidos no mide todos los incidentes que pudieron ocurrir."},{"text":"Ambos meses tienen 90 % porque el mayor numerador es nueve.","feedback":"El porcentaje requiere dividir cada numerador entre su propio total."}],"correct":0,"takeaway":"Volumen detectado y proporción sobre conocidos son indicadores diferentes.","visual":{"type":"metrics","items":[{"label":"Mes A","value":"8 / 10"},{"label":"Mes B","value":"9 / 15"}]}},{"id":"d1m5q17","kind":"reto","title":"Reto: la hipótesis cambia","scenario":"Caso docente. Se sospechó un borrado. La comprobación demuestra que los datos estaban, pero faltaba un permiso.","prompt":"¿Cómo debe quedar el registro?","terms":["Hipótesis","Hecho","Decisión"],"options":[{"text":"Borrar la evidencia del permiso para no contradecir al equipo.","feedback":"El objetivo es comprender y mejorar, no proteger una hipótesis."},{"text":"Mantener el borrado como hecho porque fue la primera explicación.","feedback":"La nueva evidencia exige revisar una explicación provisional."},{"text":"Reescribir toda la cronología para fingir que siempre se conoció la causa.","feedback":"Se perdería trazabilidad de la investigación y de las decisiones tomadas."},{"text":"Conservar la hipótesis inicial como tal, añadir la evidencia que la descarta y documentar el ajuste de la decisión.","feedback":"Correcto. La evolución queda comprensible sin falsear lo que se sabía en cada momento."}],"correct":3,"takeaway":"Actualizar una hipótesis con evidencia es parte de una respuesta rigurosa."},{"id":"d1m5q18","kind":"reto","title":"Reto: acta de relevo completa","scenario":"Caso docente. El próximo turno debe continuar una recuperación parcial sin poder hablar con el equipo saliente.","prompt":"¿Qué paquete permite asumir el trabajo con menos incertidumbre?","terms":["Parte de relevo","Procedencia","Cadena de custodia","Prueba funcional"],"options":[{"text":"Todos los archivos sin nombres, horas ni origen.","feedback":"El volumen no sustituye la procedencia ni un estado comprensible."},{"text":"Una lista de herramientas usadas sin resultados.","feedback":"Las herramientas no describen qué funciona o qué falta."},{"text":"Un vídeo del equipo celebrando el cierre.","feedback":"Puede reflejar satisfacción, pero no prueba capacidad ni deja instrucciones útiles."},{"text":"Estado y pendientes, cronología comparable, evidencias con origen y manejo, prueba funcional, responsable y próxima revisión.","feedback":"Correcto. El conjunto permite entender qué se sabe, qué se acepta y qué debe hacerse después."}],"correct":3,"takeaway":"Un relevo defendible une estado, evidencia y responsabilidad en un recorrido comprobable."}]}],"sources":[{"title":"Presentación docente, día 1, diapositivas 128–138","url":""},{"title":"NIST SP 800-86","url":"https://csrc.nist.gov/pubs/sp/800/86/final"},{"title":"NIST SP 800-184","url":"https://csrc.nist.gov/pubs/sp/800/184/final"},{"title":"NIST SP 800-55 Vol. 1","url":"https://csrc.nist.gov/pubs/sp/800/55/v1/final"}]}]},{"id":2,"title":"Detección, respuesta y recuperación","subtitle":"Cinco misiones para decidir con evidencia","missions":[{"id":1,"slug":"firma","title":"Firma en espera","block":"Responder antes de improvisar","description":"Protegemos una orden sensible y mantenemos las operaciones legítimas.","originalSlide":9,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=1","minutes":30,"concepts":[{"term":"Evento","definition":"Suceso observable en un sistema o servicio.","example":"Una cuenta inicia sesión a las 03:00."},{"term":"Alerta","definition":"Aviso que reclama evaluación porque se cumple un criterio de detección.","example":"Una regla avisa de un acceso fuera del horario habitual."},{"term":"Incidente","definition":"Situación que cumple criterios para una respuesta coordinada ante un perjuicio o amenaza a la seguridad.","example":"Se confirma el uso no autorizado de una cuenta de pagos."},{"term":"Triaje","definition":"Valoración inicial para clasificar, priorizar y asignar atención según evidencia e impacto.","example":"Revisar activo, alcance, urgencia y daño que puede continuar."},{"term":"Preparación","definition":"Capacidades y acuerdos disponibles antes del incidente.","example":"Tener suplentes, permisos y un teléfono fiable del proveedor."},{"term":"Contención","definition":"Medidas que limitan el daño o la propagación mientras se gestiona el incidente.","example":"Retener una transferencia sospechosa."},{"term":"Erradicación","definition":"Eliminación de las causas o accesos que mantienen el compromiso.","example":"Corregir la vía de acceso y retirar la persistencia detectada."},{"term":"Recuperación","definition":"Restablecimiento del servicio con comprobaciones y vigilancia.","example":"Reanudar pagos tras verificar identidad y autorización."},{"term":"SANS","definition":"Organización que publica un modelo práctico de seis fases de respuesta.","example":"Preparación, identificación, contención, erradicación, recuperación y lecciones aprendidas."},{"term":"CSF 2.0","definition":"Marco NIST que organiza resultados de ciberseguridad en gobernar, identificar, proteger, detectar, responder y recuperar.","example":"La autoridad para retener una operación se prepara antes de la alarma."},{"term":"Canal independiente","definition":"Vía fiable de comprobación que no depende de la solicitud sospechosa.","example":"Llamar al teléfono del contrato previamente verificado."},{"term":"Doble control","definition":"Participación de más de una persona con funciones de comprobación y autorización definidas.","example":"Una persona contrasta el cambio y otra autoriza con evidencia."},{"term":"Escalado","definition":"Traslado al nivel de autoridad o especialización que la situación necesita.","example":"Avisar a la suplencia autorizada si la responsable está ausente."},{"term":"Parte de incidente","definition":"Registro de hechos, decisiones, responsables, acciones y comprobaciones.","example":"Anotar qué se retuvo, por qué, quién decidió y cómo terminó."},{"term":"Lecciones aprendidas","definition":"Cambios verificables derivados de lo observado en una respuesta o ejercicio.","example":"Actualizar el contacto fallido y ensayar el relevo."},{"term":"Cola","definition":"Operaciones pendientes de atender en un momento.","example":"Si llegan cuatro pagos y salen tres, queda uno más pendiente."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d2m1q01","kind":"concepto","title":"Una señal no lo cuenta todo","scenario":"En un caso docente, una cuenta inicia sesión fuera de horario y la regla genera un aviso. Aún no se ha comprobado si estaba autorizada.","prompt":"¿Qué sabemos con seguridad?","terms":["Evento","Alerta","Incidente"],"options":[{"text":"Ya existe una intrusión confirmada.","feedback":"El horario es un indicio, no una confirmación de acceso indebido."},{"text":"No puede ser un incidente porque no hay malware.","feedback":"Un incidente puede afectar a cuentas o procesos sin malware."},{"text":"La alerta es falsa hasta demostrar quién es el atacante.","feedback":"La falta de atribución no permite descartar una señal."},{"text":"Ha ocurrido un evento y existe una alerta pendiente de evaluación.","feedback":"La actividad y el aviso son observaciones. La clasificación exige contexto."}],"correct":3,"takeaway":"Separad observación, aviso y conclusión para decidir con evidencia."},{"id":"d2m1q02","kind":"concepto","title":"La primera clasificación","scenario":"La guardia recibe varios avisos y dispone de pocos minutos para decidir cuál atiende primero.","prompt":"¿Qué caracteriza un buen triaje?","terms":["Triaje"],"options":[{"text":"Valorar activo afectado, consecuencias, urgencia y evidencia disponible.","feedback":"Estos datos permiten priorizar y revisar la clasificación al conocer más."},{"text":"Ordenar los avisos por el tamaño del correo recibido.","feedback":"La extensión del mensaje no mide impacto ni urgencia."},{"text":"Investigar al autor por completo antes de clasificar.","feedback":"Esperar una atribución completa retrasa medidas necesarias."},{"text":"Atender siempre primero el equipo más caro.","feedback":"El precio no equivale a criticidad del servicio."}],"correct":0,"takeaway":"El triaje obtiene información suficiente para una primera decisión proporcionada."},{"id":"d2m1q03","kind":"concepto","title":"Seis fases con propósito","scenario":"Repasamos el modelo práctico de SANS utilizado en la clase.","prompt":"¿Qué secuencia recoge sus seis fases?","terms":["SANS","Lecciones aprendidas"],"options":[{"text":"Protección, copia, reinicio, firma, pago y archivo.","feedback":"Son acciones posibles, no las seis fases del modelo."},{"text":"Preparación, contención, restauración y auditoría.","feedback":"Esa lista no representa las seis fases de SANS."},{"text":"Preparación, identificación, contención, erradicación, recuperación y lecciones aprendidas.","feedback":"El modelo distingue las tareas, aunque puedan solaparse y revisarse."},{"text":"Identificación, recuperación, preparación, atribución, publicidad y cierre.","feedback":"Mezcla actividades y omite contención y erradicación."}],"correct":2,"takeaway":"Las fases ayudan a comprobar tareas pendientes, no obligan a una secuencia rígida."},{"id":"d2m1q04","kind":"concepto","title":"Qué consigue una retención","scenario":"Retenemos una transferencia sospechosa, pero aún no hemos investigado la cuenta que la solicitó.","prompt":"¿Qué objetivo hemos cumplido inicialmente?","terms":["Contención","Erradicación"],"options":[{"text":"Erradicar toda presencia del atacante.","feedback":"Retener el pago no corrige el acceso o la causa del engaño."},{"text":"Recuperar por completo el servicio.","feedback":"Aún falta comprobar causa, autorización y funcionamiento."},{"text":"Atribuir el incidente a una persona.","feedback":"La retención no identifica al autor."},{"text":"Contener el daño inmediato de esa operación.","feedback":"La retención limita la pérdida mientras se aclara el compromiso."}],"correct":3,"takeaway":"Una medida puede contener un efecto sin eliminar la causa."},{"id":"d2m1q05","kind":"concepto","title":"La respuesta se prepara","scenario":"Usamos NIST SP 800-61r3 con CSF 2.0 para relacionar la guardia con la gestión.","prompt":"¿Dónde encajan los responsables, inventarios y medidas previas?","terms":["CSF 2.0","Preparación"],"options":[{"text":"Fuera del marco porque no son controles técnicos.","feedback":"El marco incluye resultados organizativos y de gestión."},{"text":"En capacidades previas de gobernar, identificar y proteger, que sostienen la respuesta.","feedback":"La respuesta depende de decisiones y recursos establecidos antes del incidente."},{"text":"Solo en recuperar, cuando termina la investigación.","feedback":"Esperar a la recuperación deja la guardia sin preparación."},{"text":"En una séptima función de CSF llamada improvisar.","feedback":"CSF 2.0 no incluye esa función."}],"correct":1,"takeaway":"NIST conecta detectar, responder y recuperar con la preparación y la mejora continua."},{"id":"d2m1q06","kind":"concepto","title":"Verificar y autorizar","scenario":"Dos personas intervienen en un cambio sensible de cuenta bancaria.","prompt":"¿Qué diseño aporta un doble control útil?","terms":["Doble control","Canal independiente"],"options":[{"text":"Una copia la firma de la otra para ahorrar tiempo.","feedback":"Desaparecen la revisión real y la trazabilidad de responsabilidades."},{"text":"La segunda firma demuestra automáticamente que el proveedor existe.","feedback":"Una firma interna no verifica el origen de la solicitud."},{"text":"Una contrasta la petición por una vía fiable y otra autoriza con evidencia y atribuciones.","feedback":"Las funciones diferenciadas aportan revisión y responsabilidad."},{"text":"Ambas pulsan aceptar sobre el mismo correo sin comprobar nada.","feedback":"Duplicar la aceptación no añade evidencia independiente."}],"correct":2,"takeaway":"El segundo control debe aportar una comprobación efectiva."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d2m1q07","kind":"caso","title":"El teléfono del mensaje","scenario":"Caso docente: un correo exige cambiar el IBAN y ofrece un número urgente para confirmarlo. El contrato conserva otro contacto verificado.","prompt":"¿Qué hacemos primero con la verificación?","terms":["Canal independiente","Contención"],"options":[{"text":"Retener el cambio y comprobarlo mediante el contacto ya verificado.","feedback":"La comprobación usa una fuente que no controla la petición sospechosa."},{"text":"Llamar al número del correo y aceptar si responde con el nombre esperado.","feedback":"El propio emisor puede controlar ese número y conocer el nombre."},{"text":"Responder al mismo correo pidiendo una firma más nítida.","feedback":"La calidad visual no demuestra legitimidad."},{"text":"Autorizar porque el proveedor parece tener prisa.","feedback":"La presión temporal refuerza la necesidad de verificar."}],"correct":0,"takeaway":"Una comprobación independiente necesita un origen fiable previo."},{"id":"d2m1q08","kind":"caso","title":"Dos firmas sobre el mismo engaño","scenario":"Caso docente: dos responsables autorizan un cambio basándose únicamente en una videollamada no contrastada.","prompt":"¿Qué falta para sostener la decisión?","terms":["Doble control","Canal independiente"],"options":[{"text":"Guardar una captura de las dos firmas y cerrar.","feedback":"La captura prueba la aprobación, no la legitimidad del cambio."},{"text":"Procesar primero una transferencia grande para comprobar si llega.","feedback":"Exponer más fondos no es una prueba adecuada de identidad."},{"text":"Contrastar la solicitud y la identidad mediante un canal fiable independiente.","feedback":"La presencia de dos firmantes no corrige la debilidad de su única fuente."},{"text":"Una tercera firma que vea la misma grabación.","feedback":"Más observadores del mismo material no crean una fuente independiente."}],"correct":2,"takeaway":"La independencia de la evidencia importa más que el número de firmas."},{"id":"d2m1q09","kind":"caso","title":"Contener sin vaciar toda la oficina","scenario":"Caso docente: solo una orden presenta un IBAN alterado. Las otras seis están verificadas y no hay indicios de compromiso compartido.","prompt":"¿Qué contención inicial es proporcionada?","terms":["Contención","Triaje"],"options":[{"text":"Eliminar el mensaje y pagar al final del día.","feedback":"Destruye contexto sin comprobar la solicitud."},{"text":"Retener la orden dudosa, investigar su alcance y mantener las verificadas bajo vigilancia.","feedback":"La medida responde al alcance conocido y se amplía si aparecen indicios."},{"text":"Detener indefinidamente todos los pagos por principio.","feedback":"Una paralización general exige justificar su alcance e impacto."},{"text":"Tramitar todas las órdenes para evitar colas.","feedback":"Mantiene el daño posible de la orden sospechosa."}],"correct":1,"takeaway":"El alcance de la contención debe poder revisarse con nueva evidencia."},{"id":"d2m1q10","kind":"caso","title":"La cola también es un resultado","scenario":"Caso docente: empezamos con dos pagos ordinarios pendientes. Llegan cuatro durante el turno. Deben quedar como máximo dos al cierre.","prompt":"¿Cuántos pagos ordinarios hay que completar como mínimo?","terms":["Cola"],"options":[{"text":"Dos pagos.","feedback":"Dejaría cuatro pendientes y superaría el máximo."},{"text":"Tres pagos.","feedback":"Dejaría tres pendientes, uno por encima del límite."},{"text":"Seis pagos obligatoriamente.","feedback":"Vaciar la cola es posible, pero el mínimo exigido es cuatro."},{"text":"Cuatro pagos.","feedback":"Dos iniciales más cuatro nuevos menos cuatro completados dejan dos."}],"correct":3,"takeaway":"Cola final = cola inicial + entradas − operaciones completadas.","visual":{"type":"metrics","items":[{"label":"Pendientes","value":"2"},{"label":"Llegan","value":"4"},{"label":"Máximo final","value":"2"}]}},{"id":"d2m1q11","kind":"caso","title":"El proveedor no responde","scenario":"Caso docente: la transferencia vence pronto y nadie responde al contacto verificado. Tenemos autoridad para mantener la retención y escalar.","prompt":"¿Qué decisión conserva un criterio defendible?","terms":["Escalado","Canal independiente"],"options":[{"text":"Mantener la retención, documentar la verificación pendiente y escalar según el procedimiento.","feedback":"La ausencia de respuesta no confirma la legitimidad del cambio."},{"text":"Aceptar por silencio porque ya hemos intentado llamar.","feedback":"Un intento de contacto no equivale a una confirmación."},{"text":"Usar el número alternativo que acaba de enviar el correo sospechoso.","feedback":"Vuelve a depender de la fuente que debemos contrastar."},{"text":"Borrar la alerta para que otro turno no la repita.","feedback":"Oculta una tarea pendiente y empeora el relevo."}],"correct":0,"takeaway":"Una verificación pendiente debe quedar explícita y con responsable."},{"id":"d2m1q12","kind":"caso","title":"Un parte que permite continuar","scenario":"Caso docente: una compañera toma el relevo después de que hayamos retenido y contrastado una orden.","prompt":"¿Qué registro le permite seguir sin repetir todo?","terms":["Parte de incidente"],"options":[{"text":"El nombre de un grupo atacante escogido por intuición.","feedback":"Una atribución sin evidencia no explica ni justifica la respuesta."},{"text":"Hechos y horas, fuente contrastada, decisión, responsable, resultado y tareas pendientes.","feedback":"Ese conjunto explica lo conocido y lo que todavía debe hacerse."},{"text":"Solo la puntuación de la partida.","feedback":"Resume el juego, pero no permite reconstruir la actuación."},{"text":"Una captura verde sin hora ni identificación del caso.","feedback":"Le falta contexto para relacionarla con una operación concreta."}],"correct":1,"takeaway":"El relevo necesita contexto y decisiones trazables."},{"id":"d2m1q13","kind":"caso","title":"El pago se salvó, el acceso sigue abierto","scenario":"Caso docente: el pago está retenido, pero comprobamos que la sesión comprometida aún puede emitir órdenes. Hay autorización para revocarla.","prompt":"¿Qué siguiente acción se ajusta al hallazgo?","terms":["Contención","Erradicación"],"options":[{"text":"Cambiar únicamente el nombre del expediente.","feedback":"No altera la capacidad de la sesión comprometida."},{"text":"Pedir otra firma sobre las próximas órdenes sin retirar el acceso.","feedback":"Sigue permitiendo solicitudes desde la cuenta comprometida."},{"text":"Revocar el acceso comprometido, comprobar el efecto e investigar la causa para corregirla.","feedback":"Limita nuevas operaciones y conecta la contención con la solución de la causa."},{"text":"Cerrar el incidente porque el primer pago no salió.","feedback":"El acceso mantiene la posibilidad de nuevos daños."}],"correct":2,"takeaway":"Proteger una operación no basta si continúa la vía que generó el problema."},{"id":"d2m1q14","kind":"caso","title":"Una alerta menos vistosa","scenario":"Caso docente: una alarma roja afecta a un entorno de demostración aislado. Otra alerta discreta muestra órdenes no autorizadas en pagos reales.","prompt":"¿Cuál merece atención inmediata según estos datos?","terms":["Triaje","Incidente"],"options":[{"text":"Las órdenes no autorizadas con daño real que puede continuar.","feedback":"La prioridad se relaciona con impacto y urgencia, no con el color."},{"text":"La alarma roja porque la interfaz ya decide la criticidad.","feedback":"El color no sustituye la valoración del servicio afectado."},{"text":"La más antigua aunque el daño ya haya cesado.","feedback":"La antigüedad por sí sola no determina la prioridad."},{"text":"Ninguna hasta atribuir las dos a un actor.","feedback":"Podemos contener un daño sin conocer al autor."}],"correct":0,"takeaway":"Priorizad por consecuencias y capacidad de actuación."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d2m1q15","kind":"reto","title":"La responsable está de vacaciones","scenario":"En el relevo de agosto, el plan nombra a una única persona autorizada para retener pagos. No existe suplencia ni delegación.","prompt":"¿Qué mejora corrige la debilidad principal?","terms":["Preparación","CSF 2.0"],"options":[{"text":"Añadir veinte páginas sobre malware al plan.","feedback":"No resuelve quién puede decidir durante la ausencia."},{"text":"Cambiar la fuente tipográfica del procedimiento.","feedback":"No modifica la autoridad ni la disponibilidad."},{"text":"Permitir que cualquiera autorice cualquier pago.","feedback":"Elimina controles sin establecer responsabilidad adecuada."},{"text":"Definir suplencia, autoridad y contacto alternativo, y ensayar su uso.","feedback":"Convierte una dependencia personal en una capacidad disponible."}],"correct":3,"takeaway":"La preparación incluye autoridad utilizable en condiciones reales."},{"id":"d2m1q16","kind":"reto","title":"No sabemos quién lo hizo","scenario":"Se confirma una orden fraudulenta y su canal de origen. La identidad del autor sigue desconocida.","prompt":"¿Qué afirmación es correcta?","terms":["Incidente","Contención"],"options":[{"text":"Debemos atribuirlo al grupo más conocido que use correo.","feedback":"Las técnicas comunes no identifican una organización."},{"text":"La falta de autor demuestra que fue un error benigno.","feedback":"Desconocer la identidad no invalida el fraude observado."},{"text":"Podemos contener e investigar dejando la atribución como pendiente.","feedback":"La respuesta se guía por daño y evidencia aunque la autoría no esté resuelta."},{"text":"Ninguna medida es válida sin un nombre de atacante.","feedback":"La atribución completa no es condición para limitar el daño."}],"correct":2,"takeaway":"La incertidumbre se registra y se gestiona."},{"id":"d2m1q17","kind":"reto","title":"La recuperación dentro de la respuesta","scenario":"Tras contener y corregir el acceso indebido, el equipo propone reanudar los pagos.","prompt":"¿Qué falta para cerrar de forma razonada?","terms":["Recuperación","Lecciones aprendidas"],"options":[{"text":"Borrar el registro para comenzar con estadísticas limpias.","feedback":"Elimina evidencia y perjudica el aprendizaje."},{"text":"Validar operaciones autorizadas, vigilar el resultado y convertir fallos observados en mejoras.","feedback":"La recuperación comprueba el servicio y el aprendizaje mejora la próxima respuesta."},{"text":"Reconectar y cerrar sin observar el resultado.","feedback":"No demuestra funcionamiento correcto ni ausencia de reincidencia."},{"text":"Esperar a que no aparezca ninguna alerta durante un minuto.","feedback":"La ausencia breve de alertas no sustituye pruebas representativas."}],"correct":1,"takeaway":"Recuperar exige pruebas del servicio, y aprender exige cambios comprobables."},{"id":"d2m1q18","kind":"reto","title":"La misión realmente cumplida","scenario":"En el último relevo, el objetivo exige proteger el pago, registrar la decisión y dejar como máximo dos pagos ordinarios en cola.","prompt":"¿Qué resultado cumple las tres condiciones?","terms":["Parte de incidente","Cola"],"options":[{"text":"Pago protegido y acta completa, pero tres pendientes.","feedback":"Supera el máximo de cola fijado por el caso."},{"text":"Pago protegido y verificado, acta con responsable y dos pagos ordinarios pendientes.","feedback":"Se cumplen protección, trazabilidad y continuidad según el criterio declarado."},{"text":"Pago protegido, ninguna acta y cero pendientes.","feedback":"Falta documentar la decisión aunque la cola esté vacía."},{"text":"Acta completa, pago fraudulento ejecutado y cero pendientes.","feedback":"El registro no compensa el daño que debía evitarse."}],"correct":1,"takeaway":"Un resultado debe contrastarse con todas las condiciones del objetivo."}]}],"sources":[{"title":"NIST SP 800-61r3","url":"https://csrc.nist.gov/pubs/sp/800/61/r3/final"},{"title":"SANS Incident Handler’s Handbook","url":"https://www.sans.org/white-papers/33901"}]},{"id":2,"slug":"rastro","title":"Rastro de salida","block":"Reconstruir lo ocurrido sin inventar al culpable","description":"Conservamos huellas y limitamos la salida de información.","originalSlide":34,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=2","minutes":30,"concepts":[{"term":"Exfiltración","definition":"Salida no autorizada de información fuera de su entorno previsto.","example":"Una sesión envía documentos privados a un destino ajeno."},{"term":"Confidencialidad","definition":"Protección frente al acceso o divulgación no autorizados.","example":"Volver a abrir una aplicación no retira los documentos ya filtrados."},{"term":"Volatilidad","definition":"Facilidad con la que cambia o desaparece una información.","example":"Una sesión activa conserva datos que pueden perderse al terminarla."},{"term":"Retención","definition":"Periodo durante el que una fuente mantiene información recuperable.","example":"Un registro circular conserva solo los últimos diez minutos."},{"term":"Preservación","definition":"Conservación metódica de información relevante y su contexto.","example":"Guardar un registro con origen, hora, responsable e integridad verificable."},{"term":"ATT&CK","definition":"Base de conocimiento MITRE sobre comportamientos adversarios observados.","example":"Describir el uso indebido de una cuenta con un vocabulario común."},{"term":"Táctica","definition":"Objetivo que persigue una acción adversaria.","example":"Obtener acceso a credenciales expresa un objetivo."},{"term":"Técnica","definition":"Forma de conseguir un objetivo adversario.","example":"Un método de acceso puede aparecer en actividades de actores distintos."},{"term":"Procedimiento","definition":"Implementación concreta observada de una técnica en un caso.","example":"La cuenta, herramienta y secuencia utilizadas en una operación determinada."},{"term":"Atribución","definition":"Evaluación de quién puede estar detrás de una actividad, con evidencia y grado de confianza.","example":"Una técnica compartida permite una hipótesis, no una identificación automática."},{"term":"D3FEND","definition":"Grafo de conocimiento MITRE de técnicas defensivas y sus relaciones.","example":"Relacionar una capacidad de defensa con el comportamiento que queremos limitar."},{"term":"Tor","definition":"Red de comunicaciones que también permite servicios onion y tiene usos legítimos e ilícitos.","example":"Un destino onion por sí solo no demuestra que su contenido sea delictivo."},{"term":"Correlación","definition":"Relación entre observaciones para interpretar una secuencia.","example":"Vincular una sesión, el acceso a documentos y un acuse compatible."},{"term":"Revocación","definition":"Retirada de autorización o validez de un acceso.","example":"Invalidar una sesión comprometida y comprobar que deja de operar."},{"term":"Aislamiento","definition":"Limitación de conexiones para reducir el alcance de una actividad.","example":"Impedir salidas por una pasarela mientras se conserva la evidencia."},{"term":"Integridad de la evidencia","definition":"Conservación de la información sin cambios no explicados, con contexto trazable.","example":"Comparar resúmenes criptográficos antes y después de copiar un registro."},{"term":"MITRE","definition":"Organización que mantiene bases de conocimiento como ATT&CK y D3FEND.","example":"Podemos usar su vocabulario para describir un comportamiento y una defensa sin dar por demostrada la autoría."},{"term":"TTP","definition":"Sigla de tácticas, técnicas y procedimientos: objetivo, forma de conseguirlo e implementación concreta de una acción adversaria.","example":"Separamos para qué actuó el adversario, cómo intentó lograrlo y qué ejecución observamos en este caso."},{"term":"APT","definition":"Advanced Persistent Threat. Denominación asociada a amenazas con capacidades y persistencia avanzadas.","example":"Una técnica compartida con un informe sobre una APT no identifica automáticamente al autor del incidente."},{"term":"Ransomware","definition":"Software o actividad de extorsión que puede impedir el acceso a datos o servicios.","example":"Recuperar los archivos cifrados no retira las copias que también pudieron haberse robado."},{"term":"Dark web","definition":"Servicios accesibles mediante redes específicas, utilizados tanto con fines legítimos como ilícitos.","example":"La presencia de una publicación en un servicio onion no demuestra por sí sola que su contenido sea verdadero."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d2m2q01","kind":"concepto","title":"Una copia no recoge lo que salió","scenario":"Un servicio se restaura después de un incidente que incluyó robo de documentos.","prompt":"¿Qué consecuencia puede seguir abierta?","terms":["Exfiltración","Confidencialidad"],"options":[{"text":"La exposición de los datos que ya salieron.","feedback":"La disponibilidad recuperada no revierte una divulgación previa."},{"text":"Ninguna, porque la copia de seguridad ya funciona.","feedback":"Una copia restaura datos propios, no elimina copias ajenas."},{"text":"Solo el color de las alertas antiguas.","feedback":"Puede persistir un perjuicio real para las personas."},{"text":"La exfiltración se deshace al cambiar la contraseña.","feedback":"Cambiar el acceso limita acciones futuras, no retira datos ya obtenidos."}],"correct":0,"takeaway":"La recuperación del servicio y la exposición de información requieren actuaciones propias."},{"id":"d2m2q02","kind":"concepto","title":"La pizarra y el archivador","scenario":"En el caso docente, una fuente desaparece pronto y otra conserva su información durante un mes.","prompt":"¿Cómo priorizamos la preservación?","terms":["Volatilidad","Preservación"],"options":[{"text":"Siempre guardando todo antes de contener.","feedback":"Retrasar toda contención puede permitir daños evitables."},{"text":"Solo por lo fácil que resulte copiar la fuente.","feedback":"La comodidad puede hacer perder la información esencial."},{"text":"Por volatilidad, valor para la investigación y daño que puede continuar.","feedback":"La prioridad combina urgencia de la huella y necesidad de protección."},{"text":"Siempre por el tamaño del archivo.","feedback":"El tamaño no determina cuándo se pierde ni qué demuestra."}],"correct":2,"takeaway":"Conservar y contener necesitan coordinación, no una regla ciega."},{"id":"d2m2q03","kind":"concepto","title":"Objetivo, método y ejecución","scenario":"Usamos ATT&CK para describir comportamientos observados.","prompt":"¿Qué correspondencia es correcta?","terms":["ATT&CK","Táctica","Técnica","Procedimiento"],"options":[{"text":"Táctica: antivirus. Técnica: proveedor. Procedimiento: precio.","feedback":"Mezcla elementos comerciales ajenos a esa clasificación."},{"text":"Táctica: culpable. Técnica: país. Procedimiento: sentencia.","feedback":"El vocabulario de comportamientos no establece autoría ni decisiones judiciales."},{"text":"Los tres términos significan exactamente lo mismo.","feedback":"Distinguir niveles permite describir mejor lo observado."},{"text":"Táctica: objetivo. Técnica: forma de conseguirlo. Procedimiento: ejecución concreta.","feedback":"Distingue niveles sin confundirlos con una identificación del actor."}],"correct":3,"takeaway":"Primero describid el comportamiento real y después nombrad su nivel."},{"id":"d2m2q04","kind":"concepto","title":"El nombre del grupo","scenario":"Una técnica observada aparece en informes públicos de varios grupos.","prompt":"¿Qué permite concluir la coincidencia?","terms":["Atribución","ATT&CK"],"options":[{"text":"Obliga a descartar todos los grupos conocidos.","feedback":"La coincidencia puede orientar sin resolver la atribución."},{"text":"Orienta hipótesis que necesitan más evidencia y alternativas.","feedback":"Muchas técnicas son compartidas y los informes disponibles son parciales."},{"text":"Identifica al grupo con más menciones en Internet.","feedback":"La popularidad no es evidencia de autoría."},{"text":"Demuestra que todos los grupos actuaron juntos.","feedback":"Una técnica común no prueba colaboración."}],"correct":1,"takeaway":"Una similitud de comportamiento no basta para identificar al autor."},{"id":"d2m2q05","kind":"concepto","title":"Un mapa de defensas","scenario":"Seleccionamos una técnica defensiva descrita en D3FEND.","prompt":"¿Qué queda por hacer?","terms":["D3FEND"],"options":[{"text":"Comprar cualquier producto que use su nombre.","feedback":"La marca no demuestra que cubra el comportamiento necesario."},{"text":"Suponer que existe una contramedida única para todos los incidentes.","feedback":"Los escenarios y las consecuencias de los controles varían."},{"text":"Verificar su aplicación, cobertura y efecto en nuestro escenario.","feedback":"El catálogo facilita el razonamiento, pero el resultado depende del entorno."},{"text":"Dar por garantizada la eficacia porque figura en MITRE.","feedback":"El catálogo no certifica cada despliegue o configuración."}],"correct":2,"takeaway":"Una defensa necesita una prueba concreta del efecto esperado."},{"id":"d2m2q06","kind":"concepto","title":"El destino de la historia","scenario":"Un informe menciona un servicio onion accesible mediante Tor.","prompt":"¿Qué interpretación evita una conclusión excesiva?","terms":["Tor","Exfiltración"],"options":[{"text":"La tecnología del destino no demuestra por sí sola delito ni extracción de datos.","feedback":"Hay usos distintos. El hecho requiere evidencia de acceso, contenido y autorización."},{"text":"Toda dirección onion demuestra una fuga confirmada.","feedback":"El formato del destino no prueba una transferencia."},{"text":"Tor garantiza que el contenido publicado es verdadero.","feedback":"El medio de acceso no valida la información."},{"text":"No puede existir delito porque la tecnología tiene usos legítimos.","feedback":"Los usos legítimos no excluyen abusos concretos."}],"correct":0,"takeaway":"Valorad el hecho y las fuentes, no solo la tecnología mencionada."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d2m2q07","kind":"caso","title":"Tres huellas, tres preguntas","scenario":"Caso docente: tenemos una sesión de acceso, un listado de documentos consultados y un acuse fiable de llegada al destino.","prompt":"¿Cómo construir una conclusión sólida?","terms":["Correlación","Exfiltración"],"options":[{"text":"Contar los tres archivos y atribuir un punto de certeza a cada uno.","feedback":"El número de piezas no sustituye la relación entre ellas."},{"text":"Asumir que cualquier acuse pertenece a esos documentos.","feedback":"Hay que demostrar correspondencia y fiabilidad."},{"text":"Relacionar identidad, tiempos y contenido, y comprobar que la transferencia no estaba autorizada.","feedback":"La conexión y el contexto permiten diferenciar acceso, consulta y salida indebida."},{"text":"Usar solo la sesión para afirmar que salió toda la base de datos.","feedback":"Una sesión no demuestra qué datos se transfirieron."}],"correct":2,"takeaway":"La evidencia se conecta por contexto y correspondencia."},{"id":"d2m2q08","kind":"caso","title":"La huella que caduca","scenario":"Caso docente: el estado de sesión caduca en dos minutos y el registro de archivos dura una hora. La pasarela puede aislarse en paralelo.","prompt":"¿Qué reparto coordina investigación y protección?","terms":["Volatilidad","Aislamiento"],"options":[{"text":"Desconectar todo sin valorar qué información desaparece ni quién actúa.","feedback":"La contención requiere conocer efectos y responsabilidades."},{"text":"Preservar la sesión y coordinar el aislamiento, después recoger el registro más duradero.","feedback":"Atiende la huella urgente sin dejar que continúe la salida por falta de coordinación."},{"text":"Esperar una hora para que ambos registros tengan la misma antigüedad.","feedback":"La sesión habrá desaparecido."},{"text":"Copiar primero el registro de una hora porque parece más completo.","feedback":"Puede perderse la fuente más volátil sin necesidad."}],"correct":1,"takeaway":"Priorizar una huella urgente es compatible con contener en paralelo.","visual":{"type":"metrics","items":[{"label":"Sesión","value":"2 min"},{"label":"Registro","value":"60 min"},{"label":"Aislamiento","value":"En paralelo"}]}},{"id":"d2m2q09","kind":"caso","title":"Dos relojes, una secuencia","scenario":"Caso docente: el acceso figura a las 09:10 UTC. El acuse fiable figura a las 10:12 UTC+1 del mismo día. Ambos relojes están sincronizados.","prompt":"¿Qué separación temporal hay?","terms":["Correlación"],"options":[{"text":"Sesenta y dos minutos.","feedback":"Se han restado horas sin normalizar la zona."},{"text":"Menos cincuenta y ocho minutos.","feedback":"La conversión del huso se ha aplicado en sentido incorrecto."},{"text":"No es posible relacionarlos aunque conozcamos ambos husos.","feedback":"Con husos explícitos se puede hacer la comparación, sujeto a la fiabilidad de relojes."},{"text":"Dos minutos.","feedback":"10:12 en UTC+1 equivale a 09:12 UTC. El acceso fue a 09:10 UTC."}],"correct":3,"takeaway":"Normalizad tiempos y documentad incertidumbre de reloj antes de ordenar hechos.","visual":{"type":"metrics","items":[{"label":"Acceso","value":"09:10 UTC"},{"label":"Acuse","value":"10:12 UTC+1"}]}},{"id":"d2m2q10","kind":"caso","title":"La dirección compartida","scenario":"Caso docente: varias personas salen a Internet por la misma dirección pública de un proxy. Una transferencia usa esa dirección.","prompt":"¿Qué debemos evitar?","terms":["Atribución","Correlación"],"options":[{"text":"Identificar a una persona solo por esa dirección compartida.","feedback":"Hace falta correlación adicional con sesiones, tiempos y registros fiables."},{"text":"Buscar los registros del proxy con autorización.","feedback":"Es una fuente pertinente para precisar el origen."},{"text":"Registrar que el origen individual está pendiente.","feedback":"Expresa correctamente el límite de la evidencia."},{"text":"Comprobar si los relojes de las fuentes coinciden.","feedback":"Es necesario para correlacionar con rigor."}],"correct":0,"takeaway":"Una infraestructura compartida limita la precisión de la atribución."},{"id":"d2m2q11","kind":"caso","title":"Un acuse sin contexto","scenario":"Caso docente: llega una captura que dice transferencia completada, sin origen verificable ni identificador de archivo.","prompt":"¿Cómo la tratamos?","terms":["Preservación","Correlación"],"options":[{"text":"La eliminamos porque una fuente imperfecta nunca sirve.","feedback":"Puede aportar pistas si se conserva el contexto y se contrasta."},{"text":"Como indicio que debemos conservar y contrastar, con su limitación explícita.","feedback":"Puede orientar, pero no demuestra por sí sola el contenido ni la autenticidad."},{"text":"Como prueba definitiva de que salieron todos los documentos.","feedback":"La captura no identifica ni verifica ese alcance."},{"text":"La publicamos para que otras personas adivinen el origen.","feedback":"Difundirla no valida la evidencia y puede exponer información."}],"correct":1,"takeaway":"Conservar una pieza no obliga a aceptar todo lo que aparenta afirmar."},{"id":"d2m2q12","kind":"caso","title":"El resumen coincide","scenario":"Caso docente: el hash del registro copiado coincide con el calculado antes de la copia mediante un algoritmo adecuado.","prompt":"¿Qué respalda esa comprobación?","terms":["Integridad de la evidencia"],"options":[{"text":"Que el autor del incidente está identificado.","feedback":"Un resumen criptográfico no determina autoría."},{"text":"Que nunca hubo alteraciones antes del primer cálculo.","feedback":"La comprobación no reconstruye el estado anterior a su punto de partida."},{"text":"Que la copia conserva los mismos bytes bajo la comprobación realizada.","feedback":"Ayuda a demostrar integridad entre esos dos momentos."},{"text":"Que todos los hechos descritos en el registro son verdaderos.","feedback":"La integridad de bytes no certifica la veracidad de su contenido."}],"correct":2,"takeaway":"La integridad técnica y la fiabilidad del contenido responden a preguntas distintas."},{"id":"d2m2q13","kind":"caso","title":"Tres ventanas de conservación","scenario":"Caso docente: la sesión desaparece tras T1, el listado tras T2 y el acuse tras T3. Podemos preservar una huella por turno, además de la contención.","prompt":"¿Qué orden conserva las tres?","terms":["Retención","Preservación"],"options":[{"text":"Sesión en T1, listado en T2 y acuse en T3.","feedback":"Cada huella se conserva antes de que expire su ventana."},{"text":"Acuse en T1, listado en T2 y sesión en T3.","feedback":"La sesión ya no estará disponible en T3."},{"text":"Listado en T1, acuse en T2 y sesión en T3.","feedback":"Se pierde la huella que caduca primero."},{"text":"Cualquier orden porque todas estuvieron disponibles al inicio.","feedback":"Disponibilidad inicial no implica retención ilimitada."}],"correct":0,"takeaway":"El orden debe respetar caducidades y valor de las fuentes.","visual":{"type":"metrics","items":[{"label":"Sesión","value":"Hasta T1"},{"label":"Listado","value":"Hasta T2"},{"label":"Acuse","value":"Hasta T3"}]}},{"id":"d2m2q14","kind":"caso","title":"La orden se envió, ¿funcionó?","scenario":"Caso docente: se solicita revocar una sesión comprometida, pero el registro siguiente muestra nuevas operaciones autorizadas con ella.","prompt":"¿Qué conclusión es adecuada?","terms":["Revocación"],"options":[{"text":"La contención fue completa porque existe un ticket.","feedback":"El ticket registra una petición, no su efecto."},{"text":"Las nuevas operaciones son legítimas por aparecer después.","feedback":"El momento no demuestra legitimidad."},{"text":"El problema se resuelve cambiando la fecha del parte.","feedback":"Modificar el registro no retira el acceso."},{"text":"La contención no está demostrada. Hay que revisar la revocación y las nuevas operaciones.","feedback":"La intención administrativa no equivale a un efecto técnico verificado."}],"correct":3,"takeaway":"Después de actuar, comprobad que la capacidad comprometida ha dejado de funcionar."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d2m2q15","kind":"reto","title":"La guardia sin registros","scenario":"Reto final: falta una hora de registros por una retención insuficiente. En ese intervalo pudo ocurrir una transferencia.","prompt":"¿Cómo redactamos el parte?","terms":["Retención","Correlación"],"options":[{"text":"Hubo transferencia de todos los archivos porque falta el registro.","feedback":"La pérdida de evidencia tampoco demuestra el hecho más grave."},{"text":"Atribuimos el hueco al atacante sin ninguna otra prueba.","feedback":"Puede haber distintas causas para la ausencia de registros."},{"text":"No podemos determinar ese intervalo con esta fuente. Indicamos otras pruebas y la limitación.","feedback":"Separa ausencia de observación de ausencia de actividad."},{"text":"No hubo transferencia porque no aparece registrada.","feedback":"Una fuente incompleta no puede demostrar ausencia."}],"correct":2,"takeaway":"Un hueco de observación exige una conclusión limitada."},{"id":"d2m2q16","kind":"reto","title":"La etiqueta de defensa","scenario":"Reto final: una propuesta presume de cubrir ATT&CK con controles D3FEND, pero no aporta pruebas del entorno.","prompt":"¿Qué petición permite valorar la propuesta?","terms":["ATT&CK","D3FEND"],"options":[{"text":"La garantía de que ya no habrá incidentes.","feedback":"No es una afirmación defendible para una defensa concreta."},{"text":"Un escenario reproducible con fuentes observadas, comportamiento a limitar y resultado medido.","feedback":"Relaciona lenguaje común, implementación y efecto comprobado."},{"text":"Un logotipo más grande en el informe.","feedback":"La presentación no demuestra cobertura operativa."},{"text":"Un porcentaje de cobertura sin denominador ni definición.","feedback":"Sin alcance no podemos interpretar la cifra."}],"correct":1,"takeaway":"Una cobertura útil indica qué se ha probado y bajo qué condiciones."},{"id":"d2m2q17","kind":"reto","title":"El cierre con una pieza perdida","scenario":"Reto final: conservamos sesión y listado, pero perdimos el acuse. La salida está contenida y no existe otra evidencia de llegada.","prompt":"¿Qué cierre expresa lo que sabemos?","terms":["Correlación","Preservación"],"options":[{"text":"Eliminamos el listado para que todas las fuentes coincidan.","feedback":"Destruir evidencia no resuelve una discrepancia."},{"text":"Acceso y consulta documentados, llegada no confirmada con las fuentes disponibles, contención verificada.","feedback":"La conclusión distingue los hechos respaldados de la incertidumbre."},{"text":"Extracción total confirmada porque dos de tres huellas bastan siempre.","feedback":"No existe esa regla universal de mayoría."},{"text":"Ningún hecho puede utilizarse porque falta una pieza.","feedback":"Las fuentes restantes conservan valor para sus preguntas."}],"correct":1,"takeaway":"La calidad del parte depende de ajustar la conclusión al alcance de la prueba."},{"id":"d2m2q18","kind":"reto","title":"El servidor ya vuelve a saludar","scenario":"Reto final: la web está restaurada, pero se confirma que salieron datos personales.","prompt":"¿Qué trabajo debe continuar?","terms":["Exfiltración","Confidencialidad"],"options":[{"text":"Solo cambiar el mensaje de bienvenida.","feedback":"No trata las consecuencias de la salida de datos."},{"text":"Cerrar todo porque una operación técnica ya termina bien.","feedback":"Quedan efectos del incidente por gestionar."},{"text":"Afirmar que los datos recuperados ya no existen fuera.","feedback":"Restaurar una copia no borra las copias ajenas."},{"text":"Valorar alcance y consecuencias para las personas y aplicar las actuaciones de protección pertinentes.","feedback":"Restaurar disponibilidad no elimina la exposición confirmada."}],"correct":3,"takeaway":"Un incidente puede tener consecuencias que duren más que la caída del servicio."}]}],"sources":[{"title":"MITRE ATT&CK FAQ","url":"https://attack.mitre.org/resources/faq/"},{"title":"MITRE ATT&CK Groups","url":"https://attack.mitre.org/groups/"},{"title":"MITRE D3FEND","url":"https://d3fend.mitre.org/about/"}]},{"id":3,"slug":"reapertura","title":"Reapertura por turnos","block":"Recuperar el servicio y proteger a las personas","description":"Comunicamos lo necesario y reabrimos con pruebas completas.","originalSlide":59,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=3","minutes":30,"concepts":[{"term":"Dato personal","definition":"Información sobre una persona identificada o identificable.","example":"Un documento identificativo o una cuenta bancaria asociada a su titular."},{"term":"Brecha de datos personales","definition":"Incidente que ocasiona destrucción, pérdida, alteración o acceso o comunicación no autorizados de datos personales.","example":"Una alteración de expedientes puede ser una brecha aunque no se publiquen."},{"term":"RGPD","definition":"Reglamento General de Protección de Datos de la Unión Europea.","example":"Sus artículos 33 y 34 distinguen notificación a la autoridad y comunicación a personas."},{"term":"Responsable del tratamiento","definition":"Quien determina los fines y medios del tratamiento de datos personales.","example":"La organización que decide para qué y cómo gestiona los expedientes."},{"term":"Autoridad de control","definition":"Organismo de protección de datos competente según el caso.","example":"La notificación se dirige a la autoridad competente, no a un destinatario elegido al azar."},{"term":"Riesgo para las personas","definition":"Posibilidad de consecuencias para los derechos y libertades de las personas afectadas.","example":"Fraude, suplantación, discriminación o pérdida de control de datos."},{"term":"Alto riesgo","definition":"Nivel de riesgo para derechos y libertades que activa la valoración de comunicación a los afectados, con las excepciones legales aplicables.","example":"Exposición utilizable de documentación identificativa y bancaria en un caso con daño grave probable."},{"term":"Notificación de brecha","definition":"Información a la autoridad competente sin dilación indebida y, de ser posible, dentro de 72 horas desde la constancia, salvo riesgo improbable.","example":"Remitir lo conocido y completar después lo pendiente cuando proceda."},{"term":"Comunicación a afectados","definition":"Información a las personas sin dilación indebida cuando sea probable un alto riesgo, salvo excepciones legales aplicables.","example":"Explicar en lenguaje claro lo ocurrido y las medidas útiles."},{"term":"Persistencia","definition":"Capacidad de mantener acceso o presencia a lo largo del tiempo.","example":"Un acceso indebido continúa después de reiniciar el sistema."},{"term":"Erradicación","definition":"Eliminación de las causas o accesos que mantienen el compromiso.","example":"Retirar persistencia y corregir la vía de entrada antes de recuperar."},{"term":"Entorno confiable","definition":"Condiciones verificadas que permiten usar un sistema con el nivel de confianza requerido.","example":"Base limpia, accesos revisados y componentes validados."},{"term":"Validación funcional","definition":"Prueba de que una operación representativa completa produce y registra el resultado previsto.","example":"Acceder, tramitar una solicitud y comprobar su registro final."},{"term":"Reapertura gradual","definition":"Restablecimiento por etapas de usuarios, funciones o capacidad.","example":"Habilitar primero un grupo limitado y ampliar si cumple los criterios."},{"term":"Reversión","definition":"Retorno a una condición prevista si no se cumplen los criterios de avance.","example":"Detener la ampliación y volver al modo seguro ante un fallo definido."},{"term":"Riesgo residual","definition":"Riesgo que permanece tras las medidas aplicadas.","example":"La capacidad recuperada puede seguir expuesta a un aumento de demanda."},{"term":"Suplantación","definition":"Uso de la identidad ajena para hacerse pasar por otra persona.","example":"Alguien utiliza datos de un expediente expuesto para fingir que es su titular."},{"term":"Extorsión","definition":"Presión mediante una amenaza para obtener un beneficio.","example":"Un actor amenaza con divulgar documentos si no recibe un pago."},{"term":"Fuente","definition":"Origen de una información, cuya fiabilidad y contexto deben evaluarse.","example":"Distinguimos lo que afirma un portal criminal de lo que muestran los registros contrastados."},{"term":"Desinformación","definition":"Información falsa o engañosa difundida con intención de inducir a error.","example":"Un actor exagera deliberadamente los datos que posee para aumentar la presión sobre la organización."},{"term":"Aviso inicial","definition":"Comunicación temprana de lo conocido y de las actuaciones necesarias.","example":"Se explica el alcance confirmado, qué sigue investigándose y qué medidas útiles pueden adoptar las personas."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d2m3q01","kind":"concepto","title":"La brecha que no salió en la prensa","scenario":"Una alteración no autorizada cambia expedientes personales, sin evidencia de publicación.","prompt":"¿Puede existir una brecha de datos personales?","terms":["Brecha de datos personales"],"options":[{"text":"No, si la página de inicio sigue disponible.","feedback":"La disponibilidad de la portada no demuestra integridad de los expedientes."},{"text":"Solo si el atacante exige dinero.","feedback":"La existencia de extorsión no es un requisito."},{"text":"Sí. También puede afectar a la integridad o disponibilidad de los datos.","feedback":"La definición no se limita a fugas públicas de información."},{"text":"No, solo existe brecha cuando se publica en Internet.","feedback":"La alteración o pérdida puede cumplir la definición."}],"correct":2,"takeaway":"Revisad confidencialidad, integridad y disponibilidad de los datos personales."},{"id":"d2m3q02","kind":"concepto","title":"El riesgo que debemos valorar","scenario":"Gestionamos una brecha y debemos decidir las actuaciones de protección de datos.","prompt":"¿Qué riesgo centra esta valoración?","terms":["Riesgo para las personas"],"options":[{"text":"Únicamente la caída de ventas de la empresa.","feedback":"El impacto comercial no sustituye la valoración de derechos y libertades."},{"text":"Solo si la empresa saldrá en los periódicos.","feedback":"La reputación de la organización no es el umbral legal de comunicación."},{"text":"El número de mensajes negativos en redes.","feedback":"La visibilidad pública no mide por sí sola el riesgo personal."},{"text":"El riesgo para los derechos y libertades de las personas afectadas.","feedback":"La valoración analiza perjuicios posibles a las personas."}],"correct":3,"takeaway":"La protección de datos centra la decisión en las personas y sus consecuencias."},{"id":"d2m3q03","kind":"concepto","title":"La notificación a la autoridad","scenario":"Repasamos la regla general del artículo 33 del RGPD.","prompt":"¿Qué formulación es correcta?","terms":["RGPD","Notificación de brecha"],"options":[{"text":"Toda alerta técnica se notifica automáticamente aunque no afecte a datos personales.","feedback":"Primero hay que identificar y valorar la brecha y su riesgo."},{"text":"Sin dilación indebida y, de ser posible, en 72 horas desde la constancia, salvo que el riesgo sea improbable.","feedback":"Distingue el inicio del cómputo, la urgencia y la excepción."},{"text":"Siempre hay que esperar 72 horas para reunir pruebas.","feedback":"El plazo no autoriza retrasos injustificados."},{"text":"Solo se notifica cuando ya hay sentencia sobre el atacante.","feedback":"La atribución judicial no es requisito para notificar."}],"correct":1,"takeaway":"La notificación responde a la constancia de la brecha y a la valoración de riesgo."},{"id":"d2m3q04","kind":"concepto","title":"El aviso a las personas","scenario":"Repasamos la regla general del artículo 34 del RGPD, sin excepciones aplicables en el supuesto.","prompt":"¿Cuándo se comunica a las personas afectadas?","terms":["Comunicación a afectados","Alto riesgo"],"options":[{"text":"Solo si alguna persona reclama primero.","feedback":"La comunicación no depende de recibir una reclamación."},{"text":"Nunca si ya hemos informado a la autoridad.","feedback":"Una notificación no sustituye la otra actuación cuando procede."},{"text":"Sin dilación indebida cuando sea probable un alto riesgo para sus derechos y libertades.","feedback":"Es una obligación distinta de informar a la autoridad."},{"text":"Siempre exactamente a las 72 horas.","feedback":"La regla de comunicación a personas es sin dilación indebida, no una espera fija de 72 horas."}],"correct":2,"takeaway":"Autoridad y personas son destinatarios distintos con criterios propios."},{"id":"d2m3q05","kind":"concepto","title":"Cerrar la puerta y reparar la cerradura","scenario":"Se ha aislado el sistema, pero conserva un acceso indebido que reaparece al reconectarlo.","prompt":"¿Qué tarea sigue pendiente?","terms":["Persistencia","Erradicación"],"options":[{"text":"Eliminar la persistencia y corregir las condiciones que mantienen el compromiso.","feedback":"El aislamiento limita el daño, pero no resuelve ese acceso."},{"text":"Cambiar el título del informe de contención a recuperación.","feedback":"Un nombre no cambia el estado del sistema."},{"text":"Declarar recuperado porque estuvo aislado una hora.","feedback":"El tiempo aislado no elimina accesos persistentes."},{"text":"Restaurar la misma configuración comprometida sin revisarla.","feedback":"Puede devolver al servicio la causa del problema."}],"correct":0,"takeaway":"La recuperación necesita una base cuyas condiciones se hayan comprobado."},{"id":"d2m3q06","kind":"concepto","title":"La prueba que llega hasta el final","scenario":"Una aplicación vuelve a mostrar la pantalla de acceso después de restaurarse.","prompt":"¿Qué valida realmente el servicio?","terms":["Validación funcional"],"options":[{"text":"Que el servidor responda a una comprobación de conectividad.","feedback":"La conexión no demuestra la lógica ni la integridad de datos."},{"text":"Que el equipo declare que ha terminado la restauración.","feedback":"La ejecución técnica requiere aceptación funcional."},{"text":"Una operación representativa completa, con permisos, resultado y registro comprobados.","feedback":"La prueba recorre el flujo útil y sus condiciones."},{"text":"Que el logotipo cargue sin tardar.","feedback":"La portada no prueba la transacción."}],"correct":2,"takeaway":"La disponibilidad técnica debe enlazarse con una operación válida."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d2m3q07","kind":"caso","title":"Avisar mientras seguimos trabajando","scenario":"Caso docente: se confirma exposición utilizable de documentos identificativos y bancarios, con alto riesgo probable. No aplica ninguna excepción legal.","prompt":"¿Qué plan combina las actuaciones necesarias?","terms":["Notificación de brecha","Comunicación a afectados"],"options":[{"text":"Ocultar el alcance para evitar que los afectados se preocupen.","feedback":"Impide que adopten medidas útiles y no respeta una comunicación clara."},{"text":"Activar notificación a la autoridad y comunicación útil a afectados mientras se contiene y recupera.","feedback":"La recuperación técnica y la protección de personas pueden avanzar coordinadas."},{"text":"Esperar a restaurar toda la infraestructura antes de informar.","feedback":"La recuperación no suspende las obligaciones de comunicación."},{"text":"Avisar solo en una red social y dar por resueltas ambas actuaciones.","feedback":"Los destinatarios y contenidos requieren canales adecuados."}],"correct":1,"takeaway":"El incidente requiere coordinación técnica, organizativa y de protección de datos."},{"id":"d2m3q08","kind":"caso","title":"El fin de semana también cuenta","scenario":"Caso docente: hay constancia de una brecha el viernes a las 10:00 UTC. Debe notificarse y puede hacerse dentro del plazo.","prompt":"¿Cuándo se cumplen las 72 horas, sin justificar esperar hasta entonces?","terms":["Notificación de brecha"],"options":[{"text":"El miércoles a las 10:00 porque solo cuentan días laborables.","feedback":"El plazo se expresa en horas, no en tres días hábiles."},{"text":"El lunes a las 00:00 UTC.","feedback":"A medianoche aún no han transcurrido 72 horas desde las 10:00."},{"text":"Cuando termine la investigación, sin referencia temporal.","feedback":"La investigación no desplaza indefinidamente la obligación."},{"text":"El lunes a las 10:00 UTC.","feedback":"Son 72 horas transcurridas. Fines de semana no detienen el cómputo."}],"correct":3,"takeaway":"Calculad desde la constancia y actuad sin dilación indebida.","visual":{"type":"metrics","items":[{"label":"Constancia","value":"Viernes 10:00 UTC"},{"label":"72 horas","value":"Lunes 10:00 UTC"}]}},{"id":"d2m3q09","kind":"caso","title":"El recuento aún no está completo","scenario":"Caso docente: la notificación procede y conocemos la naturaleza de la brecha, pero sigue afinándose el número de afectados.","prompt":"¿Cómo evitamos un retraso injustificado?","terms":["Notificación de brecha"],"options":[{"text":"Notificar lo conocido con estimaciones identificadas y completar la información por fases cuando proceda.","feedback":"La información pendiente puede ampliarse sin esperar a conocerlo todo."},{"text":"Inventar una cifra exacta para que el formulario quede completo.","feedback":"La precisión aparente no justifica datos falsos."},{"text":"Esperar varias semanas aunque ya exista constancia y riesgo.","feedback":"El recuento incompleto no autoriza un retraso indefinido."},{"text":"Informar solo al proveedor de informática y cerrar.","feedback":"No sustituye la notificación a la autoridad competente."}],"correct":0,"takeaway":"Las incertidumbres se describen y se actualizan."},{"id":"d2m3q10","kind":"caso","title":"La decisión de no notificar","scenario":"Caso docente: tras valorar los hechos y las medidas aplicadas, el responsable concluye de forma fundada que es improbable el riesgo para las personas.","prompt":"¿Qué debe conservar?","terms":["Responsable del tratamiento","Riesgo para las personas"],"options":[{"text":"Una frase genérica que diga que todo estaba cifrado, sin comprobar las claves.","feedback":"La decisión exige analizar medidas reales y sus condiciones."},{"text":"Documentación de hechos, efectos, medidas y razones de la decisión.","feedback":"La obligación de documentar la brecha permanece aunque no se notifique."},{"text":"Nada, porque no habrá una comunicación externa.","feedback":"La ausencia de notificación no elimina la trazabilidad exigida."},{"text":"Solo el nombre del técnico que prefirió no avisar.","feedback":"Se necesita una valoración razonada, no una preferencia personal."}],"correct":1,"takeaway":"Una excepción aplicada necesita evidencia y justificación."},{"id":"d2m3q11","kind":"caso","title":"El reinicio no ha limpiado la casa","scenario":"Caso docente: tras reiniciar, vuelve un acceso persistente. Existe una base limpia y un procedimiento de reconstrucción autorizado.","prompt":"¿Qué acción permite avanzar con fundamento?","terms":["Persistencia","Entorno confiable"],"options":[{"text":"Reabrir porque el servicio tiene presión de usuarios.","feedback":"La presión no valida una base comprometida."},{"text":"Copiar la configuración afectada a otra máquina sin analizarla.","feedback":"Puede transportar el acceso indebido al nuevo entorno."},{"text":"Investigar y retirar el acceso, reconstruir según el procedimiento y verificar la base antes de abrir.","feedback":"Actúa sobre el compromiso y establece pruebas para recuperar."},{"text":"Reiniciar repetidamente hasta que deje de verse el aviso.","feedback":"La intermitencia no demuestra eliminación de persistencia."}],"correct":2,"takeaway":"Restaurar capacidad y restablecer confianza son comprobaciones relacionadas."},{"id":"d2m3q12","kind":"caso","title":"Una reapertura con freno","scenario":"Caso docente: abrimos al 10 % de usuarios. El criterio exige cero duplicados en operaciones y un plan de reversión definido. Aparecen duplicados.","prompt":"¿Qué hacemos?","terms":["Reapertura gradual","Reversión"],"options":[{"text":"Detener la ampliación y aplicar la reversión prevista mientras investigamos.","feedback":"Se ha incumplido una condición de avance acordada."},{"text":"Abrir al 100 % para que los errores se diluyan en la estadística.","feedback":"Amplía el daño y no corrige duplicados."},{"text":"Cambiar retroactivamente el criterio a cinco duplicados.","feedback":"Desvirtúa la aceptación sin resolver la causa."},{"text":"Ignorarlo porque el acceso funciona.","feedback":"La operación completa incluye integridad del resultado."}],"correct":0,"takeaway":"Una reapertura gradual necesita umbrales de avance y de parada.","visual":{"type":"metrics","items":[{"label":"Usuarios","value":"10 %"},{"label":"Duplicados admitidos","value":"0"},{"label":"Resultado","value":"Duplicados"}]}},{"id":"d2m3q13","kind":"caso","title":"La matrícula fantasma","scenario":"Caso docente: una persona entra y recibe una pantalla de éxito, pero la solicitud no queda registrada.","prompt":"¿La prueba funcional ha terminado bien?","terms":["Validación funcional"],"options":[{"text":"Sí, porque la pantalla muestra éxito.","feedback":"El mensaje no garantiza que el trámite exista."},{"text":"Sí, si el servidor respondió rápido.","feedback":"La rapidez no sustituye corrección."},{"text":"Solo falla si también se cae la conexión.","feedback":"Puede existir un fallo funcional con red disponible."},{"text":"No. Falta el resultado persistido y verificable de la operación.","feedback":"La experiencia visible y el registro final deben ser coherentes."}],"correct":3,"takeaway":"Una prueba completa comprueba el resultado donde debe quedar."},{"id":"d2m3q14","kind":"caso","title":"El aviso que nadie recibió","scenario":"Caso docente: debemos comunicar una brecha de alto riesgo. El canal de correo de afectados está caído y el plan dispone de una vía alternativa fiable.","prompt":"¿Qué decisión protege mejor a las personas?","terms":["Comunicación a afectados"],"options":[{"text":"Marcar todos como informados porque enviamos un intento.","feedback":"Enviar y llegar no son el mismo resultado."},{"text":"Publicar datos personales completos para llamar su atención.","feedback":"La comunicación no debe crear una nueva exposición."},{"text":"Activar la vía alternativa prevista y comprobar alcance y pendientes.","feedback":"La obligación requiere que la información útil llegue por un medio adecuado."},{"text":"Esperar sin plazo a que vuelva el correo.","feedback":"Puede generar una demora injustificada si existe una alternativa."}],"correct":2,"takeaway":"Comprobad la entrega útil del aviso y documentad a quién falta alcanzar."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d2m3q15","kind":"reto","title":"La amenaza en el portal","scenario":"Reto final: un portal criminal afirma haber robado todos los expedientes. Solo existe una muestra aún sin contrastar.","prompt":"¿Qué comunicación interna es rigurosa?","terms":["Riesgo para las personas"],"options":[{"text":"Debemos copiar y difundir toda la muestra para validarla.","feedback":"La difusión innecesaria puede ampliar el daño."},{"text":"Hay una afirmación y una muestra por validar. Contrastaremos alcance y evidencia sin dar lo desconocido por confirmado.","feedback":"Permite actuar e investigar sin aceptar la propaganda como hecho completo."},{"text":"Todos los expedientes están confirmados como robados.","feedback":"La afirmación del actor no demuestra el alcance total."},{"text":"La muestra demuestra que no existe ningún riesgo.","feedback":"Puede ser relevante y exige valoración."}],"correct":1,"takeaway":"Las afirmaciones públicas requieren contraste y límites explícitos."},{"id":"d2m3q16","kind":"reto","title":"El piloto pasa a medias","scenario":"Reto final: seis de diez operaciones de prueba son correctas. Los criterios de aceptación exigen diez de diez antes de ampliar.","prompt":"¿Qué conclusión corresponde?","terms":["Validación funcional","Reapertura gradual"],"options":[{"text":"Basta con que funcionara una operación.","feedback":"No cumple el alcance de prueba requerido por el caso."},{"text":"La aceptación no se cumple. Investigamos las cuatro fallidas antes de ampliar.","feedback":"El resultado se compara con el criterio definido, no con una mayoría improvisada."},{"text":"Abrimos a todos porque la mayoría funcionó.","feedback":"La mayoría no satisface diez de diez."},{"text":"Declaramos un 100 % excluyendo las cuatro fallidas.","feedback":"Cambiar el denominador oculta resultados relevantes."}],"correct":1,"takeaway":"Un piloto genera evidencia para decidir según criterios previos.","visual":{"type":"metrics","items":[{"label":"Correctas","value":"6"},{"label":"Probadas","value":"10"},{"label":"Criterio","value":"10 de 10"}]}},{"id":"d2m3q17","kind":"reto","title":"Un relevo que no pierde a las personas","scenario":"Reto final: la guardia técnica termina y queda seguimiento de avisos y de una medida correctiva.","prompt":"¿Qué cierre facilita la continuidad?","terms":["Responsable del tratamiento","Riesgo residual"],"options":[{"text":"Cerrar el expediente porque acabó el turno del técnico.","feedback":"El final del turno no resuelve tareas pendientes."},{"text":"Dejar solo el enlace al panel de disponibilidad.","feedback":"No refleja avisos, riesgo ni responsabilidades."},{"text":"Asignar todo a una persona ausente sin confirmarlo.","feedback":"Un nombre sin disponibilidad puede dejar tareas sin atención."},{"text":"Registrar estado, evidencia, pendientes, responsables y próxima revisión.","feedback":"Permite conservar la responsabilidad y continuar el seguimiento."}],"correct":3,"takeaway":"El relevo debe hacer visibles los compromisos que permanecen."},{"id":"d2m3q18","kind":"reto","title":"La reapertura defendible","scenario":"Reto final: elegid el resultado que justifica ampliar el servicio en este caso de alto riesgo sin excepciones.","prompt":"¿Qué conjunto está completo?","terms":["Entorno confiable","Validación funcional","Comunicación a afectados"],"options":[{"text":"Avisos procedentes activados, base y accesos revisados, operación validada y vigilancia con reversión.","feedback":"Combina protección de personas, confianza técnica y aceptación del servicio."},{"text":"Web abierta y logo visible, sin comprobaciones adicionales.","feedback":"No demuestra operación íntegra ni actuaciones hacia personas."},{"text":"Avisos enviados, pero el acceso comprometido sigue activo.","feedback":"La comunicación no corrige la condición insegura."},{"text":"Base limpia, pero ninguna operación completa ni seguimiento.","feedback":"Falta validar la capacidad útil y controlar la ampliación."}],"correct":0,"takeaway":"Ampliar exige evidencias técnicas y organizativas coherentes."}]}],"sources":[{"title":"RGPD, artículos 33 y 34","url":"https://eur-lex.europa.eu/eli/reg/2016/679/oj/eng?locale=es"},{"title":"AEPD, notificación de brechas de datos personales","url":"https://www.aepd.es/derechos-y-deberes/cumple-tus-deberes/medidas-de-cumplimiento/brechas-de-datos-personales-notificacion"},{"title":"AEPD, brechas de gran impacto","url":"https://www.aepd.es/preguntas-frecuentes/2-tus-obligaciones-como-responsable-del-tratamiento/11-brechas-de-datos-personales/FAQ-0234-que-ocurre-en-los-casos-de-brechas-de-gran-impacto"}]},{"id":4,"slug":"enlace","title":"El enlace estrecho","block":"Defender la disponibilidad","description":"Localizamos el cuello de botella y medimos el servicio que llega.","originalSlide":84,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=4","minutes":30,"concepts":[{"term":"DDoS","definition":"Ataque distribuido que pretende impedir o degradar el servicio agotando recursos.","example":"La conexión se satura aunque el atacante no acceda a una cuenta."},{"term":"Disponibilidad","definition":"Posibilidad de acceder y usar un servicio cuando se necesita.","example":"Una persona puede completar el trámite en el plazo previsto."},{"term":"Ancho de banda","definition":"Capacidad de transmisión de una conexión expresada por unidad de tiempo.","example":"Un enlace de 100 Mb/s no admite sostenidamente 180 Mb/s."},{"term":"Mb/s","definition":"Megabits por segundo, unidad de tasa de transmisión.","example":"100 Mb/s expresa ritmo, no una cantidad almacenada."},{"term":"Cuello de botella","definition":"Recurso cuya capacidad limita el rendimiento del conjunto.","example":"Una conexión saturada limita una aplicación con servidores libres."},{"term":"Filtrado","definition":"Selección de comunicaciones que se permiten o rechazan conforme a reglas.","example":"Un proveedor retira carga hostil antes del enlace del cliente."},{"term":"Mitigación aguas arriba","definition":"Defensa aplicada antes del recurso que queremos proteger dentro del recorrido del tráfico.","example":"Retirar tráfico antes de una conexión limitada."},{"term":"Tráfico legítimo","definition":"Comunicaciones correspondientes al uso autorizado del servicio.","example":"Solicitudes de estudiantes que necesitan matricularse."},{"term":"Capacidad útil","definition":"Trabajo legítimo y válido que puede completarse por intervalo.","example":"Solicitudes autorizadas que terminan correctamente cada minuto."},{"term":"Eficacia","definition":"Grado de consecución de un objetivo bajo condiciones definidas.","example":"Atender al menos el 85 % de la demanda legítima del turno."},{"term":"Denominador","definition":"Conjunto o cantidad de referencia de una proporción.","example":"La demanda legítima prevista es el denominador de entrega útil."},{"term":"Comparación controlada","definition":"Contraste entre alternativas con condiciones comparables y cambio identificado.","example":"Misma demanda y duración, cambiando solo la posición del filtro."},{"term":"Dependencia del proveedor","definition":"Necesidad de una capacidad externa para conservar o recuperar el servicio.","example":"Poder activar un filtrado que solo administra el operador de red."},{"term":"Riesgo residual","definition":"Riesgo que permanece tras aplicar las medidas.","example":"La configuración soporta la carga actual, pero no un aumento previsto."},{"term":"Control compensatorio","definition":"Medida que cubre una necesidad cuando otra protección no puede utilizarse como estaba prevista.","example":"Activar una alternativa de atención mientras se recupera el acceso principal."},{"term":"Tolerancia","definition":"Límite de variación o exposición admitido por criterios establecidos.","example":"Un máximo de operaciones pendientes durante la mitigación."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d2m4q01","kind":"concepto","title":"Ataque sin entrar","scenario":"Un servicio deja de atender porque recibe una carga hostil desde muchas fuentes. No hay evidencia de acceso a cuentas.","prompt":"¿Qué consecuencia describe un DDoS?","terms":["DDoS","Disponibilidad"],"options":[{"text":"Únicamente robo de contraseñas.","feedback":"Un DDoS puede afectar al servicio sin comprometer una cuenta."},{"text":"Siempre extracción de la base de datos.","feedback":"La indisponibilidad no demuestra exfiltración."},{"text":"Cualquier pico legítimo de usuarios, por definición.","feedback":"Una demanda intensa no implica intención hostil."},{"text":"Pérdida o degradación de disponibilidad por agotamiento de recursos.","feedback":"La denegación de servicio no necesita robo de credenciales."}],"correct":3,"takeaway":"Distinguid la indisponibilidad observada de otras consecuencias no demostradas."},{"id":"d2m4q02","kind":"concepto","title":"Capacidad por segundo","scenario":"El enlace tiene una capacidad declarada de 100 Mb/s.","prompt":"¿Qué representa la unidad?","terms":["Ancho de banda","Mb/s"],"options":[{"text":"Cien segundos de recuperación.","feedback":"La unidad no expresa duración de una interrupción."},{"text":"Una tasa de transmisión de cien megabits por segundo.","feedback":"Es una cantidad de información por unidad de tiempo."},{"text":"Cien megabytes almacenados en el servidor.","feedback":"Confunde tasa con almacenamiento y bits con bytes."},{"text":"Cien usuarios simultáneos exactamente.","feedback":"El número de usuarios depende de su demanda."}],"correct":1,"takeaway":"Leed las unidades antes de comparar demanda y capacidad."},{"id":"d2m4q03","kind":"concepto","title":"El tramo que manda","scenario":"La aplicación puede atender más solicitudes, pero la conexión previa está saturada.","prompt":"¿Dónde está el cuello de botella descrito?","terms":["Cuello de botella"],"options":[{"text":"En el último gráfico del panel.","feedback":"La posición visual no determina el recurso limitante."},{"text":"En todos los componentes por igual.","feedback":"Los datos del caso señalan un límite concreto."},{"text":"En la conexión previa.","feedback":"Ese recurso impide que la capacidad libre posterior se aproveche."},{"text":"Siempre en el servidor con más memoria.","feedback":"La cantidad de memoria no identifica el límite observado."}],"correct":2,"takeaway":"Localizad el recurso agotado antes de elegir la medida."},{"id":"d2m4q04","kind":"concepto","title":"La posición del filtro","scenario":"Queremos proteger un enlace limitado frente a carga hostil que lo atraviesa.","prompt":"¿Qué ubicación puede impedir que esa carga consuma el enlace?","terms":["Mitigación aguas arriba","Filtrado"],"options":[{"text":"Antes del enlace, con capacidad y reglas adecuadas.","feedback":"Retirar carga previamente evita que compita por ese recurso."},{"text":"Solo después del enlace, en la aplicación.","feedback":"La carga ya ha usado o competido por el enlace."},{"text":"En una máquina que no participa en el recorrido.","feedback":"No modifica el tráfico que alcanza el recurso."},{"text":"En cualquier punto, porque el orden nunca importa.","feedback":"La posición determina qué recurso queda protegido."}],"correct":0,"takeaway":"La defensa debe actuar a tiempo para proteger el recurso que limita el servicio."},{"id":"d2m4q05","kind":"concepto","title":"Tráfico y trabajo útil","scenario":"El panel informa de paquetes descartados y transacciones completadas.","prompt":"¿Qué dato conecta mejor con la capacidad útil del servicio?","terms":["Capacidad útil","Tráfico legítimo"],"options":[{"text":"Todos los paquetes recibidos, incluidos los hostiles.","feedback":"El volumen total puede aumentar mientras el servicio empeora."},{"text":"La cantidad de capturas guardadas por el equipo.","feedback":"Documentar no equivale a entregar servicio."},{"text":"Operaciones legítimas completadas correctamente por intervalo.","feedback":"Relaciona capacidad y resultado que necesitan las personas."},{"text":"El número de reglas configuradas.","feedback":"Describe configuración, no trabajo entregado."}],"correct":2,"takeaway":"Medid el resultado legítimo que el servicio debe producir."},{"id":"d2m4q06","kind":"concepto","title":"Una cifra con apellido","scenario":"Un informe afirma que la defensa funciona al 90 %, sin explicar el cálculo.","prompt":"¿Qué falta para interpretar la eficacia?","terms":["Eficacia","Denominador"],"options":[{"text":"Otra cifra más alta sin explicación.","feedback":"Aumentar el porcentaje no corrige su falta de contexto."},{"text":"Objetivo, numerador, denominador, periodo y condiciones observadas.","feedback":"La misma cifra puede describir fenómenos diferentes."},{"text":"El color corporativo del gráfico.","feedback":"No aporta significado al porcentaje."},{"text":"Solo la marca del producto.","feedback":"La marca no define la medida ni su población."}],"correct":1,"takeaway":"Una proporción útil permite reconstruir qué se ha contado."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d2m4q07","kind":"caso","title":"La puerta estrecha","scenario":"Caso docente: llegan 60 Mb/s legítimos y 120 Mb/s hostiles a un enlace de 100 Mb/s. Un filtro anterior retira 100 Mb/s hostiles sin tocar lo legítimo.","prompt":"¿Qué carga queda para atravesar el enlace?","terms":["Mitigación aguas arriba","Ancho de banda"],"options":[{"text":"180 Mb/s porque filtrar no altera la carga.","feedback":"El supuesto establece que se retiran 100 antes del enlace."},{"text":"60 Mb/s porque desaparece todo el tráfico hostil.","feedback":"Se retiran 100 de 120, por lo que quedan 20 hostiles."},{"text":"100 Mb/s porque la capacidad siempre se llena.","feedback":"La capacidad es un límite, no la demanda restante."},{"text":"80 Mb/s. Cabe bajo estas condiciones del modelo.","feedback":"Quedan 60 legítimos y 20 hostiles: 80 en total."}],"correct":3,"takeaway":"Carga restante = tráfico legítimo + tráfico hostil no retirado.","visual":{"type":"metrics","items":[{"label":"Legítimo","value":"60 Mb/s"},{"label":"Hostil","value":"120 Mb/s"},{"label":"Enlace","value":"100 Mb/s"},{"label":"Retirado antes","value":"100 Mb/s"}]}},{"id":"d2m4q08","kind":"caso","title":"La defensa llegó al otro lado","scenario":"Caso docente: mantenemos esos 60 Mb/s legítimos y 120 hostiles, pero el filtro está después del enlace de 100 Mb/s.","prompt":"¿Qué problema sigue sin resolver por sí solo?","terms":["Cuello de botella","Filtrado"],"options":[{"text":"La competencia de 180 Mb/s por el enlace previo de 100 Mb/s.","feedback":"El filtrado posterior no evita la carga que ya alcanzó el recurso limitado."},{"text":"Que la aplicación reciba todos los paquetes descartados.","feedback":"El filtro puede proteger la aplicación, aunque no ese tramo anterior."},{"text":"Que nunca pueda existir ninguna mejora defensiva.","feedback":"Puede mejorar otros recursos. El límite concreto sigue siendo el enlace."},{"text":"Que la tasa de entrada se convierta automáticamente en 80 Mb/s.","feedback":"Eso solo ocurriría si la retirada se aplicase antes del enlace."}],"correct":0,"takeaway":"Una medida puede ayudar a un componente y dejar expuesto otro."},{"id":"d2m4q09","kind":"caso","title":"El filtro se convierte en la cola","scenario":"Caso docente: un dispositivo anterior solo puede procesar 80 Mb/s y recibe 180 Mb/s. No dispone de otra vía de mitigación.","prompt":"¿Qué limitación hay que valorar?","terms":["Cuello de botella","Filtrado"],"options":[{"text":"Solo el tamaño de su pantalla de administración.","feedback":"El problema es de capacidad del procesamiento."},{"text":"El propio dispositivo puede convertirse en un nuevo cuello de botella.","feedback":"La ubicación ayuda, pero su capacidad también debe ser suficiente."},{"text":"Ninguna, porque cualquier filtro anterior tiene capacidad ilimitada.","feedback":"El caso establece una capacidad de 80 Mb/s."},{"text":"Que sus reglas cambiarán por sí solas la velocidad del enlace.","feedback":"No existe ese efecto automático."}],"correct":1,"takeaway":"Una defensa necesita capacidad suficiente en el punto donde actúa.","visual":{"type":"metrics","items":[{"label":"Entrada","value":"180 Mb/s"},{"label":"Filtro","value":"80 Mb/s"}]}},{"id":"d2m4q10","kind":"caso","title":"Setenta y cinco por ciento","scenario":"Caso docente: llegan 60 Mb/s legítimos y 120 hostiles. Un filtro anterior elimina el 75 % de lo hostil y no bloquea lo legítimo. El enlace admite 100 Mb/s.","prompt":"¿Cuál es la carga restante?","terms":["Filtrado","Ancho de banda"],"options":[{"text":"135 Mb/s.","feedback":"Se ha aplicado mal el porcentaje de retirada."},{"text":"60 Mb/s porque 75 % equivale a eliminar todo.","feedback":"Queda una cuarta parte del tráfico hostil."},{"text":"90 Mb/s: 60 legítimos y 30 hostiles.","feedback":"El 25 % de 120 es 30. La suma es 90."},{"text":"30 Mb/s en total.","feedback":"Ese valor es solo el tráfico hostil restante."}],"correct":2,"takeaway":"Aplicad la tasa a su población correcta antes de sumar cargas.","visual":{"type":"metrics","items":[{"label":"Legítimo","value":"60 Mb/s"},{"label":"Hostil","value":"120 Mb/s"},{"label":"Retirada hostil","value":"75 %"},{"label":"Capacidad","value":"100 Mb/s"}]}},{"id":"d2m4q11","kind":"caso","title":"El objetivo del 85 %","scenario":"Caso docente: la demanda legítima es de 60 operaciones en un turno. Debemos completar al menos el 85 %.","prompt":"¿Cuál es el mínimo de operaciones correctas?","terms":["Capacidad útil","Denominador"],"options":[{"text":"51 operaciones.","feedback":"0,85 × 60 = 51."},{"text":"49 operaciones.","feedback":"49 de 60 es aproximadamente un 81,7 %."},{"text":"50 operaciones.","feedback":"50 de 60 es aproximadamente un 83,3 %."},{"text":"60 operaciones obligatoriamente.","feedback":"Es deseable, pero el umbral declarado se alcanza con 51."}],"correct":0,"takeaway":"Traducid el porcentaje del objetivo a una cantidad verificable.","visual":{"type":"metrics","items":[{"label":"Demanda","value":"60"},{"label":"Objetivo","value":"85 %"}]}},{"id":"d2m4q12","kind":"caso","title":"Mejoró, pero aún no llega","scenario":"Caso docente: completamos 48 de 60 operaciones legítimas. El objetivo es al menos el 85 %.","prompt":"¿Qué diagnóstico es correcto?","terms":["Eficacia","Capacidad útil"],"options":[{"text":"Entregamos el 85 % porque 48 es una cifra alta.","feedback":"La interpretación necesita el denominador 60."},{"text":"Faltan doce operaciones para cumplir el 85 %.","feedback":"Doce faltan para el 100 %, no para el 85 %."},{"text":"No puede calcularse sin saber quién atacó.","feedback":"La entrega útil se calcula con demanda y operaciones completadas."},{"text":"Entregamos el 80 % y faltan tres operaciones para llegar a 51.","feedback":"48/60 = 0,80. El mínimo del objetivo es 51."}],"correct":3,"takeaway":"Un progreso puede ser real y seguir por debajo del objetivo.","visual":{"type":"metrics","items":[{"label":"Completadas","value":"48"},{"label":"Demanda","value":"60"},{"label":"Mínimo","value":"51"}]}},{"id":"d2m4q13","kind":"caso","title":"Ahora el límite está dentro","scenario":"Caso docente: el enlace admite 100 solicitudes por minuto y ya no se satura. La aplicación solo completa 40. Llegan 70 solicitudes legítimas.","prompt":"¿Qué límite debemos tratar ahora?","terms":["Cuello de botella","Capacidad útil"],"options":[{"text":"Afirmar que se completan 70 porque todas llegan a la aplicación.","feedback":"Llegada y finalización son etapas diferentes."},{"text":"Bloquear a 30 usuarios y declarar demanda igual a 40.","feedback":"Reduce artificialmente el denominador y excluye necesidad legítima."},{"text":"La capacidad de la aplicación, actualmente de 40 por minuto.","feedback":"El enlace tiene margen para la demanda, pero la aplicación no."},{"text":"Comprar más enlace como única acción.","feedback":"El cuello descrito no está en la conexión."}],"correct":2,"takeaway":"El cuello puede desplazarse después de aplicar una medida.","visual":{"type":"metrics","items":[{"label":"Enlace","value":"100/min"},{"label":"Aplicación","value":"40/min"},{"label":"Demanda","value":"70/min"}]}},{"id":"d2m4q14","kind":"caso","title":"La reserva usa la misma tubería","scenario":"Caso docente: la ruta de reserva comparte exactamente el tramo saturado con la principal. No se amplía ese tramo.","prompt":"¿Qué debemos esperar de esa reserva?","terms":["Dependencia del proveedor","Cuello de botella"],"options":[{"text":"Elimina la necesidad de hablar con el proveedor.","feedback":"La capacidad externa sigue siendo una dependencia."},{"text":"No aporta independencia frente a la saturación del tramo compartido.","feedback":"Las dos alternativas conservan el mismo límite relevante."},{"text":"Duplica automáticamente el ancho de banda disponible.","feedback":"El tramo compartido mantiene su capacidad."},{"text":"Garantiza que todo tráfico legítimo tendrá prioridad.","feedback":"No se ha descrito ninguna garantía de priorización."}],"correct":1,"takeaway":"Las alternativas deben analizarse por sus dependencias comunes."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d2m4q15","kind":"reto","title":"El marcador de la última guardia","scenario":"Reto final: completamos 620 de 800 operaciones legítimas. El mínimo acordado es el 85 %.","prompt":"¿Qué falta para cumplir el objetivo?","terms":["Denominador","Eficacia"],"options":[{"text":"Nada, porque se completaron más de quinientas.","feedback":"La cantidad absoluta no basta para comparar con el 85 %."},{"text":"60 operaciones más, hasta 680.","feedback":"0,85 × 800 = 680. Llevamos 620, equivalentes al 77,5 %."},{"text":"20 operaciones más.","feedback":"640 de 800 sería un 80 %."},{"text":"180 operaciones más obligatoriamente.","feedback":"180 alcanzarían el 100 %, pero el mínimo es 680."}],"correct":1,"takeaway":"El objetivo debe comprobarse contra la demanda completa del alcance.","visual":{"type":"metrics","items":[{"label":"Completadas","value":"620"},{"label":"Demanda","value":"800"},{"label":"Objetivo","value":"85 %"}]}},{"id":"d2m4q16","kind":"reto","title":"El panel presume de bloqueos","scenario":"Reto final: una defensa bloquea el 99 % del tráfico hostil, pero solo 70 de 100 operaciones legítimas terminan. El objetivo exige 85.","prompt":"¿Qué conclusión podemos sostener?","terms":["Capacidad útil","Eficacia"],"options":[{"text":"El objetivo está cumplido porque 99 supera 85.","feedback":"Compara porcentajes con denominadores diferentes."},{"text":"Los 30 usuarios pendientes son necesariamente atacantes.","feedback":"Su legitimidad está establecida en el caso."},{"text":"La retirada hostil no puede medirse nunca.","feedback":"Puede medirse con el alcance y etiquetado adecuados."},{"text":"La retirada hostil es alta, pero el objetivo de servicio todavía no se cumple.","feedback":"Son dos medidas distintas y la entrega útil queda en el 70 %."}],"correct":3,"takeaway":"Un indicador defensivo no sustituye al resultado del servicio."},{"id":"d2m4q17","kind":"reto","title":"Una comparación que enseña algo","scenario":"Reto final: queremos saber si mover el filtro antes del enlace mejora el resultado.","prompt":"¿Qué comparación es más informativa?","terms":["Comparación controlada"],"options":[{"text":"Misma demanda, duración y criterios, cambiando solo la ubicación y anotando sus efectos.","feedback":"Aísla el cambio que queremos interpretar."},{"text":"Cambiar demanda, objetivo, filtro y duración simultáneamente.","feedback":"Impide atribuir con claridad la diferencia observada."},{"text":"Comparar dos porcentajes sin conocer sus poblaciones.","feedback":"No sabemos si representan el mismo resultado."},{"text":"Escoger solo la captura con mayor puntuación.","feedback":"Una selección parcial no permite una comparación reproducible."}],"correct":0,"takeaway":"Una comparación útil identifica qué cambió y qué condiciones se mantuvieron."},{"id":"d2m4q18","kind":"reto","title":"Cabe justo, pero la noche es larga","scenario":"Reto final: tras mitigar, la carga es de 100 Mb/s sobre un enlace de 100 Mb/s. Se espera un aumento del 10 % de la carga total, con la misma composición.","prompt":"¿Qué valoración es defendible?","terms":["Riesgo residual","Tolerancia"],"options":[{"text":"El 10 % adicional no cambia una tasa de transmisión.","feedback":"Aumenta la demanda y puede superar el límite."},{"text":"Toda mitigación ha sido inútil porque queda riesgo.","feedback":"Puede haber reducido el daño aunque necesite ajuste."},{"text":"La carga actual cabe en el modelo, pero falta margen ante el aumento previsto.","feedback":"El nuevo nivel sería 110 Mb/s si se mantiene la composición y no cambia la medida."},{"text":"Existe seguridad absoluta porque demanda y capacidad coinciden.","feedback":"No hay margen para la variación prevista."}],"correct":2,"takeaway":"Revisad el riesgo restante y las señales que activan nuevas medidas.","visual":{"type":"metrics","items":[{"label":"Actual","value":"100 Mb/s"},{"label":"Capacidad","value":"100 Mb/s"},{"label":"Previsión","value":"+10 %"}]}}]}],"sources":[{"title":"Material docente original, diapositivas 78–84","url":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=4"},{"title":"NIST SP 800-61r3","url":"https://csrc.nist.gov/pubs/sp/800/61/r3/final"}]},{"id":5,"slug":"matricula","title":"Matrícula en hora punta","block":"Proteger sin expulsar a usuarios legítimos","description":"Equilibramos capacidad, filtrado y atención al alumnado.","originalSlide":103,"originalUrl":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=5","minutes":30,"concepts":[{"term":"Falso positivo","definition":"Caso legítimo que el control clasifica erróneamente como problemático.","example":"Un estudiante autorizado queda bloqueado por el filtro."},{"term":"Falso negativo","definition":"Caso problemático que el control no identifica como tal.","example":"Una solicitud hostil atraviesa el filtro sin detectarse."},{"term":"Umbral","definition":"Valor o condición a partir del cual una regla cambia su decisión.","example":"Una regla más estricta rechaza solicitudes con menos indicios."},{"term":"Tasa de falsos positivos","definition":"Proporción de casos legítimos clasificados erróneamente como problemáticos entre los casos legítimos evaluados.","example":"Ocho bloqueados de cien legítimos representan un 8 %."},{"term":"Denominador","definition":"Población o cantidad sobre la que se calcula una proporción.","example":"Alumnado que debía atenderse, no solo el que consiguió entrar."},{"term":"Cobertura","definition":"Parte de sistemas, personas o casos incluida en la observación.","example":"La muestra de pruebas puede cubrir una facultad y dejar otra fuera."},{"term":"Muestra contrastada","definition":"Conjunto de casos cuyo estado real se ha comprobado para interpretar el resultado del control.","example":"Solicitudes conocidas como legítimas y hostiles usadas para evaluar el filtro."},{"term":"Tráfico legítimo","definition":"Comunicaciones del uso autorizado del servicio.","example":"Un estudiante que reintenta una matrícula sigue necesitando atención."},{"term":"Capacidad útil","definition":"Trabajo legítimo y correcto completado por intervalo.","example":"Matrículas registradas válidamente durante la ventana."},{"term":"Cuello de botella","definition":"Recurso que limita el rendimiento del conjunto.","example":"La base de datos atiende menos operaciones que las que admite la red."},{"term":"Comparación controlada","definition":"Comparación con condiciones equivalentes y un cambio identificado.","example":"Probar dos umbrales sobre el mismo conjunto etiquetado."},{"term":"Eficacia","definition":"Grado en que una medida consigue el objetivo definido bajo las condiciones de prueba.","example":"Llegar al 90 % del alumnado atendido con los errores medidos."},{"term":"Riesgo residual","definition":"Riesgo que queda después de las medidas aplicadas.","example":"Algunos estudiantes siguen necesitando atención por una vía alternativa."},{"term":"Control compensatorio","definition":"Medida que cubre una necesidad cuando otra protección no puede utilizarse como estaba previsto.","example":"Una atención alternativa con trazabilidad mientras se corrige el filtro."},{"term":"Trazabilidad","definition":"Posibilidad de reconstruir qué ocurrió, cuándo y con qué responsabilidad.","example":"Registrar rechazos, revisión y resolución de cada caso pendiente."},{"term":"Cola","definition":"Operaciones que esperan atención.","example":"Las nuevas solicitudes superan la capacidad y se acumulan."}],"sections":[{"id":"conceptos","label":"Conceptos","questions":[{"id":"d2m5q01","kind":"concepto","title":"El estudiante que parecía sospechoso","scenario":"El filtro rechaza una solicitud cuya legitimidad se ha comprobado.","prompt":"¿Qué resultado observamos?","terms":["Falso positivo"],"options":[{"text":"Una garantía de eficacia absoluta.","feedback":"Un error sobre un usuario legítimo contradice esa afirmación."},{"text":"Un falso positivo.","feedback":"El control marca como problemática una actividad legítima."},{"text":"Un falso negativo.","feedback":"Ese sería un caso problemático que no se detecta."},{"text":"Un verdadero positivo.","feedback":"La clasificación problemática sería correcta en un caso realmente hostil."}],"correct":1,"takeaway":"Los errores deben clasificarse según el estado real del caso."},{"id":"d2m5q02","kind":"concepto","title":"El tráfico que se coló","scenario":"Una solicitud contrastada como hostil atraviesa el filtro sin identificarse.","prompt":"¿Qué resultado observamos?","terms":["Falso negativo"],"options":[{"text":"Una operación legítima por definición.","feedback":"Que el filtro deje pasar algo no lo convierte en legítimo."},{"text":"Una prueba de que nunca hubo ataque.","feedback":"El caso establece actividad hostil no detectada."},{"text":"Un falso negativo.","feedback":"El control no reconoce un caso que sí era problemático."},{"text":"Un falso positivo.","feedback":"Ese afecta a un caso legítimo rechazado por error."}],"correct":2,"takeaway":"La aceptación por el control y la legitimidad real son datos distintos."},{"id":"d2m5q03","kind":"concepto","title":"El umbral tiene consecuencias","scenario":"Comparamos una regla moderada y otra más estricta.","prompt":"¿Qué efecto debemos comprobar al endurecer el filtro?","terms":["Umbral","Falso positivo","Falso negativo"],"options":[{"text":"Cómo cambian los casos hostiles que pasan y los legítimos que se rechazan.","feedback":"La medida puede modificar ambos tipos de error y el servicio."},{"text":"Solo que aumente el número total de bloqueos.","feedback":"Más bloqueos no garantizan menos daño a usuarios."},{"text":"Que el porcentaje de éxito suba automáticamente.","feedback":"El efecto depende de los datos y de las reglas."},{"text":"Únicamente el nombre del modo de protección.","feedback":"La etiqueta no demuestra el resultado."}],"correct":0,"takeaway":"Una regla más estricta debe valorarse por sus resultados y sus errores."},{"id":"d2m5q04","kind":"concepto","title":"A quién dividimos","scenario":"Queremos calcular la tasa de falsos positivos de una muestra etiquetada.","prompt":"¿Cuál es su denominador?","terms":["Tasa de falsos positivos","Denominador"],"options":[{"text":"Solo los casos hostiles que pasaron.","feedback":"Esos casos se relacionan con falsos negativos."},{"text":"El total de reglas del filtro.","feedback":"No es una población de solicitudes evaluadas."},{"text":"Todos los casos legítimos evaluados en esa muestra.","feedback":"La tasa mide qué fracción de los legítimos se rechazó por error."},{"text":"Todos los casos bloqueados, legítimos y hostiles.","feedback":"Eso mide otra proporción: el peso de falsos positivos entre bloqueos."}],"correct":2,"takeaway":"Elegid el denominador que corresponde a la pregunta."},{"id":"d2m5q05","kind":"concepto","title":"La muestra no es el planeta","scenario":"Probamos un filtro con solicitudes de un único campus y un único navegador.","prompt":"¿Qué límite debemos declarar?","terms":["Cobertura","Muestra contrastada"],"options":[{"text":"El navegador no puede influir nunca en un filtro.","feedback":"Las señales evaluadas pueden depender del cliente y su comportamiento."},{"text":"La prueba solo respalda ese alcance y necesita ampliarse para otras poblaciones relevantes.","feedback":"Otros usos pueden comportarse de forma distinta."},{"text":"El resultado se aplica sin cambios a toda la universidad.","feedback":"No se ha observado esa cobertura."},{"text":"Una muestra limitada carece de cualquier utilidad.","feedback":"Puede servir si sus límites están claros."}],"correct":1,"takeaway":"La cobertura determina hasta dónde podemos generalizar un resultado."},{"id":"d2m5q06","kind":"concepto","title":"Atender mientras corregimos","scenario":"Una regla bloquea a usuarios legítimos. Existe una vía alternativa autorizada y trazable.","prompt":"¿Cómo puede contribuir un control compensatorio?","terms":["Control compensatorio","Riesgo residual"],"options":[{"text":"Suprimiendo para siempre toda comprobación de identidad.","feedback":"Crear otra debilidad no es una compensación adecuada."},{"text":"Ocultando a los afectados del recuento.","feedback":"Cambiar la estadística no entrega servicio."},{"text":"Garantizando que no habrá más errores de ningún tipo.","feedback":"La alternativa también tiene condiciones y límites."},{"text":"Manteniendo atención con controles adecuados mientras se corrige y vigila el problema.","feedback":"Reduce consecuencias sin dar por eliminado el riesgo."}],"correct":3,"takeaway":"Una alternativa útil conserva servicio y responsabilidad."}]},{"id":"casos","label":"Decisiones","questions":[{"id":"d2m5q07","kind":"caso","title":"Ocho de cien","scenario":"Caso docente: probamos cien solicitudes legítimas conocidas. El filtro bloquea ocho.","prompt":"¿Cuál es la tasa de falsos positivos en esta muestra?","terms":["Tasa de falsos positivos"],"options":[{"text":"8 %.","feedback":"Ocho falsos positivos entre cien casos legítimos: 8/100."},{"text":"92 %.","feedback":"Ese es el porcentaje de legítimos que no fueron bloqueados."},{"text":"80 %.","feedback":"Se ha desplazado incorrectamente la escala del porcentaje."},{"text":"No se puede calcular aunque conozcamos todas las etiquetas.","feedback":"Las etiquetas y el recuento sí permiten este cálculo de la muestra."}],"correct":0,"takeaway":"En esta tasa el denominador es el conjunto legítimo evaluado.","visual":{"type":"metrics","items":[{"label":"Legítimas","value":"100"},{"label":"Bloqueadas por error","value":"8"}]}},{"id":"d2m5q08","kind":"caso","title":"El denominador cambia la pregunta","scenario":"Caso docente: de 100 legítimas, se bloquean 8. Además se bloquean correctamente 80 hostiles. Hay 88 bloqueos en total.","prompt":"¿Qué representa 8/88?","terms":["Denominador","Falso positivo"],"options":[{"text":"El porcentaje de estudiantes atendidos.","feedback":"Los bloqueos mezclan casos legítimos y hostiles y no equivalen a atención."},{"text":"La proporción de errores legítimos entre todos los bloqueos, aproximadamente 9,1 %.","feedback":"Es otra pregunta. La tasa de falsos positivos entre legítimos sigue siendo 8/100."},{"text":"La tasa de falsos positivos sobre las 100 legítimas.","feedback":"Ese cálculo exige dividir por 100, no por 88."},{"text":"La proporción de hostiles detectados entre todos los hostiles.","feedback":"No conocemos aquí el total de hostiles evaluados."}],"correct":1,"takeaway":"Dos proporciones pueden usar el mismo numerador y responder a preguntas distintas.","visual":{"type":"metrics","items":[{"label":"Legítimos bloqueados","value":"8"},{"label":"Hostiles bloqueados","value":"80"},{"label":"Bloqueos totales","value":"88"}]}},{"id":"d2m5q09","kind":"caso","title":"La web responde, el trámite no termina","scenario":"Caso docente: 1.000 estudiantes deben completar el trámite. Veinte quedan bloqueados por error y otros cien fallan después en la aplicación. El resto termina.","prompt":"¿Qué entrega de servicio conseguimos?","terms":["Capacidad útil","Eficacia"],"options":[{"text":"90 %, porque ignoramos los rechazos del filtro.","feedback":"También impiden completar la operación."},{"text":"100 %, porque todos llegaron a alguna pantalla.","feedback":"Llegar a una pantalla no equivale a terminar el trámite."},{"text":"880 de 1.000, un 88 %.","feedback":"Se descuentan 20 y 100 del total de 1.000. Los fallos son grupos distintos."},{"text":"98 %, porque solo contamos los veinte rechazos.","feedback":"Omite los cien fallos de aplicación."}],"correct":2,"takeaway":"El resultado útil recorre el proceso completo.","visual":{"type":"metrics","items":[{"label":"Necesitan trámite","value":"1.000"},{"label":"Bloqueados","value":"20"},{"label":"Fallan después","value":"100"}]}},{"id":"d2m5q10","kind":"caso","title":"Dos configuraciones, una necesidad","scenario":"Caso docente: con la misma población de 200 estudiantes, el modo A permite 180 matrículas válidas y el B permite 150. El objetivo es al menos 90 %.","prompt":"¿Qué configuración cumple el objetivo de servicio observado?","terms":["Comparación controlada","Eficacia"],"options":[{"text":"A, con 180/200 = 90 %. B queda en 75 %.","feedback":"El denominador común permite comparar el resultado solicitado."},{"text":"B, si su etiqueta dice protección máxima.","feedback":"La etiqueta no sustituye los resultados de servicio."},{"text":"Ambas, porque superan cien matrículas.","feedback":"La cantidad absoluta no basta para el umbral del 90 %."},{"text":"Ninguna, porque el objetivo exige siempre el 100 %.","feedback":"El umbral declarado es el 90 %."}],"correct":0,"takeaway":"Comparad resultados bajo el mismo alcance y criterio.","visual":{"type":"metrics","items":[{"label":"Población","value":"200"},{"label":"Modo A","value":"180"},{"label":"Modo B","value":"150"},{"label":"Objetivo","value":"90 %"}]}},{"id":"d2m5q11","kind":"caso","title":"La cola crece sin pedir permiso","scenario":"Caso docente: llegan 160 solicitudes legítimas por minuto. La aplicación completa 120. Empezamos sin cola y no hay abandonos ni rechazos.","prompt":"¿Cuántas quedan pendientes tras un minuto?","terms":["Cola","Cuello de botella"],"options":[{"text":"120 solicitudes.","feedback":"Ese es el número atendido, no el pendiente."},{"text":"160 solicitudes.","feedback":"Omite las operaciones completadas."},{"text":"Cero porque la red funciona.","feedback":"La capacidad de aplicación es insuficiente para esas entradas."},{"text":"40 solicitudes.","feedback":"Llegan 160 y terminan 120, así que quedan 40."}],"correct":3,"takeaway":"Una red disponible no evita la cola en otra etapa.","visual":{"type":"metrics","items":[{"label":"Llegan","value":"160/min"},{"label":"Terminan","value":"120/min"},{"label":"Inicial","value":"0"}]}},{"id":"d2m5q12","kind":"caso","title":"Capacidad suficiente, filtro demasiado severo","scenario":"Caso docente: la aplicación puede completar las 100 matrículas necesarias. El filtro bloquea por error a doce estudiantes y no hay otros fallos.","prompt":"¿Qué resultado deja esta configuración?","terms":["Falso positivo","Capacidad útil"],"options":[{"text":"90 % porque el objetivo redondea cualquier cifra cercana.","feedback":"No se ha autorizado ese redondeo ni tolerancia."},{"text":"12 % atendido.","feedback":"Doce es el grupo bloqueado, no el que completa."},{"text":"88 % atendido, por debajo del objetivo del 90 %.","feedback":"100 menos 12 son 88. La capacidad libre no recupera a los rechazados."},{"text":"100 % porque hay capacidad para todos.","feedback":"El filtro impide que doce utilicen esa capacidad."}],"correct":2,"takeaway":"Capacidad y acceso efectivo condicionan conjuntamente el servicio.","visual":{"type":"metrics","items":[{"label":"Capacidad","value":"100"},{"label":"Necesitan trámite","value":"100"},{"label":"Rechazados","value":"12"}]}},{"id":"d2m5q13","kind":"caso","title":"Novecientas solicitudes de cien personas","scenario":"Caso docente: cien estudiantes generan novecientos intentos por reintentos. Ochenta estudiantes distintos completan una matrícula válida.","prompt":"¿Qué porcentaje de alumnado ha sido atendido?","terms":["Denominador","Capacidad útil"],"options":[{"text":"100 %, porque cada estudiante intentó entrar.","feedback":"Intentar no equivale a completar la matrícula."},{"text":"80 %.","feedback":"La unidad del objetivo es estudiante distinto: 80/100."},{"text":"800 %, porque dividimos 800 intentos entre cien.","feedback":"Los intentos no equivalen a estudiantes atendidos."},{"text":"8,9 %, porque dividimos 80 entre 900.","feedback":"Ese denominador responde a otra pregunta sobre intentos."}],"correct":1,"takeaway":"El numerador y el denominador deben usar la unidad del objetivo.","visual":{"type":"metrics","items":[{"label":"Estudiantes","value":"100"},{"label":"Intentos","value":"900"},{"label":"Matriculados","value":"80"}]}},{"id":"d2m5q14","kind":"caso","title":"Solo miramos los rechazados","scenario":"Caso docente: revisamos cien solicitudes bloqueadas y confirmamos que quince eran legítimas. No sabemos cuántas solicitudes legítimas se evaluaron en total.","prompt":"¿Qué podemos afirmar?","terms":["Muestra contrastada","Tasa de falsos positivos"],"options":[{"text":"Ningún bloqueo fue correcto.","feedback":"La revisión confirma quince legítimos, no cien."},{"text":"El 15 % de los bloqueos revisados eran legítimos. Falta el denominador para la tasa global de falsos positivos.","feedback":"La muestra responde a la composición de bloqueos, no a todos los legítimos."},{"text":"La tasa global de falsos positivos es exactamente 15 %.","feedback":"No conocemos todos los casos legítimos evaluados."},{"text":"El 85 % de todos los estudiantes se matriculó.","feedback":"No estamos observando el alumnado completo ni la finalización."}],"correct":1,"takeaway":"La población seleccionada limita la interpretación del porcentaje."}]},{"id":"reto","label":"Reto final","questions":[{"id":"d2m5q15","kind":"reto","title":"El turno acaba en 180","scenario":"Reto final: 200 estudiantes necesitan matrícula y el objetivo es 90 %. Se han completado 176.","prompt":"¿Qué mínimo falta, manteniendo el mismo alcance?","terms":["Eficacia","Denominador"],"options":[{"text":"Veinticuatro obligatoriamente.","feedback":"Veinticuatro permitirían el 100 %, pero el mínimo es 180."},{"text":"Nada, porque 176 redondea a 180.","feedback":"No podemos sustituir operaciones reales por redondeo."},{"text":"Dieciocho porque el porcentaje empieza por nueve.","feedback":"La cantidad deriva de multiplicar la demanda por el objetivo."},{"text":"Cuatro matrículas válidas adicionales.","feedback":"El 90 % de 200 es 180. Faltan cuatro."}],"correct":3,"takeaway":"Un criterio numérico debe traducirse a operaciones reales.","visual":{"type":"metrics","items":[{"label":"Demanda","value":"200"},{"label":"Completadas","value":"176"},{"label":"Objetivo","value":"90 %"}]}},{"id":"d2m5q16","kind":"reto","title":"Detectamos seis de ocho","scenario":"Reto final: de ocho incidentes conocidos durante el periodo, seis se detectaron internamente. Puede haber incidentes aún desconocidos.","prompt":"¿Qué afirmación es exacta?","terms":["Denominador","Cobertura"],"options":[{"text":"Se detectó internamente el 75 % de los incidentes conocidos de ese periodo.","feedback":"6/8 = 75 %. El denominador no incluye lo que sigue desconocido."},{"text":"La organización detecta el 75 % de todos los ataques posibles.","feedback":"Generaliza fuera de la población conocida y del periodo."},{"text":"La eficacia de cada control es del 75 %.","feedback":"La cifra no atribuye el resultado a cada control."},{"text":"Solo hubo seis incidentes.","feedback":"El caso establece ocho conocidos."}],"correct":0,"takeaway":"Indicad el alcance conocido y no confundáis una métrica con una garantía general."},{"id":"d2m5q17","kind":"reto","title":"Los diez que faltan tienen nombre","scenario":"Reto final: se cumple el 90 % global, pero quedan diez estudiantes pendientes con un plazo próximo. Existe atención alternativa autorizada.","prompt":"¿Qué actuación gestiona el riesgo restante?","terms":["Riesgo residual","Control compensatorio","Trazabilidad"],"options":[{"text":"Declarar que el 90 % convierte a los restantes en irrelevantes.","feedback":"El umbral no elimina las consecuencias para personas concretas."},{"text":"Cerrar la atención sin revisar causas ni plazo.","feedback":"Mantiene riesgo sin seguimiento ni responsabilidad."},{"text":"Activar la alternativa, registrar cada pendiente y comprobar su resolución dentro del plazo.","feedback":"Cumplir el mínimo no elimina las necesidades del grupo restante."},{"text":"Borrar sus solicitudes para mejorar el porcentaje.","feedback":"Oculta la necesidad y cambia el denominador."}],"correct":2,"takeaway":"El mínimo cumplido y el riesgo residual deben comunicarse juntos."},{"id":"d2m5q18","kind":"reto","title":"La medalla no sustituye al servicio","scenario":"Reto final: una configuración obtiene muchos puntos por bloqueos, pero no alcanza el 90 % de alumnado atendido ni contrasta falsos positivos.","prompt":"¿Qué debemos concluir?","terms":["Eficacia","Muestra contrastada"],"options":[{"text":"Los puntos compensan automáticamente cualquier requisito incumplido.","feedback":"Una puntuación agregada puede ocultar fallos de una condición obligatoria."},{"text":"Basta con enseñar la cifra más alta al terminar.","feedback":"Seleccionar un indicador no prueba el resultado completo."},{"text":"No hace falta conocer qué usuarios fueron rechazados.","feedback":"Sin contraste no podemos valorar el daño sobre casos legítimos."},{"text":"La puntuación no demuestra que se hayan cumplido las condiciones de servicio y contraste.","feedback":"El objetivo contiene requisitos que deben verificarse directamente."}],"correct":3,"takeaway":"Una buena partida termina con un resultado explicable y comprobado."}]}],"sources":[{"title":"Material docente original, diapositivas 80–83 y 103–121","url":"https://blai3epascal.github.io/MEC1Ciber/ciberresiliencia/respuesta/?juego=5"}]}]}]};
